// ── TOGGLE MODO CONSULTA (Por Precificação / Por Produto) ─────────────────────
let _consultaPrecModo = 'precificacao';

function alternarModoConsultaPrec(modo) {
    _consultaPrecModo = modo;
    const btnPrecif = document.getElementById('btnConsultaModoPrecif');
    const btnProduto = document.getElementById('btnConsultaModoProduto');
    // suporte ao novo layout Bloomberg (cq-table-wrap) e ao legado (.table-container)
    const tabelaNormal = document.querySelector('#painel-consultaPrec .cq-table-wrap:not(#bodyConsultaPrecPorProduto)')
                      || document.querySelector('#painel-consultaPrec .table-container');
    const paginacao = document.getElementById('paginacaoConsultaPrec');
    const porProduto = document.getElementById('bodyConsultaPrecPorProduto');

    if (modo === 'produto') {
        if (btnPrecif) { btnPrecif.classList.remove('active'); }
        if (btnProduto) { btnProduto.classList.add('active'); }
        if (tabelaNormal) tabelaNormal.style.display = 'none';
        if (paginacao) paginacao.style.display = 'none';
        if (porProduto) porProduto.style.display = 'block';
        renderizarConsultaPorProduto();
    } else {
        if (btnPrecif) { btnPrecif.classList.add('active'); }
        if (btnProduto) { btnProduto.classList.remove('active'); }
        if (tabelaNormal) tabelaNormal.style.display = '';
        if (paginacao) paginacao.style.display = '';
        if (porProduto) porProduto.style.display = 'none';
    }
}

function renderizarConsultaPorProduto() {
    const tbody = document.getElementById('bodyConsultaPrecPorProdutoTabela');
    if (!tbody) return;

    const precificacoesCliente = estoque.precificacoesCliente || [];
    if (precificacoesCliente.length === 0) {
        tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;color:#94a3b8;padding:30px">Nenhuma precificação salva</td></tr>`;
        return;
    }

    // Agrupa por produto
    const porProduto = {};
    precificacoesCliente.forEach(precif => {
        const itens = precif.itens || [];
        itens.forEach(item => {
            const nome = item.produto || item.nome || '—';
            if (!porProduto[nome]) porProduto[nome] = [];
            porProduto[nome].push({
                valorFinal: parseFloat(item.valorFinal || item.precoFinal || 0),
                data: precif.dataCriacao || precif.data || null,
                cliente: precif.nomeCliente || precif.cliente || '—',
                id: precif.id || null,
                quantidade: item.quantidade || item.qtd || 1,
            });
        });
    });

    const fmt = v => 'R$ ' + _fmtMoeda(v);

    const linhas = Object.keys(porProduto).sort().map(nome => {
        const registros = porProduto[nome].filter(r => r.valorFinal > 0);
        if (registros.length === 0) return '';
        const valores = registros.map(r => r.valorFinal);
        const menor = Math.min(...valores);
        const maior = Math.max(...valores);
        // Último = mais recente por data
        const ordenados = [...registros].sort((a, b) => {
            const da = a.data ? new Date(a.data) : new Date(0);
            const db = b.data ? new Date(b.data) : new Date(0);
            return db - da;
        });
        const ultimo = ordenados[0];
        const ultimaData = ultimo.data ? formatDateToDDMMYYYY(new Date(ultimo.data)) : '—';
        const nomeId = nome.replace(/[^a-z0-9]/gi, '_');

        const detalheRows = ordenados.map(r => {
            const dataFmt = r.data ? formatDateToDDMMYYYY(new Date(r.data)) : '—';
            return `<tr style="background:#f8fafc">
                <td colspan="2" style="padding:6px 16px 6px 32px;color:#475569">${_escapeHtml(r.cliente)}</td>
                <td style="text-align:center;padding:6px 8px;color:#64748b">${dataFmt}</td>
                <td style="text-align:center;padding:6px 8px;color:#64748b">${r.quantidade}</td>
                <td style="text-align:right;padding:6px 8px;font-weight:600;color:#1e3a5f">${fmt(r.valorFinal)}</td>
                <td colspan="2"></td>
            </tr>`;
        }).join('');

        return `
            <tr id="prod-hist-row-${nomeId}">
                <td style="text-align:left;padding-left:12px;font-weight:600">${_escapeHtml(nome)}</td>
                <td style="text-align:center">${registros.length}</td>
                <td style="text-align:right;color:#16a34a;font-weight:600">${fmt(menor)}</td>
                <td style="text-align:right;color:#dc2626;font-weight:600">${fmt(maior)}</td>
                <td style="text-align:right;font-weight:700;color:#c9a227">${fmt(ultimo.valorFinal)}</td>
                <td style="text-align:center;color:#64748b">${ultimaData}</td>
                <td style="text-align:center">
                    <button class="btn btn-outline btn-sm" onclick="toggleDetalheProdutoConsulta('${nomeId}')">Ver detalhes</button>
                </td>
            </tr>
            <tr id="prod-hist-detalhe-${nomeId}" style="display:none">
                <td colspan="7" style="padding:0">
                    <table style="width:100%;border-top:1px solid #e2e8f0">
                        <thead><tr style="background:#f1f5f9">
                            <th colspan="2" style="text-align:left;padding:6px 16px 6px 32px;font-size:0.78rem">Cliente</th>
                            <th style="text-align:center;padding:6px 8px;font-size:0.78rem">Data</th>
                            <th style="text-align:center;padding:6px 8px;font-size:0.78rem">Qtd</th>
                            <th style="text-align:right;padding:6px 8px;font-size:0.78rem">Valor Final</th>
                            <th colspan="2"></th>
                        </tr></thead>
                        <tbody>${detalheRows}</tbody>
                    </table>
                </td>
            </tr>
        `;
    }).join('');

    tbody.innerHTML = linhas || `<tr><td colspan="7" style="text-align:center;color:#94a3b8;padding:30px">Nenhum produto encontrado</td></tr>`;
}

function toggleDetalheProdutoConsulta(nomeId) {
    const row = document.getElementById('prod-hist-detalhe-' + nomeId);
    if (!row) return;
    row.style.display = row.style.display === 'none' ? 'table-row' : 'none';
}

function carregarDados() {
    let dadosSalvos = null;
    try {
        const lzRaw = localStorage.getItem('estoqueArmasV2_lz');
        if (lzRaw && window.LZString) {
            dadosSalvos = LZString.decompressFromUTF16(lzRaw);
        }
    } catch (e) { _catchSilencioso(e, 'carregarDados'); }
    if (!dadosSalvos) dadosSalvos = localStorage.getItem('estoqueArmasV2');
    if (dadosSalvos) {
        try {
            estoque = JSON.parse(dadosSalvos);
        } catch (e) {
            console.error('Falha ao interpretar localStorage estoqueArmasV2:', e);
            localStorage.removeItem('estoqueArmasV2');
            localStorage.removeItem('estoqueArmasV2_lz');
            estoque = {
                produtos: [],
                representantes: ['KOLTE', 'ISA', 'LC', 'ADES', 'FL', 'IMBEL'],
                registroVendas: [],
                registroDistribuicao: [],
                registroDevolucoes: [],
                registroEntradas: [],
                controleEnvio: {},
                auditoriaVendas: [],
                fechamentosComissoes: [],
                clientes: [],
                propostas: [],
                precificacao: {},
                precificacaoConfig: null,
                precificacoesCliente: [],
                parametrosTabelaVenda: { versaoAtiva: null, versoes: [] }
            };
        }
        // Garantir que representantes existe — sem isso, atualizarEstatisticas()
        // quebra em "estoque.representantes.forEach" (visto em saves antigos/
        // incompletos, que nunca chegaram a gravar este campo).
        if (!Array.isArray(estoque.representantes)) {
            estoque.representantes = ['KOLTE', 'ISA', 'LC', 'ADES', 'FL', 'IMBEL'];
        }
        // Garantir que registroVendas existe
        if (!estoque.registroVendas) {
            estoque.registroVendas = [];
        }
        // Garantir que registroDistribuicao existe
        if (!estoque.registroDistribuicao) {
            estoque.registroDistribuicao = [];
        }
        // Garantir que registroDevolucoes existe
        if (!estoque.registroDevolucoes) {
            estoque.registroDevolucoes = [];
        }
        // Garantir que registroEntradas existe (novidade)
        if (!estoque.registroEntradas) {
            estoque.registroEntradas = [];
        }
        // Garantir que controleEnvio existe
        if (!estoque.controleEnvio) {
            estoque.controleEnvio = {};
        }
        if (!Array.isArray(estoque.auditoriaVendas)) {
            estoque.auditoriaVendas = [];
        }
        if (!Array.isArray(estoque.fechamentosComissoes)) {
            estoque.fechamentosComissoes = [];
        }
        if (!Array.isArray(estoque.clientes)) {
            estoque.clientes = [];
        }
        clientes = estoque.clientes;
        if (!Array.isArray(estoque.propostas)) {
            estoque.propostas = [];
        }
        propostas = estoque.propostas;
        if (!Array.isArray(estoque.precificacoesCliente)) {
            estoque.precificacoesCliente = [];
        }
        estoque.precificacoesCliente = normalizarPrecificacoesCliente(estoque.precificacoesCliente);
        if (!Array.isArray(estoque.tabelaCI)) {
            estoque.tabelaCI = [];
        }
        if (!estoque.tabelaPrecoEstado || typeof estoque.tabelaPrecoEstado !== 'object') {
            estoque.tabelaPrecoEstado = {};
        }
        if (!estoque.parametrosTabelaVenda || typeof estoque.parametrosTabelaVenda !== 'object') {
            estoque.parametrosTabelaVenda = { versaoAtiva: null, versoes: [] };
        }
        // Migração do formato antigo (taxa/roi/roiPorNCM flat → versões)
        {
            const ptv = estoque.parametrosTabelaVenda;
            if (!ptv.versoes) {
                const taxaAnt = ptv.taxa;
                const roiAnt  = ptv.roi;
                const roiNCMAnt = ptv.roiPorNCM || {};
                const params = {};
                Object.entries(roiNCMAnt).forEach(([ncm, roi]) => { params[ncm] = { taxa: taxaAnt || null, roi }; });
                const v1 = { id: Date.now(), data: new Date().toISOString(), descricao: 'Versão inicial (migrada)', params, taxaPadrao: taxaAnt || null, roiPadrao: roiAnt || null };
                ptv.versoes = [v1];
                ptv.versaoAtiva = v1.id;
                delete ptv.taxa; delete ptv.roi; delete ptv.roiPorNCM;
            }
        }
        // Carregar configuração de alertas se presente
        try {
            const cfg = localStorage.getItem('configAlertas');
            if (cfg) configAlertas = JSON.parse(cfg);
        } catch (e) { console.warn('Erro ao carregar configAlertas:', e); }
        // Migrar produtos antigos para nova propriedade `estoqueConsolidado` quando necessário
        try {
            if (Array.isArray(estoque.produtos)) {
                estoque.produtos.forEach(p => {
                    if (typeof p.estoqueConsolidado === 'undefined' || p.estoqueConsolidado === null) {
                        // fallback: somar todas as chaves de distribuição armazenadas
                        try {
                            const totalDisp = Object.keys(p.distribuicao || {}).reduce((s, k) => s + (Number(p.distribuicao[k]) || 0), 0);
                            p.estoqueConsolidado = totalDisp;
                        } catch (inner) { p.estoqueConsolidado = 0; }
                    }
                    // padronizar: manter distribuições por representantes; zerar/ignorar IMBEL armazenado (IMBEL será calculado dinamicamente a partir do consolidado)
                    try { if (!p.distribuicao) p.distribuicao = {}; p.distribuicao.IMBEL = 0; } catch (e) { _catchSilencioso(e, 'carregarDados'); }
                });
            }
        } catch (e) { console.warn('Migração estoqueConsolidado falhou:', e); }
        // Limpar campo componente que tenha sido gravado com o texto do cabeçalho por importação defeituosa
        try {
            if (Array.isArray(estoque.produtos)) {
                estoque.produtos.forEach(p => {
                    const c = (p.componente || '').trim().toUpperCase();
                    if (c === 'COMPONENTE' || c === 'COMPONENT') p.componente = '';
                });
            }
        } catch (e) { console.warn('Limpeza componente falhou:', e); }
        if (estoque.precificacao && typeof estoque.precificacao === 'object') {
            precificacao = estoque.precificacao;
        } else {
            precificacao = {};
            estoque.precificacao = precificacao;
        }
        // carregar precificações por cliente, se presente
        try { precificacoesCliente = normalizarPrecificacoesCliente(estoque.precificacoesCliente); } catch (e) { precificacoesCliente = []; }
        if (!precificacoesCliente || !precificacoesCliente.length) {
            try {
                const rawEspelho = localStorage.getItem('precificacoesClienteBackupV1');
                const espelho = normalizarPrecificacoesCliente(rawEspelho ? JSON.parse(rawEspelho) : []);
                if (espelho.length) precificacoesCliente = espelho;
            } catch (e) { _catchSilencioso(e, 'carregarDados'); }
        }
        estoque.precificacoesCliente = precificacoesCliente;
        try { atualizarIndicadoresPrecificacao(); } catch (e) { _catchSilencioso(e, 'carregarDados'); }
        tabelaAliquotas = (estoque.tabelaAliquotas && typeof estoque.tabelaAliquotas === 'object')
            ? estoque.tabelaAliquotas
            : {};
        tabelaICMS = Array.isArray(estoque.tabelaICMS) ? estoque.tabelaICMS : [];
        categoriaPorProduto = (estoque.categoriaPorProduto && typeof estoque.categoriaPorProduto === 'object')
            ? estoque.categoriaPorProduto
            : {};
        // Reconstruir distribuições e vendas por produto a partir dos registros (corrige inconsistências legadas)
        try { normalizarProdutoIdsNosRegistros(); } catch (e) { /* ignore */ }
        try { reconstruirDistribuicaoAPartirDeRegistros(); } catch (e) { /* ignore */ }
        try { reconstruirVendasAPartirDeRegistros(); } catch (e) { /* ignore */ }

        // Restore IMBEL data if it was saved in the main object
        try {
            if (estoque && estoque._imbelData) {
                const existing = localStorage.getItem(IMBEL_KEY);
                // Only restore if IMBEL localStorage is empty or default
                if (!existing || existing === '{"produtos":[],"movimentacoes":[]}') {
                    localStorage.setItem(IMBEL_KEY, JSON.stringify(estoque._imbelData));
                    console.info('IMBEL: dados restaurados do backup principal');
                }
            }
        } catch (e) { _catchSilencioso(e, 'carregarDados'); }
    } else {
        estoque = {};
        estoque.produtos = dadosIniciais.map((item, index) => ({
            id: index + 1,
            nome: item.nome,
            preco: item.preco,
            distribuicao: { ...item.distribuicao },
            vendas: { ...item.vendas }
        }));
        estoque.representantes = ['KOLTE', 'ISA', 'LC', 'ADES', 'FL', 'IMBEL'];
        estoque.registroVendas = [];
        estoque.registroDistribuicao = [];
        estoque.registroDevolucoes = [];
        estoque.registroEntradas = [];
        estoque.controleEnvio = {};
        estoque.auditoriaVendas = [];
        estoque.fechamentosComissoes = [];
        estoque.clientes = [];
        clientes = estoque.clientes;
        estoque.precificacao = {};
        estoque.precificacaoConfig = null;
        precificacao = estoque.precificacao;
        tabelaAliquotas = {};
        tabelaICMS = [];
        categoriaPorProduto = {};
        estoque.precificacoesCliente = [];
        estoque.tabelaAliquotas = tabelaAliquotas;
        estoque.tabelaICMS = tabelaICMS;
        estoque.categoriaPorProduto = categoriaPorProduto;
        salvarDados();
    }
}

// Debounce para localStorage — evita 60 escritas seguidas
let __localSaveTimer = null;
function agendarSalvarLocal() {
    if (__localSaveTimer) clearTimeout(__localSaveTimer);
    __localSaveTimer = setTimeout(() => {
        __localSaveTimer = null;
        _executarSalvarLocal();
    }, 300); // 300ms de espera
}

function _executarSalvarLocal() {
    // Sincronizar aliases mutáveis de volta para estoque antes de persistir
    // (clientes e propostas são arrays compartilhados que podem ter sido mutados diretamente)
    if (Array.isArray(clientes)) estoque.clientes = clientes;
    if (Array.isArray(propostas)) estoque.propostas = propostas;
    // Sincroniza os objetos de precificação no estado persistido
    estoque.precificacao = precificacao;
    estoque.tabelaAliquotas = tabelaAliquotas;
    estoque.tabelaICMS = tabelaICMS;
    estoque.categoriaPorProduto = categoriaPorProduto;
    // Persistir precificações salvas por cliente
    try { estoque.precificacoesCliente = precificacoesCliente || []; } catch (e) { _catchSilencioso(e, '_executarSalvarLocal'); }
    // Persistir tabelas de impostos editáveis
    try { estoque.impostosEditaveis = impostosEditaveis || {}; } catch (e) { _catchSilencioso(e, '_executarSalvarLocal'); }
    try { estoque.icmsEditavelPJ = icmsEditavelPJ || {}; } catch (e) { _catchSilencioso(e, '_executarSalvarLocal'); }
    try { estoque.icmsEditavelPF = icmsEditavelPF || {}; } catch (e) { _catchSilencioso(e, '_executarSalvarLocal'); }
    // marca hora local de atualização para comparação com o remoto
    // Quando carregando do cloud, preservar o timestamp remoto (já setado em carregarDoCloud)
    // para que onSnapshot não compare com um "now()" mais recente que o remoto
    try { if (!window._carregandoDoCloud) estoque._localUpdatedAt = new Date().toISOString(); } catch (e) { _catchSilencioso(e, '_executarSalvarLocal'); }
    // Include IMBEL data in main save
    try {
        const imbelData = loadImbel();
        estoque._imbelData = imbelData;
    } catch (e) { _catchSilencioso(e, '_executarSalvarLocal'); }
    try {
        const json = JSON.stringify(estoque);
        if (window.LZString) {
            const compressed = LZString.compressToUTF16(json);
            localStorage.setItem('estoqueArmasV2_lz', compressed);
            localStorage.setItem('estoqueArmasV2', json); // manter plain como fallback
        } else {
            localStorage.setItem('estoqueArmasV2', json);
        }
    } catch (e) {
        try { localStorage.setItem('estoqueArmasV2', JSON.stringify(estoque)); } catch(e2) {}
    }
    try { localStorage.setItem('precificacoesClienteBackupV1', JSON.stringify(precificacoesCliente || [])); } catch (e) { _catchSilencioso(e, '_executarSalvarLocal'); }
    // Sem o try/catch, uma falha aqui (ex.: KPI de tela ausente) interrompia a
    // função antes de agendar o save no cloud logo abaixo — a UI não crashava
    // visivelmente, mas o cloud nunca era acionado.
    try { atualizarEstatisticas(); } catch (e) { _catchSilencioso(e, '_executarSalvarLocal'); }

    // agendar salvamento no cloud (debounced) se habilitado
    // Não re-enviar ao cloud quando estamos apenas persistindo dados recebidos do cloud
    try { if (!window._carregandoDoCloud) scheduleCloudSaveDebounced(); } catch (e) { _catchSilencioso(e, '_executarSalvarLocal'); }
    try {
        if (!window._cloudSyncedRecently && !window._carregandoDoCloud) window._dadosAlterados = true;
    } catch (e) { _catchSilencioso(e, '_executarSalvarLocal'); }
}

function salvarDados(opcoes = {}) {
    // Não marcar como alterado se viemos de uma carga do cloud (evita bloquear sync futuro)
    if (!window._carregandoDoCloud) {
        try { window._dadosAlterados = true; } catch (e) { _catchSilencioso(e, 'salvarDados'); }
        // Registrar edição real do usuário (só após init completa — não durante renderizações iniciais)
        if (window._appInitialized) {
            try { window._userHasEdited = true; } catch (e) { _catchSilencioso(e, 'salvarDados'); }
        }
    }
    if (opcoes && opcoes.imediato) {
        if (__localSaveTimer) { clearTimeout(__localSaveTimer); __localSaveTimer = null; }
        _executarSalvarLocal();
    } else {
        agendarSalvarLocal();
    }
}

// =============================
// Controle de versão local
// =============================
function getLocalUpdatedAt() {
    try {
        const v = localStorage.getItem('_cloudUpdatedAt');
        return v ? new Date(v) : null;
    } catch(e) { return null; }
}

function setLocalUpdatedAt(date) {
    try {
        localStorage.setItem('_cloudUpdatedAt', date instanceof Date ? date.toISOString() : date);
    } catch (e) { _catchSilencioso(e, 'setLocalUpdatedAt'); }
}

// =============================
// Funções para salvar/carregar no Firestore
// =============================
async function salvarNoCloud() {
    if (!window.firestoreDB) {
        console.warn('Firestore não inicializado. Impossível salvar no cloud.');
        return false;
    }
    const indicator = document.getElementById('cloudSaveIndicator');
    if (indicator) { indicator.textContent = '☁️ Salvando...'; indicator.style.color = '#d97706'; }
    try {
        // Garantir que estoque reflete o estado atual das variáveis globais antes de salvar
        if (Array.isArray(precificacoesCliente)) estoque.precificacoesCliente = precificacoesCliente;
        if (Array.isArray(clientes)) estoque.clientes = clientes;
        if (Array.isArray(propostas)) estoque.propostas = propostas;
        // Incluir dados IMBEL no backup Cloud (pegar do localStorage antes de enviar)
        try {
            const imbelDataToSave = (typeof loadImbel === 'function') ? loadImbel() : null;
            if (imbelDataToSave) estoque._imbelData = imbelDataToSave;
        } catch (e) { /* ignore */ }
        const docRef = window.firestoreDB.collection('app_data').doc('latest');
        // Escrita dupla (ver cloud-store.js): grava os três documentos por
        // módulo — app_data/estoque, /crm, /ponto — e também o legado
        // app_data/latest, no formato exato de antes. Enquanto o legado
        // continuar sendo escrito, voltar ao código anterior é seguro e não
        // perde nada. Os campos abaixo já vivem dentro de `estado`; seguem
        // replicados no topo do documento legado só por compatibilidade.
        await CloudStore.salvarComEscritaDupla(window.firestoreDB, firebase, estoque, {
            precificacao,
            precificacoesCliente: precificacoesCliente || [],
            tabelaAliquotas,
            tabelaICMS,
            categoriaPorProduto,
            impostosEditaveis: impostosEditaveis || {},
            icmsEditavelPJ: icmsEditavelPJ || {},
            icmsEditavelPF: icmsEditavelPF || {}
        });
        // ler o documento para obter o updatedAt do servidor
            try {
            const savedDoc = await docRef.get();
            const d = savedDoc && savedDoc.exists ? savedDoc.data() : null;
            const updatedAt = d && d.updatedAt ? d.updatedAt.toDate() : new Date();
            updateFirestoreStatus(true, updatedAt, 'Cloud: salvo');
        } catch (inner) {
            updateFirestoreStatus(true, new Date(), 'Cloud: salvo');
        }
        if (indicator) {
            indicator.textContent = '✅ Salvo';
            indicator.style.color = '#16a34a';
            setTimeout(() => { if (indicator) indicator.textContent = ''; }, 3000);
        }
        try {
            window._cloudSyncedRecently = true;
            window._dadosAlterados = false;
            // Guardar o momento exato do save — ignorar snapshots por 10s após salvar
            window._lastCloudSaveAt = Date.now();
            try {
                const savedDoc2 = await docRef.get();
                const d2 = savedDoc2 && savedDoc2.exists ? savedDoc2.data() : null;
                window._lastCloudSaveTimestamp = d2 && d2.updatedAt ? d2.updatedAt.toDate().getTime() : Date.now();
            } catch(e) { window._lastCloudSaveTimestamp = Date.now(); }
            if (__cloudSyncResetTimer) clearTimeout(__cloudSyncResetTimer);
            __cloudSyncResetTimer = setTimeout(() => { window._cloudSyncedRecently = false; window._lastCloudSaveAt = 0; }, 30000);
        } catch (e) { _catchSilencioso(e, 'salvarNoCloud'); }
        console.debug('Dados salvos no Firestore (coleção app_data / doc latest)');
        return true;
    } catch (e) {
        console.error('Erro salvando no Firestore:', e);
        // Detectar esgotamento de writes no Firestore e pausar auto-save temporariamente
        try {
            const errMsg = (e && (e.code || e.message || e.toString())) ? (e.code || e.message || e.toString()) : '';
            if (errMsg && (errMsg.indexOf('resource-exhausted') !== -1 || errMsg.indexOf('exhausted') !== -1)) {
                console.warn('Firestore resource-exhausted detectado — pausando auto-save por 60s.');
                window.__AUTO_SAVE_CLOUD = window.__AUTO_SAVE_CLOUD || {};
                window.__AUTO_SAVE_CLOUD.enabled = false;
                try { if (typeof mostrarNotificacao === 'function') mostrarNotificacao('Auto-save pausado por 1 minuto devido a limites do Firestore.', 'warning'); } catch (_) { _catchSilencioso(_, 'salvarNoCloud'); }
                setTimeout(() => {
                    try { window.__AUTO_SAVE_CLOUD.enabled = true; } catch (_) { _catchSilencioso(_, 'salvarNoCloud'); }
                }, 60000);
            }
        } catch (inner) { console.warn('Erro ao processar erro do Firestore:', inner); }

        updateFirestoreStatus(false, null, 'Cloud: erro ao salvar');
        if (indicator) { indicator.textContent = '❌ Erro ao salvar'; indicator.style.color = '#dc2626'; }
        return false;
    }
}

// UI wrappers for manual save/load triggered by user buttons
async function salvarNoCloudUI() {
    if (typeof requireAdminOrNotify === 'function' && !requireAdminOrNotify()) return false;
    if (typeof showProgressBar === 'function') showProgressBar('Salvando no Cloud...');
    try {
        mostrarNotificacao('Salvando dados no cloud...', 'info');
        const ok = await salvarNoCloud();
        if (ok) mostrarNotificacao('Dados salvos no Firestore com sucesso.', 'success');
        else mostrarNotificacao('Falha ao salvar no Firestore. Veja o console para detalhes.', 'error');
        return ok;
    } catch (e) {
        console.error('salvarNoCloudUI erro:', e);
        mostrarNotificacao('Erro ao salvar no cloud.', 'error');
        return false;
    } finally {
        if (typeof hideProgressBar === 'function') hideProgressBar();
    }
}

async function carregarDoCloudUI() {
    if (typeof requireAdminOrNotify === 'function' && !requireAdminOrNotify()) return false;
    if (typeof showProgressBar === 'function') showProgressBar('Carregando do Cloud...');
    try {
        mostrarNotificacao('Carregando dados do cloud...', 'info');
        // Resetar flag antes do carregamento manual para não bloquear
        window._dadosAlterados = false;
        const ok = await carregarDoCloud({ confirmOverwrite: false });
        if (ok) mostrarNotificacao('✅ Dados carregados do Cloud com sucesso.', 'success');
        else mostrarNotificacao('Nenhum backup encontrado no Cloud ou falha ao carregar.', 'warning');
        return ok;
    } catch (e) {
        console.error('carregarDoCloudUI erro:', e);
        mostrarNotificacao('Erro ao carregar do cloud.', 'error');
        return false;
    } finally {
        if (typeof hideProgressBar === 'function') hideProgressBar();
    }
}

async function carregarDoCloud({confirmOverwrite=true} = {}) {
    if (!window.firestoreDB) {
        console.warn('Firestore não inicializado. Impossível carregar do cloud.');
        return false;
    }
    window._carregandoDoCloud = true;
    try {
        // Lê da fonte mais recente (documentos por módulo ou o legado),
        // sempre no mesmo formato de antes — ver lerEstadoCompativel em
        // cloud-store.js. O restante desta função não muda.
        const { data, origem } = await CloudStore.lerEstadoCompativel(window.firestoreDB);
        if (!data) {
            console.warn('Nenhum backup encontrado no Firestore.');
            updateFirestoreStatus(true, null, 'Cloud: pronto (sem backup)');
            return false;
        }
        if (!data.estado) {
            console.warn('Documento encontrado não contém campo estado.');
            return false;
        }
        console.debug('carregarDoCloud: dados vindos de', origem);
        // obter timestamp de atualização remoto se disponível
        try {
            const updatedAt = data.updatedAt ? data.updatedAt.toDate() : null;
            updateFirestoreStatus(true, updatedAt, 'Cloud: carregado');
        } catch (inner) { updateFirestoreStatus(true, null, 'Cloud: carregado'); }
        if (confirmOverwrite) {
            const ok = confirm('Carregar dados do cloud irá substituir os dados locais. Deseja continuar?');
            if (!ok) { window._carregandoDoCloud = false; return false; }
        }
        estoque = data.estado;
        try { if (window.CrmStore) window.CrmStore.ensureCrmDefault(); } catch (e) { console.error('CRM ensureCrmDefault (cloud):', e); }
        try { if (window.PontoStore) window.PontoStore.ensurePontoDefault(); } catch (e) { console.error('Ponto ensurePontoDefault (cloud):', e); }
        try { if (window.ProcessosStore) window.ProcessosStore.ensureProcessosDefault(); } catch (e) { console.error('Processos ensureProcessosDefault (cloud):', e); }
        // Sincronizar _localUpdatedAt com o timestamp remoto para evitar re-trigger do onSnapshot
        try {
            const tsRemoto = data.updatedAt ? data.updatedAt.toDate().toISOString() : new Date().toISOString();
            estoque._localUpdatedAt = tsRemoto;
        } catch (e) { _catchSilencioso(e, 'carregarDoCloud'); }
        // Restaurar dados IMBEL salvos no backup principal (se existirem)
        try {
            if (data && data.estado && data.estado._imbelData) {
                try { localStorage.setItem(IMBEL_KEY, JSON.stringify(data.estado._imbelData)); console.info('IMBEL: restaurado do Cloud'); } catch (e) { console.warn('IMBEL: falha ao restaurar do Cloud', e); }
            } else if (estoque && estoque._imbelData) {
                try { localStorage.setItem(IMBEL_KEY, JSON.stringify(estoque._imbelData)); console.info('IMBEL: restaurado do backup principal'); } catch (e) { /* ignore */ }
            }
        } catch (e) { _catchSilencioso(e, 'carregarDoCloud'); }
        const precifsCloudFinal = (data.precificacoesCliente && data.precificacoesCliente.length)
            ? data.precificacoesCliente
            : (estoque.precificacoesCliente || []);
        estoque.precificacoesCliente = normalizarPrecificacoesCliente(precifsCloudFinal);
        precificacoesCliente = estoque.precificacoesCliente;
        try { atualizarIndicadoresPrecificacao(); } catch (e) { _catchSilencioso(e, 'carregarDoCloud'); }
        try { localStorage.setItem('precificacoesClienteBackupV1', JSON.stringify(precificacoesCliente || [])); } catch (e) { _catchSilencioso(e, 'carregarDoCloud'); }
        if (!Array.isArray(estoque.auditoriaVendas)) estoque.auditoriaVendas = [];
        if (!Array.isArray(estoque.fechamentosComissoes)) estoque.fechamentosComissoes = [];
        if (!Array.isArray(estoque.clientes)) estoque.clientes = [];
        clientes = estoque.clientes;
        if (!Array.isArray(estoque.propostas)) estoque.propostas = [];
        propostas = estoque.propostas;
        if (estoque.precificacao && typeof estoque.precificacao === 'object') precificacao = estoque.precificacao;
        else { estoque.precificacao = {}; precificacao = estoque.precificacao; }

        precificacao = (data.precificacao && typeof data.precificacao === 'object')
            ? data.precificacao
            : (estoque.precificacao || {});
        tabelaAliquotas = (data.tabelaAliquotas && typeof data.tabelaAliquotas === 'object')
            ? data.tabelaAliquotas
            : (estoque.tabelaAliquotas || {});
        tabelaICMS = Array.isArray(data.tabelaICMS)
            ? data.tabelaICMS
            : (Array.isArray(estoque.tabelaICMS) ? estoque.tabelaICMS : []);
        categoriaPorProduto = (data.categoriaPorProduto && typeof data.categoriaPorProduto === 'object')
            ? data.categoriaPorProduto
            : (estoque.categoriaPorProduto || {});
        try { inicializarImpostosPreDefinidos(); } catch (e) { console.warn('Inicializar impostos predefinidos após cloud falhou:', e); }

        salvarDados();
        renderizarTabela();
        renderizarDashboard();
        renderizarRegistroVendas();
        renderizarRegistroDistribuicao();
        renderizarControleEnvio();
        renderizarClientes();
        atualizarKPIsClientes();
        atualizarDatalistClientes();
        renderizarPropostas();
        atualizarKPIsPropostas();
        if (abaAtiva === 'precificacao') renderizarPrecificacao();
        atualizarSelectsProdutos();
        atualizarSelectsRelatorios();
        try {
            // Detectar se a aba de Precificação está visível
            const tabPrecif = document.querySelector('#tab-precificacao');
            const tabPrecifVisivel = tabPrecif && (
                tabPrecif.style.display !== 'none' &&
                tabPrecif.classList.contains('active') ||
                tabPrecif.offsetParent !== null
            );

            if (tabPrecifVisivel) {
                // Tentar renderizar todas as subabas de precificação que possam estar ativas
                try { renderizarConsultaPrecificacao && renderizarConsultaPrecificacao(); } catch (e) { _catchSilencioso(e, 'carregarDoCloud'); }
                try { renderizarRastreabilidade && renderizarRastreabilidade(); } catch (e) { _catchSilencioso(e, 'carregarDoCloud'); }
            } else {
                // Marcar flag para renderizar quando a aba for aberta
                window._precificacaoPendenteRender = true;
            }
        } catch(e) { console.error('Erro re-render precif:', e); }
        console.debug('Dados carregados do Firestore com sucesso.');
        // Forçar re-render das abas de precificação após carregamento completo
        try {
            precificacoesCliente = Array.isArray(estoque.precificacoesCliente)
                ? estoque.precificacoesCliente
                : [];
            setTimeout(() => {
                try {
                    renderizarConsultaPrecificacao && renderizarConsultaPrecificacao();
                    renderizarRastreabilidade && renderizarRastreabilidade();
                } catch (e) { _catchSilencioso(e, 'carregarDoCloud'); }
            }, 400);
        } catch (e) { _catchSilencioso(e, 'carregarDoCloud'); }
        window._carregandoDoCloud = false;
        window._dadosAlterados = false;
        window._userHasEdited = false;
        return true;
    } catch (e) {
        console.error('Erro carregando do Firestore:', e);
        window._carregandoDoCloud = false;
        return false;
    }
}

// Carrega automaticamente do cloud se o documento remoto for mais recente que o local
async function carregarDoCloudAuto() {
    if (!window.firestoreDB) return false;
    // Evitar leitura sem autenticação (causa Missing or insufficient permissions)
    try {
        if (!firebase || !firebase.auth || !firebase.auth().currentUser) {
            updateFirestoreStatus(true, null, 'Cloud: aguardando login');
            return false;
        }
    } catch (e) {
        return false;
    }
    window._carregandoDoCloud = true;
    try {
        // Mesma troca de fonte de carregarDoCloud (ver cloud-store.js).
        const { data } = await CloudStore.lerEstadoCompativel(window.firestoreDB);
        if (!data || !data.estado) { window._carregandoDoCloud = false; return false; }
        const remoteUpdated = data.updatedAt ? data.updatedAt.toDate().getTime() : null;
        const localUpdated = estoque._localUpdatedAt ? new Date(estoque._localUpdatedAt).getTime() : 0;
        // Não sobrescrever se há alterações locais pendentes não sincronizadas
        if (window._dadosAlterados) { window._carregandoDoCloud = false; return false; }
        if (remoteUpdated && remoteUpdated > localUpdated + 1000) {
            // substituir local automaticamente
            estoque = data.estado;
            try { if (window.CrmStore) window.CrmStore.ensureCrmDefault(); } catch (e) { console.error('CRM ensureCrmDefault (cloud auto):', e); }
            try { if (window.PontoStore) window.PontoStore.ensurePontoDefault(); } catch (e) { console.error('Ponto ensurePontoDefault (cloud auto):', e); }
            try { if (window.ProcessosStore) window.ProcessosStore.ensureProcessosDefault(); } catch (e) { console.error('Processos ensureProcessosDefault (cloud auto):', e); }
            // Sincronizar _localUpdatedAt com o timestamp remoto
            try { estoque._localUpdatedAt = data.updatedAt.toDate().toISOString(); } catch (e) { _catchSilencioso(e, 'carregarDoCloudAuto'); }
            // Restaurar dados IMBEL salvos no backup principal (se existirem)
            try {
                if (data && data.estado && data.estado._imbelData) {
                    try { localStorage.setItem(IMBEL_KEY, JSON.stringify(data.estado._imbelData)); console.info('IMBEL: restaurado do Cloud (auto)'); } catch (e) { console.warn('IMBEL: falha ao restaurar do Cloud (auto)', e); }
                } else if (estoque && estoque._imbelData) {
                    try { localStorage.setItem(IMBEL_KEY, JSON.stringify(estoque._imbelData)); console.info('IMBEL: restaurado do backup principal (auto)'); } catch (e) { /* ignore */ }
                }
            } catch (e) { _catchSilencioso(e, 'carregarDoCloudAuto'); }
            estoque.precificacoesCliente = normalizarPrecificacoesCliente(
                data.precificacoesCliente && data.precificacoesCliente.length
                    ? data.precificacoesCliente
                    : (estoque.precificacoesCliente || [])
            );
            precificacoesCliente = estoque.precificacoesCliente; // sincroniza variável global
            try { atualizarIndicadoresPrecificacao(); } catch (e) { _catchSilencioso(e, 'carregarDoCloudAuto'); }
            try { localStorage.setItem('precificacoesClienteBackupV1', JSON.stringify(precificacoesCliente || [])); } catch (e) { _catchSilencioso(e, 'carregarDoCloudAuto'); }
            if (!Array.isArray(estoque.auditoriaVendas)) estoque.auditoriaVendas = [];
            if (!Array.isArray(estoque.fechamentosComissoes)) estoque.fechamentosComissoes = [];
            if (!Array.isArray(estoque.clientes)) estoque.clientes = [];
            clientes = estoque.clientes;
            if (!Array.isArray(estoque.propostas)) estoque.propostas = [];
            propostas = estoque.propostas;
            if (estoque.precificacao && typeof estoque.precificacao === 'object') precificacao = estoque.precificacao;
            else { estoque.precificacao = {}; precificacao = estoque.precificacao; }

            precificacao = (data.precificacao && typeof data.precificacao === 'object')
                ? data.precificacao
                : (estoque.precificacao || {});
            tabelaAliquotas = (data.tabelaAliquotas && typeof data.tabelaAliquotas === 'object')
                ? data.tabelaAliquotas
                : (estoque.tabelaAliquotas || {});
            tabelaICMS = Array.isArray(data.tabelaICMS)
                ? data.tabelaICMS
                : (Array.isArray(estoque.tabelaICMS) ? estoque.tabelaICMS : []);
            categoriaPorProduto = (data.categoriaPorProduto && typeof data.categoriaPorProduto === 'object')
                ? data.categoriaPorProduto
                : (estoque.categoriaPorProduto || {});

            // Restaurar tabelas de impostos editáveis quando disponíveis
            impostosEditaveis = (data.impostosEditaveis && typeof data.impostosEditaveis === 'object') ? data.impostosEditaveis : (estoque.impostosEditaveis || {});
            icmsEditavelPJ    = (data.icmsEditavelPJ && typeof data.icmsEditavelPJ === 'object') ? data.icmsEditavelPJ : (estoque.icmsEditavelPJ || {});
            icmsEditavelPF    = (data.icmsEditavelPF && typeof data.icmsEditavelPF === 'object') ? data.icmsEditavelPF : (estoque.icmsEditavelPF || {});
            try { inicializarImpostosEditaveis(); } catch (e) { _catchSilencioso(e, 'carregarDoCloudAuto'); }
            try { inicializarICMSEditavel(); } catch (e) { _catchSilencioso(e, 'carregarDoCloudAuto'); }

            salvarDados();
            renderizarTabela();
            renderizarDashboard();
            renderizarRegistroVendas();
            renderizarRegistroDistribuicao();
            renderizarControleEnvio();
            renderizarClientes();
            atualizarKPIsClientes();
            atualizarDatalistClientes();
            renderizarPropostas();
            atualizarKPIsPropostas();
            if (abaAtiva === 'precificacao') renderizarPrecificacao();
            atualizarSelectsProdutos();
            atualizarSelectsRelatorios();
            try {
                const consultaEl = document.getElementById('subaba-precif-consulta');
                const rastreaEl = document.getElementById('subaba-precif-rastreabilidade');
                const isConsultaVis = consultaEl ? consultaEl.style.display !== 'none' : false;
                const isRastreaVis  = rastreaEl ? rastreaEl.style.display !== 'none' : false;
                if (isConsultaVis && typeof renderizarConsultaPrecificacao === 'function') renderizarConsultaPrecificacao();
                if (isRastreaVis && typeof renderizarRastreabilidade === 'function') renderizarRastreabilidade();
            } catch (e) { _catchSilencioso(e, 'carregarDoCloudAuto'); }
            console.debug('Dados carregados automaticamente do Firestore (remoto mais recente).');
            try { mostrarNotificacao('✅ Dados sincronizados do Cloud.', 'success'); } catch (e) { _catchSilencioso(e, 'carregarDoCloudAuto'); }
            window._carregandoDoCloud = false;
            window._dadosAlterados = false;
            window._userHasEdited = false;
            return true;
        }
        window._carregandoDoCloud = false;
        return false;
    } catch (e) {
        // Quando regras bloquearem leitura, não poluir console com erro fatal
        console.warn('carregarDoCloudAuto: leitura não permitida pelo perfil atual.');
        window._carregandoDoCloud = false;
        return false;
    }
}

// ============================
// Auto-save (debounced) helpers
// ============================
window.__AUTO_SAVE_CLOUD = {
    enabled: true,
    debounceMs: 2500,
    timerId: null,
    inProgress: false
};

function scheduleCloudSaveDebounced() {
    if (!window.__AUTO_SAVE_CLOUD.enabled) return;
    if (!window.firestoreDB) return;
    // Não salvar no cloud se o usuário não editou nada desde a inicialização
    // (evita sobrescrever dados do cloud com estado antigo do localStorage ao abrir o sistema)
    if (!window._userHasEdited) return;
    // permitir auto-save para usuários autenticados OU para admin (fallback)
    try {
        const fbUser = (typeof firebase !== 'undefined' && firebase.auth) ? firebase.auth().currentUser : null;
        const cachedAdmin = (typeof isCurrentUserAdmin === 'function') ? isCurrentUserAdmin() : false;
        if (!fbUser && !cachedAdmin) return;
    } catch (e) {
        if (!isCurrentUserAdmin()) return;
    }
    if (window.__AUTO_SAVE_CLOUD.timerId) clearTimeout(window.__AUTO_SAVE_CLOUD.timerId);
    window.__AUTO_SAVE_CLOUD.timerId = setTimeout(async () => {
        window.__AUTO_SAVE_CLOUD.timerId = null;
        if (window.__AUTO_SAVE_CLOUD.inProgress) return;
        window.__AUTO_SAVE_CLOUD.inProgress = true;
        try {
            await salvarNoCloud();
        } catch (e) {
            console.error('Auto-save falhou:', e);
        } finally {
            window.__AUTO_SAVE_CLOUD.inProgress = false;
        }
    }, window.__AUTO_SAVE_CLOUD.debounceMs);
}

function iniciarAutoSaveCloud() {
    // ativa auto-save se Firestore presente
    if (!window.firestoreDB) return;
    window.__AUTO_SAVE_CLOUD.enabled = true;
    // salvar a cada X minutos também (fallback periódico)
    if (!window.__AUTO_SAVE_CLOUD.periodicId) {
        window.__AUTO_SAVE_CLOUD.periodicId = setInterval(() => {
            // Só executar save periódico se o usuário realmente editou algo após a inicialização
            // Evita sobrescrever dados do cloud com estado antigo do localStorage ao abrir o sistema
            if (!window.__AUTO_SAVE_CLOUD.inProgress && window._userHasEdited) {
                salvarNoCloud().catch(e => console.error('Auto-save periódico falhou:', e));
            }
        }, 1000 * 60 * 5); // a cada 5 minutos
    }
}

function pararAutoSaveCloud() {
    window.__AUTO_SAVE_CLOUD.enabled = false;
    if (window.__AUTO_SAVE_CLOUD.timerId) {
        clearTimeout(window.__AUTO_SAVE_CLOUD.timerId);
        window.__AUTO_SAVE_CLOUD.timerId = null;
    }
    if (window.__AUTO_SAVE_CLOUD.periodicId) {
        clearInterval(window.__AUTO_SAVE_CLOUD.periodicId);
        window.__AUTO_SAVE_CLOUD.periodicId = null;
    }
}

function atualizarData() {
    const agora = new Date();
    const opcoes = { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' };
    const dataFormatada = agora.toLocaleDateString('pt-BR', opcoes);
    const dataAtualEl = document.getElementById('dataAtual');
    if (dataAtualEl) dataAtualEl.textContent = dataFormatada;
}

function atualizarEstatisticas() {
    let totalEstoque = 0;
    let totalVendas = 0;
    let valorTotalVendas = 0;

    estoque.produtos.forEach(produto => {
        estoque.representantes.forEach(rep => {
            const disp = produto.distribuicao[rep] || 0;
            const venda = produto.vendas[rep] || 0;
            totalEstoque += (disp - venda);
            totalVendas += venda;
        });
    });

    // Corrigir cálculo de faturamento: somar valorTotal de todas vendas registradas
    valorTotalVendas = 0;
    if (Array.isArray(estoque.registroVendas)) {
        estoque.registroVendas.forEach(venda => {
            if (venda && venda.cancelado) return; // ignorar vendas canceladas ao somar faturamento
            if (Array.isArray(venda.items) && venda.items.length > 0) {
                venda.items.forEach(it => {
                    valorTotalVendas += it.valorTotal || 0;
                });
            } else {
                valorTotalVendas += venda.valorTotal || 0;
            }
        });
    }

    const totalProdutosEl = document.getElementById('totalProdutos');
    if (totalProdutosEl) totalProdutosEl.textContent = estoque.produtos.length;

    const totalEstoqueEl = document.getElementById('totalEstoque');
    if (totalEstoqueEl) totalEstoqueEl.textContent = totalEstoque.toLocaleString('pt-BR');

    const totalVendasEl = document.getElementById('totalVendas');
    if (totalVendasEl) totalVendasEl.textContent = totalVendas.toLocaleString('pt-BR');

    const dashContainer = document.getElementById('tab-dashboard');
    const valorTotalVendasEl = (dashContainer && dashContainer.querySelector)
        ? (dashContainer.querySelector('#valorTotalVendas') || document.getElementById('valorTotalVendas'))
        : document.getElementById('valorTotalVendas');
    if (valorTotalVendasEl) valorTotalVendasEl.textContent = formatarMoedaValor(valorTotalVendas);
    // Calcular total de comissões (5%) excluindo vendas da IMBEL
    let totalComissoes = 0;
    if (Array.isArray(estoque.registroVendas)) {
        estoque.registroVendas.forEach(venda => {
            if (venda && venda.cancelado) return; // ignorar vendas canceladas
            const rep = (venda.representante || '').toString().trim().toUpperCase();
            if (rep === 'IMBEL') return; // sem comissão
            let valor = 0;
            if (Array.isArray(venda.items) && venda.items.length > 0) {
                venda.items.forEach(it => {
                    const valorItem = typeof it.valorTotal === 'number'
                        ? it.valorTotal
                        : ((Number(it.valorUnitario) || 0) * (Number(it.quantidade) || 0));
                    valor += valorItem;
                });
            } else {
                valor = typeof venda.valorTotal === 'number'
                    ? venda.valorTotal
                    : ((Number(venda.valorUnitario) || 0) * (Number(venda.quantidade) || 0));
            }
            totalComissoes += (Math.round((valor * 0.05) * 100) / 100);
        });
    }
    try {
        const totalComissoesEl = (dashContainer && dashContainer.querySelector)
            ? (dashContainer.querySelector('#totalComissoes') || document.getElementById('totalComissoes'))
            : document.getElementById('totalComissoes');
        if (totalComissoesEl) totalComissoesEl.textContent = formatarMoedaValor(totalComissoes);
    } catch (e) { _catchSilencioso(e, 'atualizarEstatisticas'); }
}

// Helper global: normaliza várias formas de data para YYYY-MM-DD
function parseDateToYYYYMMDD(input) {
    if (!input && input !== 0) return null;
    // Firestore Timestamp-like objects (has toDate)
    try {
        if (input && typeof input.toDate === 'function') {
            const dt = input.toDate();
            if (dt instanceof Date && !isNaN(dt.getTime())) return dt.toISOString().slice(0,10);
        }
    } catch (e) { _catchSilencioso(e, 'parseDateToYYYYMMDD'); }
    // Objects with seconds (e.g., { seconds, nanoseconds })
    if (input && typeof input === 'object') {
        if (typeof input.seconds === 'number') {
            const dt = new Date(input.seconds * 1000);
            if (!isNaN(dt.getTime())) return dt.toISOString().slice(0,10);
        }
        if (typeof input._seconds === 'number') {
            const dt = new Date(input._seconds * 1000);
            if (!isNaN(dt.getTime())) return dt.toISOString().slice(0,10);
        }
    }

    if (input instanceof Date) {
        if (isNaN(input.getTime())) return null;
        return input.toISOString().slice(0,10);
    }

    let s = String(input).trim();
    // ISO-like (starts with YYYY-MM-DD)
    const iso = s.match(/^(\d{4}-\d{2}-\d{2})/);
    if (iso) return iso[1];
    // BR format DD/MM/YYYY
    const br = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    if (br) return `${br[3]}-${br[2]}-${br[1]}`;
    // Try parsing general string
    const d = new Date(s);
    if (!isNaN(d.getTime())) return d.toISOString().slice(0,10);
    return null;
}

// Formata uma data (aceita 'YYYY-MM-DD', Date ou strings) para 'DD/MM/YYYY'
function formatDateToDDMMYYYY(input) {
    if (!input && input !== 0) return '-';
    try {
        // Already in YYYY-MM-DD
        if (typeof input === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(input)) {
            const parts = input.split('-');
            return `${parts[2].padStart(2,'0')}/${parts[1].padStart(2,'0')}/${parts[0]}`;
        }
        // Date-like
        const d = (input instanceof Date) ? input : new Date(input);
        if (!isNaN(d.getTime())) {
            const dd = String(d.getDate()).padStart(2,'0');
            const mm = String(d.getMonth() + 1).padStart(2,'0');
            const yyyy = d.getFullYear();
            return `${dd}/${mm}/${yyyy}`;
        }
    } catch (e) { _catchSilencioso(e, 'formatDateToDDMMYYYY'); }
    return '-';
}

function formatCpfCnpjMask(value) {
    const digits = String(value || '').replace(/\D/g, '').slice(0, 14);
    if (!digits) return '';

    if (digits.length <= 11) {
        if (digits.length <= 3) return digits;
        if (digits.length <= 6) return `${digits.slice(0,3)}.${digits.slice(3)}`;
        if (digits.length <= 9) return `${digits.slice(0,3)}.${digits.slice(3,6)}.${digits.slice(6)}`;
        return `${digits.slice(0,3)}.${digits.slice(3,6)}.${digits.slice(6,9)}-${digits.slice(9)}`;
    }

    if (digits.length <= 2) return digits;
    if (digits.length <= 5) return `${digits.slice(0,2)}.${digits.slice(2)}`;
    if (digits.length <= 8) return `${digits.slice(0,2)}.${digits.slice(2,5)}.${digits.slice(5)}`;
    if (digits.length <= 12) return `${digits.slice(0,2)}.${digits.slice(2,5)}.${digits.slice(5,8)}/${digits.slice(8)}`;
    return `${digits.slice(0,2)}.${digits.slice(2,5)}.${digits.slice(5,8)}/${digits.slice(8,12)}-${digits.slice(12)}`;
}

// Validação de CPF/CNPJ (dígitos verificadores)
function validarCPF(cpf) {
    const digits = String(cpf || '').replace(/\D/g, '');
    if (digits.length !== 11) return false;
    if (/^(\d)\1{10}$/.test(digits)) return false;

    let sum = 0;
    for (let i = 0; i < 9; i++) sum += parseInt(digits[i], 10) * (10 - i);
    let rest = (sum * 10) % 11;
    if (rest === 10 || rest === 11) rest = 0;
    if (rest !== parseInt(digits[9], 10)) return false;

    sum = 0;
    for (let i = 0; i < 10; i++) sum += parseInt(digits[i], 10) * (11 - i);
    rest = (sum * 10) % 11;
    if (rest === 10 || rest === 11) rest = 0;
    if (rest !== parseInt(digits[10], 10)) return false;

    return true;
}

function validarCNPJ(cnpj) {
    const digits = String(cnpj || '').replace(/\D/g, '');
    if (digits.length !== 14) return false;
    if (/^(\d)\1{13}$/.test(digits)) return false;

    let len = digits.length - 2;
    let nums = digits.substring(0, len);
    const digs = digits.substring(len);
    let sum = 0;
    let pos = len - 7;

    for (let i = len; i >= 1; i--) {
        sum += parseInt(nums.charAt(len - i), 10) * pos--;
        if (pos < 2) pos = 9;
    }
    let result = sum % 11 < 2 ? 0 : 11 - (sum % 11);
    if (result !== parseInt(digs.charAt(0), 10)) return false;

    len = digits.length - 1;
    nums = digits.substring(0, len);
    sum = 0;
    pos = len - 7;

    for (let i = len; i >= 1; i--) {
        sum += parseInt(nums.charAt(len - i), 10) * pos--;
        if (pos < 2) pos = 9;
    }
    result = sum % 11 < 2 ? 0 : 11 - (sum % 11);
    if (result !== parseInt(digs.charAt(1), 10)) return false;

    return true;
}

function validarDocumentoCliente() {
    const cnpjEl = document.getElementById('clienteCnpj');
    const tipoEl = document.getElementById('clienteTipoPessoa');
    if (!cnpjEl) return true;

    const valor = String(cnpjEl.value || '').trim();
    if (!valor) return true;

    const tipo = tipoEl?.value || 'PJ';
    const digits = valor.replace(/\D/g, '');
    const valido = tipo === 'PF' ? validarCPF(digits) : validarCNPJ(digits);

    if (!valido) {
        cnpjEl.style.borderColor = '#dc2626';
        cnpjEl.style.background = '#fef2f2';
        let errEl = document.getElementById('erroCnpj');
        if (!errEl) {
            errEl = document.createElement('div');
            errEl.id = 'erroCnpj';
            errEl.style.cssText = 'color:#dc2626;font-size:0.78rem;margin-top:4px;font-weight:500';
            cnpjEl.parentNode.appendChild(errEl);
        }
        errEl.textContent = tipo === 'PF' ? '❌ CPF inválido — verifique os dígitos' : '❌ CNPJ inválido — verifique os dígitos';
        cnpjEl.focus();
        return false;
    }

    cnpjEl.style.borderColor = '#22c55e';
    cnpjEl.style.background = '#f0fdf4';
    const errEl = document.getElementById('erroCnpj');
    if (errEl) errEl.textContent = '✅ ' + (tipo === 'PF' ? 'CPF válido' : 'CNPJ válido');
    return true;
}

function limparValidacaoDocumento() {
    const cnpjEl = document.getElementById('clienteCnpj');
    if (cnpjEl) {
        cnpjEl.style.borderColor = '';
        cnpjEl.style.background = '';
    }
    const errEl = document.getElementById('erroCnpj');
    if (errEl) errEl.textContent = '';
}

function formatPhoneMask(value) {
    const digits = String(value || '').replace(/\D/g, '').slice(0, 11);
    if (!digits) return '';
    if (digits.length <= 2) return `(${digits}`;
    if (digits.length <= 6) return `(${digits.slice(0,2)}) ${digits.slice(2)}`;
    if (digits.length <= 10) return `(${digits.slice(0,2)}) ${digits.slice(2,6)}-${digits.slice(6)}`;
    return `(${digits.slice(0,2)}) ${digits.slice(2,7)}-${digits.slice(7)}`;
}

function formatCurrencyBRLInput(value) {
    const digits = String(value || '').replace(/\D/g, '');
    if (!digits) return '';
    const cents = Number(digits);
    return (cents / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Cálculo puro extraído para EstoqueCalculos.parseCurrencyBRLToNumber (estoque-calculos.js).
function parseCurrencyBRLToNumber(value) {
    return EstoqueCalculos.parseCurrencyBRLToNumber(value);
}

function bindImbelMovInputMasks() {
    const cpfInput = document.getElementById('imbel_mov_cpf');
    const telInput = document.getElementById('imbel_mov_tel');
    const valorInput = document.getElementById('imbel_mov_valor');

    if (cpfInput && !cpfInput.dataset.maskBound) {
        cpfInput.addEventListener('input', function() {
            this.value = formatCpfCnpjMask(this.value);
        });
        cpfInput.dataset.maskBound = '1';
    }

    if (telInput && !telInput.dataset.maskBound) {
        telInput.addEventListener('input', function() {
            this.value = formatPhoneMask(this.value);
        });
        telInput.dataset.maskBound = '1';
    }

    if (valorInput && !valorInput.dataset.maskBound) {
        valorInput.addEventListener('input', function() {
            this.value = formatCurrencyBRLInput(this.value);
        });
        valorInput.dataset.maskBound = '1';
    }
}

function normalizarContratoKey(valor) {
    const bruto = (valor ?? '').toString().normalize('NFKC');
    const clean = bruto.replace(/[\u200B-\u200D\uFEFF\s]+/g, '');
    const digitos = clean.replace(/\D+/g, '');
    return digitos ? String(parseInt(digitos, 10)) : clean.toUpperCase();
}

function formatarContratoDisplay(valor, fallbackYear) {
    const bruto = (valor ?? '').toString().normalize('NFKC');
    const clean = bruto.replace(/[\u200B-\u200D\uFEFF\s]+/g, '');
    const currentYear = fallbackYear || new Date().getFullYear();
    // formato com separador: 002/2026 ou 2-2026
    const m = clean.match(/^(\d+)\D+(\d{4})$/);
    if (m) {
        const seq = String(parseInt(m[1], 10)).padStart(3, '0');
        const yr = m[2];
        return seq + '/' + yr;
    }
    const digits = clean.replace(/\D+/g, '');
    if (digits) {
        if (digits.length > 4) {
            const maybeYear = parseInt(digits.slice(-4), 10);
            if (!isNaN(maybeYear) && maybeYear >= 2000 && maybeYear <= 2099) {
                const seq = String(parseInt(digits.slice(0, -4), 10) || 0).padStart(3, '0');
                return seq + '/' + maybeYear;
            }
        }
        const seq = String(parseInt(digits, 10) || 0).padStart(3, '0');
        return seq + '/' + currentYear;
    }
    return '-';
}

function getUsuarioAtual() {
    let usuario = '';
    try { usuario = (localStorage.getItem('estoqueUsuarioAtual') || '').trim(); } catch (e) { _catchSilencioso(e, 'getUsuarioAtual'); }
    if (!usuario) {
        usuario = (prompt('Informe seu nome/usuário para auditoria:') || '').trim();
        if (!usuario) usuario = 'Usuário';
        try { localStorage.setItem('estoqueUsuarioAtual', usuario); } catch (e) { _catchSilencioso(e, 'getUsuarioAtual'); }
    }
    return usuario;
}

// Auditoria genérica para qualquer operação (distribuição, cadastro, etc.)
function registrarAuditoria(acao, antes, depois, detalhes) {
    if (!Array.isArray(estoque.auditoriaVendas)) estoque.auditoriaVendas = [];
    const entry = {
        id: Date.now() + Math.floor(Math.random() * 1000),
        quando: new Date().toISOString(),
        quem: getUsuarioAtual(),
        acao: acao,
        contrato: '-',
        antes: antes || null,
        depois: depois || null,
        detalhes: detalhes || ''
    };
    estoque.auditoriaVendas.push(entry);
    if (estoque.auditoriaVendas.length > 1000) {
        estoque.auditoriaVendas = estoque.auditoriaVendas.slice(-1000);
    }
}

function registrarAuditoriaVenda(acao, vendaAntes, vendaDepois, detalhes = '') {
    if (!Array.isArray(estoque.auditoriaVendas)) estoque.auditoriaVendas = [];
    const base = vendaDepois || vendaAntes || {};
    const contrato = normalizarContratoKey(base.contrato || '');
    const entry = {
        id: Date.now() + Math.floor(Math.random() * 1000),
        quando: new Date().toISOString(),
        quem: getUsuarioAtual(),
        acao: acao,
        contrato: contrato || '-',
        vendaId: base.id || null,
        antes: vendaAntes || null,
        depois: vendaDepois || null,
        detalhes: detalhes || ''
    };
    estoque.auditoriaVendas.push(entry);
    if (estoque.auditoriaVendas.length > 1000) {
        estoque.auditoriaVendas = estoque.auditoriaVendas.slice(-1000);
    }
}

function obterAuditoriaPorContrato(contrato) {
    const key = normalizarContratoKey(contrato || '');
    const lista = Array.isArray(estoque.auditoriaVendas) ? estoque.auditoriaVendas : [];
    return lista.filter(a => normalizarContratoKey(a.contrato || '') === key)
        .sort((a, b) => new Date(b.quando).getTime() - new Date(a.quando).getTime());
}

function abrirModalCancelamentos() {
    const eventos = (estoque.auditoriaVendas || [])
        .filter(a => a.acao === 'cancelamento')
        .sort((a, b) => new Date(b.quando) - new Date(a.quando));

    const container = document.getElementById('cancelamentosLista');
    if (!container) return;

    if (eventos.length === 0) {
        container.innerHTML = '<p style="text-align:center;color:var(--text-secondary);padding:20px">Nenhum cancelamento registrado na auditoria.</p>';
    } else {
        // Deduplica por contrato (mantém o evento mais recente de cada)
        const vistos = new Set();
        const unicos = eventos.filter(e => {
            if (vistos.has(e.contrato)) return false;
            vistos.add(e.contrato);
            return true;
        });

        const linhas = unicos.map(e => {
            const dep = e.depois || {};
            const contratoNum = dep.contrato || e.contrato || '-';
            const loja = dep.loja || '-';
            const rep = dep.representante || '-';
            const canceladoEm = dep.canceladoEm
                ? new Date(dep.canceladoEm).toLocaleString('pt-BR')
                : (e.quando ? new Date(e.quando).toLocaleString('pt-BR') : '-');
            const por = dep.canceladoPor || e.quem || '-';
            const aindaExiste = (estoque.registroVendas || []).some(v =>
                normalizarContratoKey(v.contrato) === e.contrato && v.cancelado
            );
            const situacao = aindaExiste
                ? '<span style="color:#d97706;font-weight:600">⛔ No registro</span>'
                : '<span style="color:#6b7280">Removido (reimport.)</span>';
            return `<tr style="border-bottom:1px solid var(--border-color)">
                <td style="padding:6px 10px;font-weight:600">${contratoNum}</td>
                <td style="padding:6px 10px">${loja}</td>
                <td style="padding:6px 10px">${rep}</td>
                <td style="padding:6px 10px;white-space:nowrap">${canceladoEm}</td>
                <td style="padding:6px 10px">${por}</td>
                <td style="padding:6px 10px">${situacao}</td>
            </tr>`;
        }).join('');

        container.innerHTML = `
            <table style="width:100%;border-collapse:collapse;font-size:0.88rem">
                <thead>
                    <tr style="border-bottom:2px solid var(--border-color);background:var(--bg-secondary)">
                        <th style="text-align:left;padding:6px 10px">Contrato</th>
                        <th style="text-align:left;padding:6px 10px">Loja</th>
                        <th style="text-align:left;padding:6px 10px">Rep.</th>
                        <th style="text-align:left;padding:6px 10px">Cancelado em</th>
                        <th style="text-align:left;padding:6px 10px">Por</th>
                        <th style="text-align:left;padding:6px 10px">Situação</th>
                    </tr>
                </thead>
                <tbody>${linhas}</tbody>
            </table>
            <p style="margin-top:10px;font-size:0.8rem;color:var(--text-secondary)">
                ${unicos.length} contrato(s) cancelado(s) encontrado(s) na auditoria.
            </p>`;
    }

    document.getElementById('modalCancelamentos').style.display = 'flex';
}

// ========================================
// RENDER: AUDITORIA DE VENDAS
// ========================================

function renderizarAuditoria() {
    const tbody = document.getElementById('auditoriaTbody');
    if (!tbody) return;

    const busca  = (document.getElementById('auditoriaBusca')?.value || '').toLowerCase();
    const filtroAcao = document.getElementById('auditoriaFiltroAcao')?.value || '';

    const lista = (estoque.auditoriaVendas || [])
        .slice()
        .reverse()
        .filter(a => {
            if (filtroAcao && !(a.acao||'').toUpperCase().includes(filtroAcao)) return false;
            if (busca) {
                return (a.contrato||'').toLowerCase().includes(busca) ||
                             (a.quem||'').toLowerCase().includes(busca) ||
                             (a.acao||'').toLowerCase().includes(busca) ||
                             (a.detalhes||'').toLowerCase().includes(busca);
            }
            return true;
        });

    const acaoColor = {
        'CRIAÇÃO':      { bg:'#f0fdf4', text:'#16a34a', icon:'➕' },
        'EDIÇÃO':       { bg:'#eff6ff', text:'#1d4ed8', icon:'✏️' },
        'EXCLUSÃO':     { bg:'#fef2f2', text:'#dc2626', icon:'🗑️' },
        'CANCELAMENTO': { bg:'#fff8f0', text:'#d97706', icon:'⛔' },
    };

    if (!lista.length) {
        tbody.innerHTML = `
            <tr>
                <td colspan="5" style="text-align:center;color:#94a3b8;padding:40px">Nenhum registro de auditoria encontrado</td>
            </tr>`;
        const cnt = document.getElementById('auditoriaCount');
        if (cnt) cnt.textContent = '0 registros';
        return;
    }

    tbody.innerHTML = lista.map((a, i) => {
        const dt = a.quando ? new Date(a.quando).toLocaleString('pt-BR') : '—';
        const acaoUpper = (a.acao||'').toUpperCase();
        const colorKey = Object.keys(acaoColor).find(k => acaoUpper.includes(k));
        const ac = acaoColor[colorKey] || { bg:'#f8fafc', text:'#475569', icon:'📝' };

        let delta = a.detalhes || '';
        if (a.antes && a.depois) {
            const campos = [];
            ['valorTotal','representante','contrato','loja'].forEach(campo => {
                const antes  = a.antes[campo];
                const depois = a.depois[campo];
                if (antes !== undefined && depois !== undefined && antes !== depois) {
                    campos.push(`${campo}: ${antes} → ${depois}`);
                }
            });
            if (campos.length) delta = campos.join(' | ');
        }

        return `
            <tr style="background:${i%2===0?'#fff':'#f8fafc'};border-bottom:1px solid #f1f5f9">
                <td style="font-size:0.78rem;color:#475569;white-space:nowrap">${dt}</td>
                <td style="font-size:0.8rem;font-weight:500;color:#1e293b">${a.quem || 'Sistema'}</td>
                <td><span style="background:${ac.bg};color:${ac.text};font-size:0.72rem;font-weight:600;padding:2px 8px;border-radius:20px;white-space:nowrap">${ac.icon} ${a.acao || '—'}</span></td>
                <td style="font-weight:700;color:#1e3a5f">${a.contrato ? '#' + a.contrato : '—'}</td>
                <td style="font-size:0.78rem;color:#64748b;max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${delta}">${delta || '—'}</td>
            </tr>`;
    }).join('');

    const cnt = document.getElementById('auditoriaCount');
    if (cnt) cnt.textContent = `${lista.length} de ${(estoque.auditoriaVendas||[]).length} registros`;
}

function exportarAuditoria() {
    const lista = (estoque.auditoriaVendas||[]).slice().reverse();
    if (!lista.length) { mostrarNotificacao('Nenhum registro para exportar.', 'warning'); return; }
    const rows = lista.map(a => ({
        'Data/Hora': a.quando ? new Date(a.quando).toLocaleString('pt-BR') : '',
        'Usuário':   a.quem   || 'Sistema',
        'Ação':      a.acao   || '',
        'Contrato':  a.contrato || '',
        'Detalhes':  a.detalhes || '',
    }));
    const ws = XLSX.utils.json_to_sheet(rows);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Auditoria');
    XLSX.writeFile(wb, 'auditoria_' + new Date().toISOString().split('T')[0] + '.xlsx');
}

// ========================================
// NAVEGAÇÃO POR ABAS
// ========================================

function trocarAba(aba) {
    // Controle de Envio foi unificado com Vendas
    if (aba === 'controleenvio') aba = 'vendas';
    try {
        const targetId = `tab-${aba}`;
        const target = document.getElementById(targetId);
        if (!target) {
            const msg = `Aba não encontrada: ${targetId}`;
            console.error(msg);
            if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(msg);
            return;
        }

        abaAtiva = aba;
        try { window.abaAtiva = aba; } catch (e) { _catchSilencioso(e, 'trocarAba'); }

        // Atualizar botões de navegação (sidebar e fallback antigo)
        document.querySelectorAll('.sidebar .nav-item, .tabs-navigation .tab-btn').forEach(btn => {
            btn.classList.remove('active');
        });
        const activeSidebarBtn = document.querySelector(`.sidebar .nav-item[data-tab="${aba}"]`);
        const activeLegacyBtn = document.querySelector(`.tabs-navigation .tab-btn[data-tab="${aba}"]`);
        if (activeSidebarBtn) activeSidebarBtn.classList.add('active');
        if (activeLegacyBtn) activeLegacyBtn.classList.add('active');

        // Atualizar conteúdo de forma segura
        document.querySelectorAll('.tab-content').forEach(content => content.classList.remove('active', 'fade-in'));
        target.classList.add('active');
        void target.offsetWidth; // força reflow p/ a animação reiniciar mesmo ao trocar de aba rapidamente
        target.classList.add('fade-in');


        if (aba === 'dashboard') {
            try { renderizarDashboard(); } catch (e) { console.error('dashboard:', e); if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'cadastro-produtos') {
            try { renderizarCadastroProdutos(); } catch (e) { console.error('cadastro-produtos:', e); if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'vendas') {
            try { renderizarRegistroVendas(); } catch (e) { console.error('vendas:', e); if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'distribuicao') {
            try { popularSelectRepresentantes('filtroDistribuicaoRep', true); } catch (e) { _catchSilencioso(e, 'trocarAba'); }
            try { atualizarSelectDistribuicaoProduto(); } catch (e) { _catchSilencioso(e, 'trocarAba'); }
            try { renderizarRegistroDistribuicao(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'relatorios') {
            try { prepararRelatorioInventario(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
            try { gerarRelatorioRentabilidade(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
            try { _popularSelectMes(); } catch (e) { _catchSilencioso(e, 'trocarAba'); }
        } else if (aba === 'controleenvio') {
            try { renderizarControleEnvio(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'controleimbel') {
            try { trocarSubAbaControleImbel('dashboard'); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'precificacao') {
            try { trocarSubabaPrecif('porcliente'); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
            try { renderizarPrecificacao(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
            try { popularSelectProdutosPrecif(); } catch (e) { _catchSilencioso(e, 'trocarAba'); }
            // Se o carregamento anterior deixou uma render pendente, disparar agora
            try {
                if (window._precificacaoPendenteRender) {
                    window._precificacaoPendenteRender = false;
                    setTimeout(() => {
                        try { renderizarConsultaPrecificacao && renderizarConsultaPrecificacao(); } catch (e) { _catchSilencioso(e, 'trocarAba'); }
                        try { renderizarRastreabilidade && renderizarRastreabilidade(); } catch (e) { _catchSilencioso(e, 'trocarAba'); }
                    }, 100);
                }
            } catch (e) { _catchSilencioso(e, 'trocarAba'); }
        } else if (aba === 'clientes') {
            try { renderizarClientes(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'propostas') {
            try { renderizarPropostas(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'relacionamento') {
            try { if (window.Crm) Crm.renderizar(); } catch (e) { console.error('relacionamento:', e); if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'ponto') {
            try { if (window.PontoUI) PontoUI.renderizar(); } catch (e) { console.error('ponto:', e); if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'processos') {
            try { if (window.ProcessosUI) ProcessosUI.renderizar(); } catch (e) { console.error('processos:', e); if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'estoque') {
            try { renderizarTabela(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'configuracoes') {
            try { atualizarPreviaContrato(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
            try { renderizarAuditoria(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
        } else if (aba === 'cadastro') {
            try { renderizarConfigVendedor(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
            try { renderizarConfigTestemunhas(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
            try { renderizarSelectConfigRep(); } catch (e) { if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(e); }
            try { renderizarListaRepresentantesConfig(); } catch (e) { _catchSilencioso(e, 'trocarAba'); }
            try { carregarConfigEmail(); } catch (e) { _catchSilencioso(e, 'trocarAba'); }
        }

        try { if (window.__updateDebugPanel) window.__updateDebugPanel(); } catch (e) { _catchSilencioso(e, 'trocarAba'); }

        // Fechar drawer mobile ao trocar aba
        try { document.body.classList.remove('mobile-sidebar-open'); } catch (e) { _catchSilencioso(e, 'trocarAba'); }
    } catch (err) {
        console.error('trocarAba falhou:', err);
        if (window.__showRuntimeErrorOverlay) window.__showRuntimeErrorOverlay(err);
    }
}

// ========================================
// RENDERIZAÇÃO DA TABELA DE ESTOQUE
// ========================================

function getInventoryRepsOrder() {
    const stored = Array.isArray(estoque.representantes) ? estoque.representantes.map(r => String(r).toUpperCase()) : [];
    const baseline = ['ISA','KOLTE','ADES','FL','LC'];
    // Começar sempre com a ordem fixa solicitada
    const order = baseline.slice();
    // Não adicionar representantes extras — manter apenas a baseline solicitada e IMBEL
    if (!order.includes('IMBEL')) order.push('IMBEL');
    return order;
}

function repClassName(rep) {
    return 'rep-' + String(rep || '').toLowerCase().replace(/[^a-z0-9\-]/g, '-');
}

// Abre a aba 'vendas' filtrada por produto e representante (função global usada por onclick)
function abrirVendasPorProduto(produtoId, representante) {
    try {
        try { atualizarSelectsProdutos(); } catch (e) { _catchSilencioso(e, 'abrirVendasPorProduto'); }
        try { popularSelectRepresentantes('filtroRepresentante', true); } catch (e) { _catchSilencioso(e, 'abrirVendasPorProduto'); }
        const filtroProduto = document.getElementById('filtroProduto');
        const filtroRep = document.getElementById('filtroRepresentante');
        if (filtroProduto) filtroProduto.value = produtoId || '';
        if (filtroRep) filtroRep.value = representante || '';
        trocarAba('vendas');
        setTimeout(() => {
            try {
                renderizarRegistroVendas();
                // rolar para a primeira linha que contenha o produto (se houver)
                try {
                    const prod = (estoque.produtos || []).find(p => Number(p.id) === Number(produtoId));
                    if (prod) {
                        const rows = Array.from(document.querySelectorAll('#tabelaRegistroVendasBody tr'));
                        for (const r of rows) {
                            if ((r.textContent || '').includes(prod.nome)) { r.scrollIntoView({ behavior: 'smooth', block: 'center' }); break; }
                        }
                    }
                } catch (e) { _catchSilencioso(e, 'abrirVendasPorProduto'); }
            } catch (e) { console.warn('abrirVendasPorProduto renderizar erro', e); }
        }, 80);
    } catch (e) { console.warn('abrirVendasPorProduto erro', e); }
}

// ── Configuração de representadas (cores Bloomberg) ──
const _EST_REPS_CFG = [
    { id: 'ISA',   nome: 'ISA',   tipo: 'dist',  cor: '#7c3aed', corBg: 'rgba(124,58,237,0.12)', corHdr: 'linear-gradient(180deg,#3b1f72,#4c1d95)' },
    { id: 'KOLTE', nome: 'KOLTE', tipo: 'dist',  cor: '#2563eb', corBg: 'rgba(37,99,235,0.12)',  corHdr: 'linear-gradient(180deg,#1e3a8a,#1d4ed8)' },
    { id: 'ADES',  nome: 'ADES',  tipo: 'dist',  cor: '#ea580c', corBg: 'rgba(234,88,12,0.12)',  corHdr: 'linear-gradient(180deg,#7c2d12,#c2410c)' },
    { id: 'FL',    nome: 'FL',    tipo: 'dist',  cor: '#9333ea', corBg: 'rgba(147,51,234,0.12)', corHdr: 'linear-gradient(180deg,#581c87,#7e22ce)' },
    { id: 'LC',    nome: 'LC',    tipo: 'dist',  cor: '#16a34a', corBg: 'rgba(22,163,74,0.12)',  corHdr: 'linear-gradient(180deg,#14532d,#15803d)' },
    { id: 'IMBEL', nome: 'IMBEL', tipo: 'house', cor: '#b8651f', corBg: 'rgba(184,101,31,0.12)', corHdr: 'linear-gradient(180deg,#431407,#9a3412)' },
];

// Estado persistente da UI da tabela de estoque
let _estState = {
    hiddenReps: new Set(),
    sortCol: null,
    sortDir: 'desc',
    filtro: { termo: '', categoria: '', mostrarZeros: true },
    pagina: 1,
    porPagina: 50,
};

function _estVisibleReps() {
    return getInventoryRepsOrder()
        .map(id => _EST_REPS_CFG.find(r => r.id === id) || { id, nome: id, tipo: 'dist', cor: '#666', corBg: '#eee', corHdr: '#333' })
        .filter(r => !_estState.hiddenReps.has(r.id));
}

function _estToggleRep(id) {
    if (_estState.hiddenReps.has(id)) _estState.hiddenReps.delete(id);
    else _estState.hiddenReps.add(id);
    renderizarTabela();
}
window._estToggleRep = _estToggleRep;

function _estSetDensity(d) {
    const tab = document.getElementById('tab-estoque');
    if (!tab) return;
    tab.classList.remove('est-density-compact', 'est-density-normal', 'est-density-cozy');
    tab.classList.add('est-density-' + d);
    tab.querySelectorAll('.est-density-btn').forEach(btn => {
        btn.classList.toggle('active', btn.getAttribute('onclick') && btn.getAttribute('onclick').includes(d));
    });
}
window._estSetDensity = _estSetDensity;

function _estSetSort(col) {
    if (_estState.sortCol === col) {
        _estState.sortDir = _estState.sortDir === 'asc' ? 'desc' : 'asc';
    } else {
        _estState.sortCol = col;
        _estState.sortDir = 'desc';
    }
    renderizarTabela();
}
window._estSetSort = _estSetSort;

function _estFmtN(n) {
    if (n == null || n === 0) return '—';
    return n.toLocaleString('pt-BR');
}

function _estRenderRepBar(produtosVisiveis) {
    const bar = document.getElementById('estRepbar');
    if (!bar) return;
    const allReps = getInventoryRepsOrder()
        .map(id => _EST_REPS_CFG.find(r => r.id === id) || { id, nome: id, cor: '#666', corBg: '#eee' });

    // Calcular vendas por rep para o badge
    const vendasPorRep = {};
    allReps.forEach(r => { vendasPorRep[r.id] = 0; });
    (estoque.registroVendas || []).forEach(v => {
        if (v.cancelado) return;
        const rep = (v.representante || '').toUpperCase();
        if (vendasPorRep[rep] !== undefined) {
            if (Array.isArray(v.items)) v.items.forEach(it => { vendasPorRep[rep] += Number(it.quantidade) || 0; });
            else vendasPorRep[rep] += Number(v.quantidade) || 0;
        }
    });

    const visCount = allReps.length - _estState.hiddenReps.size;
    let html = '<span class="est-repbar-lbl">Representadas:</span>';
    allReps.forEach(r => {
        const off = _estState.hiddenReps.has(r.id);
        const style = off ? 'border-color:#334155;color:#64748b' : `border-color:${r.cor};color:${r.cor};background:${r.corBg}`;
        html += `<button class="est-rep-pill${off ? ' off' : ''}" style="${style}" onclick="window._estToggleRep('${r.id}')">
            <span class="est-rep-dot" style="background:${off ? '#475569' : r.cor}"></span>
            ${r.nome}
            <span class="est-rep-cnt">${_estFmtN(vendasPorRep[r.id])} vd</span>
        </button>`;
    });
    html += `<span class="est-repbar-info">${visCount} de ${allReps.length} visíveis</span>`;
    bar.innerHTML = html;
}

function _estRenderKPIs(produtosVisiveis, totais, repsVisiveis) {
    const strip = document.getElementById('estKpiStrip');
    if (!strip) return;

    const totalDisp = totais.GERAL.disp;
    const totalVenda = totais.GERAL.venda;
    const totalSaldo = totais.GERAL.saldo;
    const countProd = produtosVisiveis.length;
    const totalProd = (estoque.produtos || []).filter(p => p.exibirNoEstoque === true).length;

    const negativos = produtosVisiveis.filter(p => {
        const m = obterMetricasImbelProduto(p);
        return m.consolidadoSaldo < 0;
    }).length;
    const zerados = produtosVisiveis.filter(p => {
        const m = obterMetricasImbelProduto(p);
        return m.consolidadoSaldo === 0;
    }).length;

    // Top rep por venda
    let topRepNome = '—', topRepVd = 0;
    repsVisiveis.forEach(r => {
        const vd = totais[r.id] ? totais[r.id].venda : 0;
        if (vd > topRepVd) { topRepVd = vd; topRepNome = r.nome; }
    });

    // Valor em saldo (CI × saldo consolidado)
    let valorSaldo = 0;
    produtosVisiveis.forEach(p => {
        const ci = Number(precificacao[p.nome]?.ci ?? p.ci ?? 0);
        const m = obterMetricasImbelProduto(p);
        valorSaldo += ci * Math.max(0, m.consolidadoSaldo);
    });

    const saldoCls = totalSaldo < 0 ? 'neg' : totalSaldo > 0 ? 'pos' : '';
    const alertCls = (negativos > 0 || zerados > 0) ? 'neg' : '';

    strip.innerHTML = `
        <div class="est-kpi">
            <div class="est-kpi-lbl">Produtos no inventário</div>
            <div class="est-kpi-val amber">${countProd}<span class="unit"> SKU</span></div>
            <div class="est-kpi-delta">${countProd === totalProd ? 'catálogo completo' : 'de ' + totalProd}</div>
        </div>
        <div class="est-kpi">
            <div class="est-kpi-lbl">Estoque consolidado</div>
            <div class="est-kpi-val ${saldoCls}">${_estFmtN(totalSaldo)}<span class="unit"> un</span></div>
            <div class="est-kpi-delta">dist ${_estFmtN(totalDisp)} · vendas ${_estFmtN(totalVenda)}</div>
        </div>
        <div class="est-kpi">
            <div class="est-kpi-lbl">Vendas totais</div>
            <div class="est-kpi-val pos">${_estFmtN(totalVenda)}<span class="unit"> un</span></div>
            <div class="est-kpi-delta">top: <b>${topRepNome}</b> (${_estFmtN(topRepVd)})</div>
        </div>
        <div class="est-kpi">
            <div class="est-kpi-lbl">Valor em saldo (CI)</div>
            <div class="est-kpi-val amber" style="color:var(--tv-copper)">R$ ${_estFmtN(Math.round(valorSaldo / 1000))}<span class="unit"> mil</span></div>
            <div class="est-kpi-delta">saldo × preço unit</div>
        </div>
        <div class="est-kpi">
            <div class="est-kpi-lbl">Alertas</div>
            <div class="est-kpi-val ${alertCls}">${negativos + zerados}</div>
            <div class="est-kpi-delta">${negativos} c/ saldo negativo · ${zerados} zerados</div>
        </div>`;

    // Atualizar KPIs do Dashboard também
    try {
        let totalVendidasGlobal = 0;
        if (Array.isArray(estoque.registroVendas) && estoque.registroVendas.length > 0) {
            totalVendidasGlobal = estoque.registroVendas.reduce((sum, v) => {
                if (Array.isArray(v.items)) return sum + v.items.reduce((s, i) => s + (Number(i.quantidade) || 0), 0);
                return sum + (Number(v.quantidade) || 0);
            }, 0);
        }
        const kpiTV = document.getElementById('kpiTotalVendido');
        const kpiSZ = document.getElementById('kpiSaldoZero');
        if (kpiTV) kpiTV.textContent = `${totalVendidasGlobal.toLocaleString('pt-BR')} un.`;
        if (kpiSZ) kpiSZ.textContent = `${(negativos + zerados).toLocaleString('pt-BR')} produtos`;
    } catch (e) { _catchSilencioso(e, '_estRenderKPIs'); }
}

function renderizarTabela() {
    const tbody = document.getElementById('corpoTabela');
    if (!tbody) return;

    const repsOrder = getInventoryRepsOrder();
    const repsVisiveis = _estVisibleReps();
    const totais = { GERAL: { disp: 0, venda: 0, saldo: 0 } };
    repsOrder.forEach(rep => { totais[rep] = { disp: 0, venda: 0, saldo: 0 }; });

    // Produtos filtrados e ordenados
    let produtosOrdenados = [...(estoque.produtos || [])]
        .filter(p => p.exibirNoEstoque === true);

    if (_estState.sortCol) {
        produtosOrdenados.sort((a, b) => {
            let vA, vB;
            if (_estState.sortCol === 'nome') { vA = a.nome; vB = b.nome; }
            else if (_estState.sortCol === 'total') { vA = obterMetricasImbelProduto(a).consolidadoDisp; vB = obterMetricasImbelProduto(b).consolidadoDisp; }
            else if (_estState.sortCol === 'venda') { vA = obterMetricasImbelProduto(a).consolidadoVenda; vB = obterMetricasImbelProduto(b).consolidadoVenda; }
            else if (_estState.sortCol === 'saldo') { vA = obterMetricasImbelProduto(a).consolidadoSaldo; vB = obterMetricasImbelProduto(b).consolidadoSaldo; }
            else { vA = 0; vB = 0; }
            const cmp = typeof vA === 'string' ? vA.localeCompare(vB, 'pt-BR') : vA - vB;
            return _estState.sortDir === 'asc' ? cmp : -cmp;
        });
    } else {
        produtosOrdenados.sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));
    }

    // ── Renderizar header ──
    const thead = document.getElementById('estThead');
    if (thead) {
        const sc = _estState.sortCol, sd = _estState.sortDir;
        function thSort(col, label, extra = '') {
            const isActive = sc === col;
            return `<th class="${extra}${isActive ? ' sort-active' : ''}${isActive && sd === 'desc' ? ' sort-desc' : ''}" onclick="window._estSetSort('${col}')" style="cursor:pointer">${label}<span class="est-sort-caret">▲</span></th>`;
        }

        // Linha 1 — grupos de rep
        let hdr1 = `<tr class="est-hdr-group">
            ${thSort('nome', 'PRODUTOS', 'est-prod-hdr')}`;
        repsVisiveis.forEach((r, ri) => {
            // !important pra vencer a regra genérica de header ".est-v2-table thead th"
            // (styles.css), que também usa !important e senão pintaria todo header de navy.
            hdr1 += `<th colspan="3" style="background:${r.corHdr} !important;color:#fff;border-bottom:0">
                <span class="est-rep-dot-hdr" style="background:${r.cor}"></span>${r.nome}
            </th>`;
        });
        hdr1 += `<th colspan="3" class="est-consol-grp">▪ CONSOLIDADO</th></tr>`;

        // Linha 2 — sub-headers DIST/VENDA/SALDO
        let hdr2 = `<tr class="est-hdr-sub"><th class="est-prod-hdr" style="top:28px"></th>`;
        repsVisiveis.forEach((r, ri) => {
            const alt = ri % 2 === 1 ? ' est-grp-alt-hdr' : '';
            const distLbl = r.tipo === 'house' ? 'ESTOQUE' : 'DIST';
            hdr2 += `<th class="${alt}" style="background:${r.corHdr} !important;color:#fff">${distLbl}</th>`;
            hdr2 += `<th class="${alt}" style="background:${r.corHdr} !important;color:#fff">VENDA</th>`;
            hdr2 += `<th class="est-grp-end${alt}" style="background:${r.corHdr} !important;color:#fff">SALDO</th>`;
        });
        hdr2 += `${thSort('total', 'TOTAL', 'est-consol-sub')}`;
        hdr2 += `${thSort('venda', 'VENDA', 'est-consol-sub')}`;
        hdr2 += `${thSort('saldo', 'SALDO', 'est-consol-sub')}`;
        hdr2 += `</tr>`;

        thead.innerHTML = hdr1 + hdr2;
    }

    // ── Renderizar corpo ──
    // Filtro (texto/categoria/zerados) + paginação decidem só quais linhas viram
    // HTML no DOM — os totais/KPIs abaixo continuam somando a lista inteira
    // (produtosOrdenados), sem mudar de comportamento.
    const filtro = _estState.filtro || {};
    const termoBuscaEst = (filtro.termo || '').toLowerCase();
    const catFiltroEst = (filtro.categoria || '').toLowerCase();
    const inicioPagina = (_estState.pagina - 1) * _estState.porPagina;
    const fimPagina = inicioPagina + _estState.porPagina;
    let indiceFiltrado = 0;
    let totalFiltradoEst = 0;

    let rows = '';
    produtosOrdenados.forEach(produto => {
        const produtoId = produto.id;
        const metricaImbel = obterMetricasImbelProduto(produto);
        const obs = produto.observacoes ? String(produto.observacoes).trim() : '';
        const categoria = (categoriaPorProduto && categoriaPorProduto[produto.nome]) || produto.categoria || '';
        const ncm = produto.ncm || '';

        const passaBuscaEst = !termoBuscaEst ||
            produto.nome.toLowerCase().includes(termoBuscaEst) ||
            ncm.toLowerCase().includes(termoBuscaEst) ||
            categoria.toLowerCase().includes(termoBuscaEst);
        const passaCatEst = !catFiltroEst || categoria.toLowerCase().includes(catFiltroEst);
        const passaZeroEst = filtro.mostrarZeros !== false || metricaImbel.consolidadoSaldo !== 0;
        const passaFiltroEst = passaBuscaEst && passaCatEst && passaZeroEst;

        const estoqueTotal = Number(
            (produto.estoqueConsolidado ?? produto.estoqueTotal ?? produto.estoque ?? produto.qtdTotal ?? produto.estoqueInicial) || 0
        );

        // Distribuições
        const distPorRep = {};
        (estoque.registroDistribuicao || []).forEach(d => {
            try {
                if (Number(d.produtoId) === Number(produtoId) || d.produtoNome === produto.nome) {
                    const r = (d.representante || '').toUpperCase();
                    distPorRep[r] = (distPorRep[r] || 0) + (Number(d.quantidade) || 0);
                }
            } catch (e) { _catchSilencioso(e, 'renderizarTabela'); }
        });

        // Devoluções
        const devPorRep = {};
        (estoque.registroDevolucoes || []).forEach(d => {
            try {
                if (Number(d.produtoId) === Number(produtoId) || d.produtoNome === produto.nome) {
                    const origem = (d.origem || d.representante || '').toUpperCase();
                    devPorRep[origem] = (devPorRep[origem] || 0) + (Number(d.quantidade) || 0);
                }
            } catch (e) { _catchSilencioso(e, 'renderizarTabela'); }
        });

        // Vendas
        const vendasPorRep = {};
        (estoque.registroVendas || []).forEach(v => {
            try {
                if (v.cancelado) return;
                const rep = (v.representante || '').toUpperCase();
                if (Array.isArray(v.items) && v.items.length) {
                    v.items.forEach(it => {
                        if (Number(it.produtoId) === Number(produtoId) || it.produtoNome === produto.nome)
                            vendasPorRep[rep] = (vendasPorRep[rep] || 0) + (Number(it.quantidade) || 0);
                    });
                } else if (Number(v.produtoId) === Number(produtoId) || v.produtoNome === produto.nome) {
                    vendasPorRep[rep] = (vendasPorRep[rep] || 0) + (Number(v.quantidade) || 0);
                }
            } catch (e) { _catchSilencioso(e, 'renderizarTabela'); }
        });

        // Célula produto
        const catBadge = categoria ? `<span class="est-prod-cat">${_escapeHtml(categoria)}</span>` : '';
        const ncmBadge = ncm ? `<span class="est-prod-ncm">${_escapeHtml(ncm)}</span>` : '';
        const obsHtml = obs ? `<span title="${_escapeHtml(obs)}" style="font-size:0.68rem;color:#94a3b8;margin-left:4px">📝</span>` : '';
        const destaqueClass = produto.destaque ? ' est-destaque' : '';

        let row = `<tr data-id="${produtoId}" data-nome="${_escapeHtml(produto.nome)}" data-cat="${_escapeHtml(categoria)}" data-ncm="${_escapeHtml(ncm)}"${destaqueClass ? ` class="${destaqueClass.trim()}"` : ''}>
            <td class="est-prod-cell">
                <div class="est-prod-nm" onclick="abrirModalEditarProduto(${produtoId})" title="${_escapeHtml(produto.nome)}">${_escapeHtml(produto.nome)}${obsHtml}</div>
                <div class="est-prod-meta">${catBadge}${ncmBadge}</div>
            </td>`;

        // Colunas por rep visível
        repsVisiveis.forEach((r, ri) => {
            const repKey = r.id;
            const alt = ri % 2 === 1 ? ' est-grp-alt' : '';
            let disp = 0, venda = 0, saldo = 0;

            if (repKey === 'IMBEL') {
                disp = metricaImbel.imbelDisp;
                venda = metricaImbel.imbelVenda;
                saldo = metricaImbel.imbelSaldo;
            } else {
                const dist = distPorRep[repKey] || 0;
                const dev = devPorRep[repKey] || 0;
                disp = dist - dev;
                venda = vendasPorRep[repKey] || 0;
                saldo = disp - venda;
            }

            const teveMov = !!(distPorRep[repKey] || devPorRep[repKey] || vendasPorRep[repKey]);
            const showDisp = repKey === 'IMBEL' ? (estoqueTotal > 0) : teveMov;
            const showVenda = teveMov || (repKey === 'IMBEL' && (vendasPorRep['IMBEL'] || 0) > 0);
            const showSaldo = showDisp || showVenda;

            const dispTxt = showDisp ? _estFmtN(disp) : '—';
            const vendaTxt = showVenda && venda > 0
                ? `<a class="est-venda-link" href="#" onclick="abrirVendasPorProduto(${produtoId},'${_escapeJsString(repKey)}');return false">${_estFmtN(venda)}</a>`
                : (showVenda ? _estFmtN(venda) : '—');
            const saldoCls = !showSaldo ? ' est-cell-zero' : saldo > 0 ? ' est-saldo-pos' : saldo < 0 ? ' est-saldo-neg' : ' est-saldo-zero';

            row += `<td class="${alt}">${disp !== 0 ? _estFmtN(disp) : '<span class="est-cell-zero">—</span>'}</td>`;
            row += `<td class="${alt}">${vendaTxt}</td>`;
            row += `<td class="est-grp-end${alt}${saldoCls}">${showSaldo ? _estFmtN(saldo) : '—'}</td>`;

            // Acumular totais (sempre, independente de visibilidade)
            totais[repKey].disp  += Number(disp)  || 0;
            totais[repKey].venda += Number(venda) || 0;
            totais[repKey].saldo += Number(saldo) || 0;
        });

        // Acumular totais de reps ocultos também
        repsOrder.forEach(repKey => {
            if (repsVisiveis.find(r => r.id === repKey)) return;
            let disp = 0, venda = 0, saldo = 0;
            if (repKey === 'IMBEL') {
                disp = metricaImbel.imbelDisp; venda = metricaImbel.imbelVenda; saldo = metricaImbel.imbelSaldo;
            } else {
                const dist = distPorRep[repKey] || 0;
                const dev = devPorRep[repKey] || 0;
                disp = dist - dev; venda = vendasPorRep[repKey] || 0; saldo = disp - venda;
            }
            totais[repKey].disp  += Number(disp)  || 0;
            totais[repKey].venda += Number(venda) || 0;
            totais[repKey].saldo += Number(saldo) || 0;
        });

        // Consolidado
        const cDisp  = metricaImbel.consolidadoDisp;
        const cVenda = metricaImbel.consolidadoVenda;
        const cSaldo = metricaImbel.consolidadoSaldo;
        const cSaldoCls = cSaldo > 0 ? ' est-saldo-pos' : cSaldo < 0 ? ' est-saldo-neg' : ' est-saldo-zero';
        const cVendaInner = cVenda > 0
            ? `<a class="est-venda-link" href="#" onclick="abrirVendasPorProduto(${produtoId},'');return false">${_estFmtN(cVenda)}</a>`
            : _estFmtN(cVenda);

        row += `<td class="est-consol-cell est-total">${_estFmtN(cDisp)}</td>`;
        row += `<td class="est-consol-cell">${cVendaInner}</td>`;
        row += `<td class="est-consol-cell${cSaldoCls}">${_estFmtN(cSaldo)}</td>`;
        row += `</tr>`;

        totais.GERAL.disp  += cDisp;
        totais.GERAL.venda += cVenda;
        totais.GERAL.saldo += cSaldo;

        if (passaFiltroEst) {
            if (indiceFiltrado >= inicioPagina && indiceFiltrado < fimPagina) {
                rows += row;
            }
            indiceFiltrado++;
            totalFiltradoEst++;
        }
    });

    if (!rows) rows = `<tr><td colspan="99" style="padding:20px;text-align:center;color:#94a3b8;font-size:0.82rem">Nenhum produto para exibir.</td></tr>`;
    tbody.innerHTML = rows;

    // ── Rodapé de totais ──
    const tfoot = document.getElementById('rodapeTabela');
    if (tfoot) {
        let foot = `<tr><td class="est-prod-cell">
            <div class="est-foot-lbl">TOTAIS</div>
            <div class="est-foot-sub">${produtosOrdenados.length} produtos</div>
        </td>`;
        repsVisiveis.forEach((r, ri) => {
            const alt = ri % 2 === 1 ? ' est-grp-alt-foot' : '';
            const t = totais[r.id];
            const sCls = t.saldo > 0 ? ' est-saldo-pos' : t.saldo < 0 ? ' est-saldo-neg' : '';
            foot += `<td class="${alt}">${_estFmtN(t.disp)}</td>`;
            foot += `<td class="${alt}">${_estFmtN(t.venda)}</td>`;
            foot += `<td class="est-grp-end${alt}${sCls}">${_estFmtN(t.saldo)}</td>`;
        });
        const gCls = totais.GERAL.saldo > 0 ? ' est-saldo-pos' : totais.GERAL.saldo < 0 ? ' est-saldo-neg' : '';
        foot += `<td class="est-consol-cell">${_estFmtN(totais.GERAL.disp)}</td>`;
        foot += `<td class="est-consol-cell">${_estFmtN(totais.GERAL.venda)}</td>`;
        foot += `<td class="est-consol-cell${gCls}">${_estFmtN(totais.GERAL.saldo)}</td>`;
        foot += `</tr>`;
        tfoot.innerHTML = foot;
    }

    // ── Renderizar RepBar e KPIs (sempre sobre a lista inteira, não a página atual) ──
    try { _estRenderRepBar(produtosOrdenados); } catch (e) { _catchSilencioso(e, 'renderizarTabela'); }
    try { _estRenderKPIs(produtosOrdenados, totais, repsVisiveis); } catch (e) { _catchSilencioso(e, 'renderizarTabela'); }
    try { _estRenderPaginacao(totalFiltradoEst); } catch (e) { _catchSilencioso(e, 'renderizarTabela'); }

    // Aplicar densidade padrão (compacto) se ainda não definida
    const tabEstoque = document.getElementById('tab-estoque');
    if (tabEstoque && !tabEstoque.classList.contains('est-density-compact') &&
        !tabEstoque.classList.contains('est-density-normal') &&
        !tabEstoque.classList.contains('est-density-cozy')) {
        tabEstoque.classList.add('est-density-compact');
    }

    try { renderizarCadastroProdutos(); } catch (e) { _catchSilencioso(e, 'renderizarTabela'); }
}

function _togglePecas(el, nomePai) {
    const tbody = document.getElementById('corpoCadastroProdutos');
    if (!tbody) return;
    const icon = el.querySelector('.pn-expand-icon');
    const expandido = icon && icon.textContent.trim() === '▼';
    const nomePaiUpper = (nomePai || '').toUpperCase();
    tbody.querySelectorAll('tr[data-peca-filha]').forEach(tr => {
        if ((tr.dataset.pecaFilha || '').toUpperCase() === nomePaiUpper) {
            tr.style.display = expandido ? 'none' : 'table-row';
        }
    });
    if (icon) icon.textContent = expandido ? '▶' : '▼';
}

function renderizarCadastroProdutos() {
    const tbody = document.getElementById('corpoCadastroProdutos');
    const empty = document.getElementById('cadastroProdutosEmpty');
    const tabelaWrap = document.getElementById('cadastroProdutosTabelaWrap');
    if (!tbody || !empty || !tabelaWrap) return;

    let lista = Array.isArray(estoque.produtos) ? [...estoque.produtos] : [];

    // ── Filtro por busca de texto ──
    const termoBusca = _cadProdFiltroBusca.toLowerCase().trim();
    if (termoBusca) {
        lista = lista.filter(p => {
            const nome = (p.nome || '').toLowerCase();
            const pn = (p.pn || '').toLowerCase();
            const nf = (p.nomeFabrica || '').toLowerCase();
            const comp = (p.componente || '').toLowerCase();
            const ncm = (p.ncm || '').toLowerCase();
            return nome.includes(termoBusca) || pn.includes(termoBusca) || nf.includes(termoBusca) || comp.includes(termoBusca) || ncm.includes(termoBusca);
        });
    }

    // ── Filtro por categoria ──
    if (_cadProdFiltroCategoria) {
        lista = lista.filter(p => {
            const cat = (categoriaPorProduto && categoriaPorProduto[p.nome]) || p.categoria || '';
            return cat === _cadProdFiltroCategoria;
        });
    }

    // ── Filtro "Sem CI" ──
    if (_cadProdFiltroSemCI) {
        lista = lista.filter(p => {
            const ci = parseFloat(precificacao[p.nome]?.ci ?? p.ci ?? 0);
            return !ci || ci <= 0;
        });
    }

    // ── Ordenação ──
    lista.sort((a, b) => {
        const dir = _cadProdSort.dir === 'asc' ? 1 : -1;
        const nomeA = a.nome || '';
        const nomeB = b.nome || '';
        const regraA = (precificacao && precificacao[nomeA]) ? precificacao[nomeA] : {};
        const regraB = (precificacao && precificacao[nomeB]) ? precificacao[nomeB] : {};
        switch (_cadProdSort.col) {
            case 'nome':
                return dir * nomeA.localeCompare(nomeB, 'pt-BR');
            case 'categoria': {
                const cA = (categoriaPorProduto && categoriaPorProduto[nomeA]) || a.categoria || '';
                const cB = (categoriaPorProduto && categoriaPorProduto[nomeB]) || b.categoria || '';
                return dir * cA.localeCompare(cB, 'pt-BR');
            }
            case 'pn':
                return dir * (a.pn || '').localeCompare(b.pn || '', 'pt-BR');
            case 'nomeFabrica':
                return dir * (a.nomeFabrica || '').localeCompare(b.nomeFabrica || '', 'pt-BR');
            case 'ci': {
                const ciA = Number(regraA.ci ?? a.ci ?? 0) || 0;
                const ciB = Number(regraB.ci ?? b.ci ?? 0) || 0;
                return dir * (ciA - ciB);
            }
            case 'margemMin': {
                const mA = Number(regraA.margemMinima ?? a.margemMinima ?? 0) || 0;
                const mB = Number(regraB.margemMinima ?? b.margemMinima ?? 0) || 0;
                return dir * (mA - mB);
            }
            case 'descMax': {
                const dA = Number(regraA.descontoMaximo ?? a.descontoMaximo ?? 0) || 0;
                const dB = Number(regraB.descontoMaximo ?? b.descontoMaximo ?? 0) || 0;
                return dir * (dA - dB);
            }
            case 'saldo': {
                const sA = obterMetricasImbelProduto(a).consolidadoSaldo;
                const sB = obterMetricasImbelProduto(b).consolidadoSaldo;
                return dir * (sA - sB);
            }
            case 'atualizado': {
                const dA = new Date(a.atualizadoEm || a.dataAtualizacao || a.criadoEm || 0).getTime();
                const dB = new Date(b.atualizadoEm || b.dataAtualizacao || b.criadoEm || 0).getTime();
                return dir * (dA - dB);
            }
            default:
                return dir * nomeA.localeCompare(nomeB, 'pt-BR');
        }
    });

    // ── Atualizar ícones de sort no thead ──
    document.querySelectorAll('#tabelaCadastroProdutos th.sortable').forEach(th => {
        th.classList.remove('sort-asc', 'sort-desc');
        const icon = th.querySelector('.sort-icon');
        if (icon) icon.textContent = '↕';
    });
    const colMap = { nome: 4, categoria: 1, pn: 2, nomeFabrica: 3, ci: 6, saldo: 8, atualizado: 9 };
    const colIdx = colMap[_cadProdSort.col];
    if (colIdx !== undefined) {
        const ths = document.querySelectorAll('#tabelaCadastroProdutos thead th');
        const thAtivo = ths[colIdx];
        if (thAtivo) {
            thAtivo.classList.add(_cadProdSort.dir === 'asc' ? 'sort-asc' : 'sort-desc');
            const icon = thAtivo.querySelector('.sort-icon');
            if (icon) icon.textContent = _cadProdSort.dir === 'asc' ? '↑' : '↓';
        }
    }

    const totalGeral = (Array.isArray(estoque.produtos) ? estoque.produtos : []).length;
    let comCI = 0;
    (Array.isArray(estoque.produtos) ? estoque.produtos : []).forEach(p => {
        const r = (precificacao && precificacao[p.nome]) ? precificacao[p.nome] : {};
        if ((Number(r.ci ?? p.ci ?? 0) || 0) > 0) comCI += 1;
    });

    tbody.innerHTML = '';

    // Separar produtos principais (sem componente) de peças (com componente)
    const todosOsProdutos = Array.isArray(estoque.produtos) ? estoque.produtos : [];
    const principais = lista.filter(p => !p.componente || p.componente.trim() === '' || p.componente.trim() === '-');
    const pecas = lista.filter(p => p.componente && p.componente.trim() !== '' && p.componente.trim() !== '-');

    // Indexar peças pelo nome do armamento pai (campo componente) — chave em uppercase para match case-insensitive
    const pecasPorPai = {};
    todosOsProdutos.filter(p => p.componente && p.componente.trim() !== '' && p.componente.trim() !== '-').forEach(p => {
        const pai = p.componente.trim().toUpperCase();
        if (!pecasPorPai[pai]) pecasPorPai[pai] = [];
        pecasPorPai[pai].push(p);
    });

    // Peças que apareceram no filtro mas cujo pai não está na lista filtrada — mostrar como linha normal
    const paisNaLista = new Set(principais.map(p => p.nome.toUpperCase()));
    const pecasOrfas = pecas.filter(p => !paisNaLista.has(p.componente.trim().toUpperCase()));

    function _renderLinhaProduto(produto, isPeca = false) {
        const nome = produto.nome || '-';
        const regra = (precificacao && precificacao[nome]) ? precificacao[nome] : {};
        const ci = Number(regra.ci ?? produto.ci ?? 0) || 0;
        const margemMin = Number(regra.margemMinima ?? produto.margemMinima ?? 0) || 0;
        const descontoMax = Number(regra.descontoMaximo ?? produto.descontoMaximo ?? 0) || 0;
        const categoria = (categoriaPorProduto && categoriaPorProduto[nome]) || produto.categoria || '-';
        const ncm = produto.ncm || '-';
        const metricaImbel = obterMetricasImbelProduto(produto);
        const imbelTexto = metricaImbel.estoqueTotal === 0 ? '-' : formatarNumero(metricaImbel.imbelDisp);
        const saldoConsolidado = metricaImbel.consolidadoSaldo;
        const saldoConsolidadoTexto = formatarNumero(saldoConsolidado);
        const saldoConsolidadoCor = saldoConsolidado > 0 ? '#2da44e' : '#cf222e';
        const saldoConsolidadoClasse = saldoConsolidado < 0 ? 'negativo' : '';
        const atualizadoEm = produto.atualizadoEm || produto.dataAtualizacao || produto.criadoEm || '';
        const atualizadoTxt = atualizadoEm
            ? (typeof formatDateToDDMMYYYY === 'function' ? formatDateToDDMMYYYY(atualizadoEm) : new Date(atualizadoEm).toLocaleDateString('pt-BR'))
            : '-';
        const noEstoque = produto.exibirNoEstoque === true;
        const noEstoqueBadge = noEstoque
            ? `<span style="display:inline-block;background:#dcfce7;color:#166534;border-radius:10px;padding:2px 10px;font-size:0.78rem;font-weight:700">Sim</span>`
            : `<span style="display:inline-block;background:#f1f5f9;color:#94a3b8;border-radius:10px;padding:2px 10px;font-size:0.78rem">Não</span>`;
        const pn = produto.pn || '-';
        const nomeFabrica = produto.nomeFabrica || '-';
        const componente = produto.componente || '-';
        const categoriaBadge = categoria !== '-'
            ? `<span class="badge-categoria" data-cat="${_escapeHtml(categoria)}">${_escapeHtml(categoria)}</span>`
            : '-';

        const expandSlotId = 'expand-slot-' + Number(produto.id);
        const tr = document.createElement('tr');
        if (isPeca) {
            tr.style.cssText = 'background:#f8fafc;display:none';
            tr.dataset.pecaFilha = produto.componente.trim();
        }
        const ncmCodigo = ncm && ncm !== '-' ? ncm.split(/\s*[–\-]\s*/)[0].trim() : '-';
        const ncmDescricao = ncm && ncm !== '-' ? ncm : '';
        tr.innerHTML = `
            <td style="font-family:monospace;font-size:0.85rem;white-space:nowrap" title="${_escapeHtml(ncmDescricao)}">${_escapeHtml(ncmCodigo)}</td>
            <td>${categoriaBadge}</td>
            <td style="font-family:monospace;${isPeca ? 'color:#64748b;font-size:0.85rem' : ''}">${_escapeHtml(pn)}<span id="${expandSlotId}"></span></td>
            <td>${_escapeHtml(nomeFabrica)}</td>
            <td>${_escapeHtml(componente)}</td>
            <td style="text-align:left;font-weight:600;${isPeca ? 'padding-left:12px;color:#475569' : ''}">${isPeca ? '↳ ' : ''}${_escapeHtml(nome)}</td>
            <td>${ci > 0 ? formatarMoedaValor(ci) : '-'}</td>
            <td>${imbelTexto}</td>
            <td class="${saldoConsolidadoClasse}" style="color:${saldoConsolidadoCor};font-weight:700;font-family:monospace">${saldoConsolidadoTexto}</td>
            <td>${atualizadoTxt}</td>
            <td style="text-align:center">${noEstoqueBadge}</td>
            <td style="white-space:nowrap">
                <button class="btn-action btn-edit" data-admin="true" onclick="abrirModalEditarProduto(${Number(produto.id)})" title="Editar">✎</button>
                <button class="btn-action btn-delete" data-admin="true" onclick="excluirProduto(${Number(produto.id)})" title="Excluir">🗑</button>
            </td>
        `;
        tr.addEventListener('click', e => {
            if (e.target.tagName === 'BUTTON' || e.target.tagName === 'SELECT' || e.target.closest('button') || e.target.closest('select')) return;
            document.querySelectorAll('#corpoCadastroProdutos tr.row-selected').forEach(r => r.classList.remove('row-selected'));
            tr.classList.add('row-selected');
        });
        return tr;
    }

    // Renderizar produtos principais com botão expand se tiver peças, e as peças
    // órfãs (pai fora da lista filtrada) — em lotes de 50 via LazyLoader, pra não
    // travar a tela quando a lista tem centenas/milhares de produtos.
    function _renderUnidadeProdutoPrincipal(produto) {
        const filhas = pecasPorPai[produto.nome.toUpperCase()] || [];
        const temPecas = filhas.length > 0;
        const tr = _renderLinhaProduto(produto, false);

        tbody.appendChild(tr);

        if (temPecas) {
            // Busca o slot APÓS o tr estar no DOM
            const slot = document.getElementById('expand-slot-' + Number(produto.id));
            if (slot) {
                const btnExpand = document.createElement('span');
                btnExpand.style.cssText = 'cursor:pointer;user-select:none;display:inline-flex;align-items:center;gap:4px;margin-top:4px';
                btnExpand.title = `Clique para ver as ${filhas.length} peça(s)`;
                btnExpand.dataset.nomePai = produto.nome;
                const iconSpan = document.createElement('span');
                iconSpan.className = 'pn-expand-icon';
                iconSpan.style.cssText = 'font-size:0.75rem;color:#1e3a5f;font-weight:700';
                iconSpan.textContent = '▶';
                const badge = document.createElement('span');
                badge.style.cssText = 'background:#e0f2fe;color:#0369a1;border-radius:10px;padding:1px 7px;font-size:0.72rem;font-weight:700';
                badge.textContent = `${filhas.length} peça${filhas.length > 1 ? 's' : ''}`;
                btnExpand.appendChild(iconSpan);
                btnExpand.appendChild(badge);
                btnExpand.addEventListener('click', e => {
                    e.stopPropagation();
                    _togglePecas(btnExpand, produto.nome);
                });
                slot.appendChild(document.createElement('br'));
                slot.appendChild(btnExpand);
            }
        }

        // Renderizar linhas das peças (ocultas por padrão)
        filhas.forEach(peca => {
            tbody.appendChild(_renderLinhaProduto(peca, true));
        });
    }

    const unidadesParaRenderizar = principais.map(produto => ({ tipo: 'principal', produto }))
        .concat(pecasOrfas.map(produto => ({ tipo: 'orfa', produto })));

    function _renderUnidade(unidade) {
        if (unidade.tipo === 'principal') _renderUnidadeProdutoPrincipal(unidade.produto);
        else tbody.appendChild(_renderLinhaProduto(unidade.produto, false));
    }

    if (window.LazyLoader) {
        LazyLoader.render(tbody, unidadesParaRenderizar, _renderUnidade, {
            chunkSize: 50,
            criarSentinela: function (restantes) {
                const tr = document.createElement('tr');
                tr.className = 'lazy-sentinela';
                const td = document.createElement('td');
                td.colSpan = 11;
                td.style.cssText = 'text-align:center;padding:12px;color:#94a3b8;font-size:0.8rem';
                td.textContent = `Carregando mais produtos... (${restantes} restante${restantes !== 1 ? 's' : ''})`;
                tr.appendChild(td);
                return tr;
            }
        });
    } else {
        // Fallback defensivo caso lazy-loader.js não tenha carregado — comportamento antigo.
        unidadesParaRenderizar.forEach(_renderUnidade);
    }

    // ── Atualizar KPIs com contagem global (não filtrada) ──
    const semCI = Math.max(0, totalGeral - comCI);
    const totalEl = document.getElementById('cadProdTotal');
    const comCIEl = document.getElementById('cadProdComCI');
    const semCIEl = document.getElementById('cadProdSemCI');
    if (totalEl) totalEl.textContent = String(totalGeral);
    if (comCIEl) comCIEl.textContent = String(comCI);
    if (semCIEl) semCIEl.textContent = String(semCI);

    // ── Barra de progresso CI ──
    const pct = totalGeral > 0 ? Math.round((comCI / totalGeral) * 100) : 0;
    const bar = document.getElementById('cadProdCIProgressBar');
    const barLabel = document.getElementById('cadProdCIProgressLabel');
    if (bar) bar.style.width = pct + '%';
    if (barLabel) barLabel.textContent = `${comCI} de ${totalGeral} (${pct}%)`;

    // ── Contador de resultados ──
    const countEl = document.getElementById('prodResultCount');
    if (countEl) {
        const filtrado = termoBusca || _cadProdFiltroCategoria;
        countEl.textContent = filtrado ? `${lista.length} de ${totalGeral} produto${totalGeral !== 1 ? 's' : ''}` : '';
    }

    const vazio = lista.length === 0;
    empty.style.display = vazio ? 'block' : 'none';
    tabelaWrap.style.display = vazio ? 'none' : 'block';
}

function excluirProduto(id) {
    const idx = (estoque.produtos || []).findIndex(p => Number(p.id) === Number(id));
    if (idx === -1) return;
    const prod = estoque.produtos[idx];
    if (!confirm(`Excluir "${prod.nome}"?\nEsta ação não pode ser desfeita.`)) return;
    estoque.produtos.splice(idx, 1);
    if (precificacao && precificacao[prod.nome]) delete precificacao[prod.nome];
    salvarDados();
    renderizarCadastroProdutos();
    mostrarNotificacao(`Produto "${prod.nome}" excluído.`, 'success');
}

function ordenarCadastroPor(col) {
    if (_cadProdSort.col === col) {
        _cadProdSort.dir = _cadProdSort.dir === 'asc' ? 'desc' : 'asc';
    } else {
        _cadProdSort = { col, dir: 'asc' };
    }
    renderizarCadastroProdutos();
}

function filtrarCadastroProdutos() {
    _cadProdFiltroBusca = (document.getElementById('produtoBusca')?.value || '').trim().toLowerCase();
    _cadProdFiltroCategoria = document.getElementById('produtoFiltroCategoria')?.value || '';
    renderizarCadastroProdutos();
}

// Versão com debounce para o campo de busca por texto: evita re-renderizar a
// tabela inteira a cada tecla digitada (o filtro por categoria, um <select>,
// continua chamando filtrarCadastroProdutos() direto — não precisa de debounce).
const filtrarCadastroProdutosDebounced = window.Debounce
    ? Debounce.criar(filtrarCadastroProdutos, 300)
    : filtrarCadastroProdutos;

function toggleFiltroSemCI() {
    _cadProdFiltroSemCI = !_cadProdFiltroSemCI;
    const btn = document.getElementById('btnFiltroSemCI');
    if (btn) {
        btn.style.background = _cadProdFiltroSemCI ? '#1e3a5f' : '';
        btn.style.color = _cadProdFiltroSemCI ? '#fff' : '';
        btn.style.borderColor = _cadProdFiltroSemCI ? '#1e3a5f' : '';
    }
    renderizarCadastroProdutos();
}

// Calcula e aplica o top correto para a segunda linha do thead (sub-headers)
function ajustarStickyHeader() {
    const tabela = document.getElementById('tabelaEstoque');
    if (!tabela) return;
    const firstRow = tabela.querySelector('thead tr:first-child');
    if (!firstRow) return;
    requestAnimationFrame(() => {
        const h = firstRow.getBoundingClientRect().height;
        const secondRowThs = tabela.querySelectorAll('thead tr:nth-child(2) th');
        secondRowThs.forEach(th => { th.style.top = h + 'px'; });
    });
}

