function abrirModalVendaDetalhada(vendaId = null, propostaId = null) {
    // vendaId: se fornecido, abre o modal em modo de edição para essa venda
    // propostaId: se fornecido, preenche campos a partir da proposta para revisão
    if (!requireAdminOrNotify()) return;
    const modalEl = document.getElementById('modalVendaDetalhada');
    modalEl.style.display = 'flex';
    document.getElementById('formVendaDetalhada').reset();
    document.getElementById('valorUnitarioVenda').value = '';
    document.getElementById('valorTotalVenda').value = '';
    atualizarSelectsProdutos();
    try { popularSelectRepresentantes('representanteVendaDet', true); } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }

    const container = document.getElementById('itensVendaContainer');
    if (!container) return;

    // Garantir listener no campo cliente/loja para atualizar preços quando mudar
    try {
        const lojaEl = document.getElementById('lojaVenda');
        if (lojaEl) {
            const _onLojaChange = function() {
                try { preencherDadosCliente(lojaEl.value); } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }
                try { atualizarUFClienteVenda(lojaEl.value); } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }
                try { atualizarPrecosVendaPorCliente(true); } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }
                try { atualizarBadgesEstoqueTodasLinhas(); } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }
            };
            lojaEl.oninput = _onLojaChange;
            lojaEl.onchange = _onLojaChange;
        }
    } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }

    // Pre-fill from proposal if propostaId provided
    if (propostaId && !vendaId) {
        const proposta = (propostas || []).find(p => p.id === propostaId || p.id === String(propostaId));
        if (proposta) {
            vendaEditandoId = null;
            container.innerHTML = '';

            // preencher contrato com sequência (apenas número) baseada no ano da data
            try {
                const contratoEl = document.getElementById('contratoVenda');
                const dataEl = document.getElementById('dataVenda');
                const defaultYear = (dataEl && dataEl.value) ? new Date(dataEl.value + 'T12:00:00').getFullYear() : new Date().getFullYear();
                const seq = gerarNumeroContrato(defaultYear);
                if (contratoEl) {
                    contratoEl.value = seq;
                    contratoEl.dataset.autogenerated = '1';
                    contratoEl.oninput = function() { this.dataset.autogenerated = '0'; };
                }
                if (dataEl) {
                    dataEl.onchange = function() {
                        if (contratoEl && contratoEl.dataset.autogenerated === '1') {
                            const y = this.value ? new Date(this.value + 'T12:00:00').getFullYear() : new Date().getFullYear();
                            contratoEl.value = gerarNumeroContrato(y);
                            contratoEl.dataset.autogenerated = '1';
                        }
                    };
                }
            } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }
            document.getElementById('lojaVenda').value = proposta.cliente || '';
            try { atualizarUFClienteVenda(proposta.cliente || ''); } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }
            document.getElementById('representanteVendaDet').value = proposta.representante || '';
            document.getElementById('observacoesVenda').value = 'Gerado a partir da proposta ' + proposta.numero + (proposta.observacoes ? '\n' + proposta.observacoes : '');
            try { document.getElementById('dataVenda').value = new Date().toISOString().slice(0, 10); } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }

            if (Array.isArray(proposta.itens) && proposta.itens.length > 0) {
                proposta.itens.forEach(it => {
                    const preValor = it.valorUnitario ? it.valorUnitario.toLocaleString('pt-BR', { minimumFractionDigits: 2 }) : '';
                    adicionarItemVendaRow(it.produtoId, it.quantidade, preValor, it.produtoNome || '');
                });
            } else {
                adicionarItemVendaRow();
            }
            atualizarTotalVendaDetalhada();
            return;
        }
    }

    // Se estamos criando nova venda, inicializa com uma linha vazia e sugere contrato
    if (!vendaId) {
        vendaEditandoId = null;
        container.innerHTML = '';
        adicionarItemVendaRow();

        try {
            const contratoEl = document.getElementById('contratoVenda');
            const dataEl = document.getElementById('dataVenda');
            const defaultYear = (dataEl && dataEl.value) ? new Date(dataEl.value + 'T12:00:00').getFullYear() : new Date().getFullYear();
            const seq = gerarNumeroContrato(defaultYear);
            if (contratoEl) {
                contratoEl.value = seq;
                contratoEl.dataset.autogenerated = '1';
                contratoEl.oninput = function() { this.dataset.autogenerated = '0'; };
            }
            if (dataEl) {
                dataEl.onchange = function() {
                    if (contratoEl && contratoEl.dataset.autogenerated === '1') {
                        const y = this.value ? new Date(this.value + 'T12:00:00').getFullYear() : new Date().getFullYear();
                        contratoEl.value = gerarNumeroContrato(y);
                        contratoEl.dataset.autogenerated = '1';
                    }
                };
            }
        } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }
        // Preencher data padrão como hoje
        try { document.getElementById('dataVenda').value = new Date().toISOString().slice(0,10); } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }
        return;
    }

    // Modo edição: preencher campos com os dados da venda
    const venda = estoque.registroVendas.find(v => v.id === vendaId);
    if (!venda) {
        mostrarNotificacao('Venda não encontrada para edição', 'error');
        vendaEditandoId = null;
        container.innerHTML = '';
        adicionarItemVendaRow();
        return;
    }

    vendaEditandoId = vendaId;
    container.innerHTML = '';

    document.getElementById('contratoVenda').value = venda.contrato || '';
    document.getElementById('lojaVenda').value = venda.loja || '';
    try { atualizarUFClienteVenda(venda.loja || ''); } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }
    document.getElementById('representanteVendaDet').value = venda.representante || '';
    document.getElementById('observacoesVenda').value = venda.observacoes || '';
    // Preencher campo de data com valor existente (normalizado para YYYY-MM-DD)
    try { document.getElementById('dataVenda').value = parseDateToYYYYMMDD(venda.data) || ''; } catch (e) { _catchSilencioso(e, 'abrirModalVendaDetalhada'); }

    if (Array.isArray(venda.items) && venda.items.length > 0) {
        venda.items.forEach(it => {
            const preValor = it.valorUnitario ? it.valorUnitario.toLocaleString('pt-BR', { minimumFractionDigits: 2 }) : '';
            adicionarItemVendaRow(it.produtoId, it.quantidade, preValor, it.produtoNome || '');
        });
    } else {
        // compatibilidade com registro antigo
        const preValor = venda.valorUnitario ? venda.valorUnitario.toLocaleString('pt-BR', { minimumFractionDigits: 2 }) : '';
        adicionarItemVendaRow(venda.produtoId, venda.quantidade || 1, preValor, venda.produtoNome || '');
    }

    atualizarTotalVendaDetalhada();

}

// Constrói opções de produtos (HTML) para selects dinâmicos
function construirOpcoesProdutos() {
    let html = '<option value="">Selecione um produto</option>';
    const produtosOrdenados = [...estoque.produtos]
        .filter(p => !p.componente || p.componente.trim() === '' || p.componente.trim() === '-')
        .sort((a, b) => a.nome.localeCompare(b.nome, 'pt-BR'));
    produtosOrdenados.forEach(produto => {
        html += `<option value="${produto.id}">${produto.nome}</option>`;
    });
    return html;
}

function adicionarItemVendaRow(preProdutoId = '', preQuantidade = 1, preValor = '', preProdutoNome = '') {
    try {
        const container = document.getElementById('itensVendaContainer');
        if (!container) return;

        const row = document.createElement('div');
        row.className = 'item-venda-row';
        row.style.display = 'flex';
        row.style.gap = '8px';
        row.style.alignItems = 'center';
        row.style.marginBottom = '6px';

        // Construir opções com segurança
        let opcoesHtml = '';
        try {
            opcoesHtml = construirOpcoesProdutos();
        } catch (err) {
            console.error('Erro ao construir opções de produtos:', err);
            opcoesHtml = '<option value="">(nenhum produto)</option>';
        }

        row.innerHTML = `
            <select class="item-produto" onchange="onTrocarProdutoVenda(this)">${opcoesHtml}</select>
            <span class="item-estoque-badge" style="font-size:0.75rem;white-space:nowrap;color:#64748b;background:#f1f5f9;border-radius:4px;padding:2px 7px;border:1px solid #e2e8f0"></span>
            <input type="number" class="item-quantidade" min="1" value="${preQuantidade}" style="width:90px" onchange="atualizarItemRow(this)" />
            <input type="text" class="item-valor" placeholder="Valor unit. (obrigatório)" style="width:140px" oninput="formatarMoeda(this); atualizarItemRow(this)" />
            <div class="item-subtotal" style="min-width:120px">-</div>
            <button type="button" class="btn btn-outline btn-sm" onclick="removerItemRow(this)">Remover</button>
        `;

        container.appendChild(row);

        // Preencher valores se fornecidos (forçar string para bater com value das options)
        if (preProdutoId) {
            const selProd = row.querySelector('.item-produto');
            const idStr = String(preProdutoId);
            selProd.dataset.preselect = idStr;
            if (preProdutoNome) selProd.dataset.produtoNome = preProdutoNome;
            const _aplicarSelecao = (sel, id) => {
                for (let i = 0; i < sel.options.length; i++) {
                    if (sel.options[i].value === id) { sel.options[i].selected = true; return true; }
                }
                // Fallback: tentar encontrar pelo nome do produto gravado no item
                if (sel.dataset.produtoNome) {
                    const nomeLower = sel.dataset.produtoNome.trim().toLowerCase();
                    for (let i = 0; i < sel.options.length; i++) {
                        if (sel.options[i].textContent.trim().toLowerCase() === nomeLower) {
                            sel.options[i].selected = true;
                            return true;
                        }
                    }
                }
                sel.value = id;
                return sel.value === id;
            };
            _aplicarSelecao(selProd, idStr);
            setTimeout(() => { if (selProd.isConnected && selProd.value !== idStr) _aplicarSelecao(selProd, idStr); }, 50);
            setTimeout(() => { if (selProd.isConnected && selProd.value !== idStr) _aplicarSelecao(selProd, idStr); }, 300);
        }
        if (preValor) row.querySelector('.item-valor').value = preValor;

        // Garantir que o input de valor remova o estado "auto-preenchido" quando o usuário editar
        try {
            const valorInp = row.querySelector('.item-valor');
            if (valorInp && !valorInp.dataset._listenerVal) {
                valorInp.addEventListener('input', () => {
                    valorInp.style.background = '';
                    valorInp.removeAttribute('data-autofilled');
                });
                valorInp.dataset._listenerVal = '1';
            }
        } catch (e) { _catchSilencioso(e, 'adicionarItemVendaRow'); }

        // Se já existe um cliente preenchido no modal, tentar preencher o preço salvo automaticamente
        try {
            const lojaEl = document.getElementById('lojaVenda');
            if (lojaEl && lojaEl.value && (!preValor || preValor === '')) {
                const sel = row.querySelector('.item-produto');
                if (sel) autoPreencherPrecoProduto(sel);
            }
        } catch (e) { _catchSilencioso(e, 'adicionarItemVendaRow'); }

        // Atualizar visual do item
        atualizarItemRow(row.querySelector('.item-produto'));
    } catch (err) {
        console.error('Erro em adicionarItemVendaRow:', err);
        mostrarNotificacao('Erro ao adicionar item. Veja o console para detalhes.', 'error');
    }
}

function removerItemRow(btn) {
    const row = btn.closest('.item-venda-row');
    if (row) {
        row.remove();
        atualizarTotalVendaDetalhada();
    }
}

function atualizarBadgeEstoqueItem(selectEl) {
    const row = selectEl.closest('.item-venda-row');
    if (!row) return;
    const badge = row.querySelector('.item-estoque-badge');
    if (!badge) return;
    const produtoId = parseInt(selectEl.value);
    if (!produtoId) { badge.textContent = ''; return; }
    const produto = (estoque.produtos || []).find(p => p.id === produtoId);
    if (!produto) { badge.textContent = ''; return; }
    const rep = (document.getElementById('representanteVendaDet')?.value || '').trim();
    if (!rep) { badge.textContent = ''; return; }
    const repUpper = rep.toUpperCase();
    const isImbelRep = repUpper === 'IMBEL';

    let disp, distribuido, vendidoRep;

    if (isImbelRep) {
        // IMBEL (Venda Direta): usar métricas consolidadas — sem distribuição por rep
        const met = obterMetricasImbelProduto(produto);
        disp = Number(met.imbelSaldo || 0);
        distribuido = Number(met.imbelDisp || 0);
        vendidoRep = Number(met.imbelVenda || 0);
        badge.textContent = `Disp. IMBEL: ${disp}`;
        badge.title = `Disp. IMBEL (após dist.): ${distribuido} | Vendido IMBEL: ${vendidoRep} | Disponível: ${disp}`;
    } else {
        // Representante externo: calcular a partir de registroDistribuicao/Vendas
        distribuido = (estoque.registroDistribuicao || []).reduce((s, d) => {
            if ((d.representante || '').toUpperCase() !== repUpper) return s;
            if (Number(d.produtoId) !== Number(produto.id) && d.produtoNome !== produto.nome) return s;
            return s + (Number(d.quantidade) || 0);
        }, 0) - (estoque.registroDevolucoes || []).reduce((s, d) => {
            if ((d.origem || '').toUpperCase() !== repUpper) return s;
            if (Number(d.produtoId) !== Number(produto.id) && d.produtoNome !== produto.nome) return s;
            return s + (Number(d.quantidade) || 0);
        }, 0);
        vendidoRep = (estoque.registroVendas || []).reduce((s, v) => {
            if (v.cancelado) return s;
            if (vendaEditandoId !== null && v.id === vendaEditandoId) return s;
            if ((v.representante || '').toUpperCase() !== repUpper) return s;
            return s + vendaItemQtdParaProduto(v, produto);
        }, 0);
        disp = distribuido - vendidoRep;
        badge.textContent = `Disp. ${rep}: ${disp}`;
        badge.title = `Distribuído: ${distribuido} | Vendido: ${vendidoRep} | Disponível: ${disp}`;
    }

    badge.style.cursor = 'help';
    badge.style.color = disp > 0 ? '#15803d' : '#dc2626';
    badge.style.background = disp > 0 ? '#f0fdf4' : '#fef2f2';
    badge.style.borderColor = disp > 0 ? '#bbf7d0' : '#fecaca';
}

function onTrocarProdutoVenda(selectEl) {
    // Ao trocar o produto, sempre limpar o valor anterior (auto ou manual)
    // para que o novo preço seja buscado
    const row = selectEl.closest('.item-venda-row');
    if (row) {
        const valorInput = row.querySelector('.item-valor');
        if (valorInput) {
            valorInput.value = '';
            valorInput.removeAttribute('data-autofilled');
            valorInput.style.background = '';
        }
    }
    autoPreencherPrecoProduto(selectEl);
    atualizarItemRow(selectEl);
    atualizarBadgeEstoqueItem(selectEl);
}

function atualizarUFClienteVenda(nomeCliente) {
    const ufEl = document.getElementById('ufClienteVenda');
    if (!ufEl) return;
    const cliente = (clientes || []).find(c => (c.nome || '').trim().toLowerCase() === (nomeCliente || '').trim().toLowerCase());
    ufEl.value = (cliente && cliente.uf) ? cliente.uf.trim().toUpperCase() : '';
}

function atualizarBadgesEstoqueTodasLinhas() {
    const container = document.getElementById('itensVendaContainer');
    if (!container) return;
    container.querySelectorAll('.item-venda-row').forEach(row => {
        const sel = row.querySelector('.item-produto');
        if (sel) atualizarBadgeEstoqueItem(sel);
    });
}

function atualizarItemRow(el) {
    const row = el.closest ? el.closest('.item-venda-row') : el.parentElement;
    if (!row) return;

    const quantidade = parseInt(row.querySelector('.item-quantidade').value) || 0;
    const valorInput = row.querySelector('.item-valor').value || '';

    let unit = 0;
    if (valorInput && valorInput.trim() !== '') {
        unit = converterMoedaParaNumero(valorInput);
    }

    const subtotal = unit * quantidade;
    const subtotalEl = row.querySelector('.item-subtotal');
    subtotalEl.textContent = quantidade > 0 ? formatarMoedaValor(subtotal) : '-';

    // Placeholder fixo para reforçar valor informado na venda
    const valorEl = row.querySelector('.item-valor');
    if (valorEl && (!valorEl.value || valorEl.value.trim() === '')) {
        valorEl.placeholder = 'Valor unit. (obrigatório)';
    }

    atualizarTotalVendaDetalhada();
}

function atualizarTotalVendaDetalhada() {
    const container = document.getElementById('itensVendaContainer');
    if (!container) return;

    let total = 0;
    let totalQtd = 0;
    const rows = container.querySelectorAll('.item-venda-row');
    rows.forEach(row => {
        const quantidade = parseInt(row.querySelector('.item-quantidade').value) || 0;
        const valorInput = row.querySelector('.item-valor').value || '';

        let unit = 0;
        if (valorInput && valorInput.trim() !== '') {
            unit = converterMoedaParaNumero(valorInput);
        }

        total += unit * quantidade;
        totalQtd += quantidade;
    });

    document.getElementById('valorTotalVenda').value = total > 0 ? formatarMoedaValor(total) : '';
    document.getElementById('valorUnitarioVenda').value = totalQtd > 0 ? formatarMoedaValor(total / totalQtd) : '';
}

// Layout toggle removed per user request (button removed from modal)

function atualizarPrecoVenda() {
    // Valor de venda não é mais vinculado ao cadastro do produto.
    // Mantemos o total com base apenas nos valores informados nos itens da venda.
    atualizarTotalVendaDetalhada();
}

function validarEstoqueParaVenda(representante, itens, excluirVendaId) {
    const erros = [];
    (itens || []).forEach(it => {
        let produto = null;
        if (it.produtoId) produto = (estoque.produtos || []).find(p => p.id === it.produtoId);
        if (!produto && it.produtoNome) produto = (estoque.produtos || []).find(p => (p.nome || '').toLowerCase() === (it.produtoNome || '').toLowerCase());
        if (!produto) {
            erros.push({ produto: it.produtoNome || ('ID:' + (it.produtoId || '')), solicitado: it.quantidade || 0, disponivel: 0 });
            return;
        }
        const isImbelRep = (representante || '').toString().toUpperCase() === 'IMBEL';
        const repUpper = (representante || '').toString().toUpperCase();
        // Calcular distribuído em tempo real dos registros
        const distribReal = isImbelRep ? calcularImbelDisponivel(produto) : (
            (estoque.registroDistribuicao || []).reduce((s, d) => {
                if ((d.representante || '').toUpperCase() !== repUpper) return s;
                if (Number(d.produtoId) !== Number(produto.id) && d.produtoNome !== produto.nome) return s;
                return s + (Number(d.quantidade) || 0);
            }, 0) - (estoque.registroDevolucoes || []).reduce((s, d) => {
                if ((d.origem || '').toUpperCase() !== repUpper) return s;
                if (Number(d.produtoId) !== Number(produto.id) && d.produtoNome !== produto.nome) return s;
                return s + (Number(d.quantidade) || 0);
            }, 0)
        );
        const disp = distribReal;
        const vendido = isImbelRep ? 0 : (estoque.registroVendas || []).reduce((s, v) => {
            if (v.cancelado) return s;
            if (excluirVendaId !== undefined && v.id === excluirVendaId) return s;
            if ((v.representante || '').toUpperCase() !== repUpper) return s;
            return s + vendaItemQtdParaProduto(v, produto);
        }, 0);
        const saldo = disp - vendido;
        if ((it.quantidade || 0) > saldo) {
            erros.push({ produto: produto.nome, solicitado: it.quantidade || 0, disponivel: saldo });
        }
    });
    return erros.length ? { valido: false, erros } : { valido: true };
}

function mostrarConfirmacaoEstoque(mensagem, callbackConfirmar, callbackCancelar) {
    const elMsg = document.getElementById('msgConfirmacaoEstoque');
    const modal = document.getElementById('modalConfirmacaoEstoque');
    if (!elMsg || !modal) {
        if (typeof callbackConfirmar === 'function') callbackConfirmar();
        return;
    }
    elMsg.textContent = mensagem;
    modal.style.display = 'block';
    const btn = document.getElementById('btnConfirmarVendaSemEstoque');
    if (btn) {
        btn.onclick = () => {
            fecharModal('modalConfirmacaoEstoque');
            if (typeof callbackConfirmar === 'function') callbackConfirmar();
        };
    }
    const btnCancel = modal.querySelector('.modal-footer .btn.btn-outline');
    if (btnCancel) {
        btnCancel.onclick = () => {
            fecharModal('modalConfirmacaoEstoque');
            if (typeof callbackCancelar === 'function') callbackCancelar();
        };
    }
}

function finalizarSalvamentoVendaDetalhada(params) {
    const { contrato, loja, representante, observacoes, itens, totalQtd, totalValor, isEditing, vendaAnterior, vendaAnteriorSnapshot, vendaEditandoIdLocal } = params;

    if (isEditing && vendaAnterior) {
        const idx = estoque.registroVendas.findIndex(v => v.id === vendaEditandoIdLocal);
        if (idx !== -1) {
            estoque.registroVendas[idx].contrato = contrato;
            estoque.registroVendas[idx].loja = loja;
            estoque.registroVendas[idx].representante = representante;
            estoque.registroVendas[idx].items = itens;
            estoque.registroVendas[idx].quantidadeTotal = totalQtd;
            estoque.registroVendas[idx].valorTotal = totalValor;
            estoque.registroVendas[idx].observacoes = observacoes;
            const dataInput = document.getElementById('dataVenda') ? document.getElementById('dataVenda').value : '';
            if (dataInput && dataInput !== '') {
                try { estoque.registroVendas[idx].data = new Date(dataInput + 'T00:00:00Z').toISOString(); } catch (e) { estoque.registroVendas[idx].data = new Date().toISOString(); }
            } else {
                estoque.registroVendas[idx].data = new Date().toISOString();
            }
            try {
                registrarAuditoriaVenda(
                    'edicao',
                    vendaAnteriorSnapshot,
                    JSON.parse(JSON.stringify(estoque.registroVendas[idx])),
                    `Contrato ${contrato} atualizado (${totalQtd} itens / ${formatarMoedaValor(totalValor)})`
                );
            } catch (e) { _catchSilencioso(e, 'finalizarSalvamentoVendaDetalhada'); }
        }
        vendaEditandoId = null;

        try { reconstruirVendasAPartirDeRegistros(); } catch (e) { _catchSilencioso(e, 'finalizarSalvamentoVendaDetalhada'); }
        salvarDados();
        renderizarTabela();
        renderizarDashboard();
        renderizarRegistroVendas();
        fecharModal('modalVendaDetalhada');

        mostrarNotificacao(`Venda atualizada: Contrato ${contrato} - ${totalQtd} itens - ${formatarMoedaValor(totalValor)}`, 'success');
        return;
    }

    // Verificar se já existe contrato com mesmo número E mesmo cliente (loja)
    const contratoExistente = (estoque.registroVendas || []).find(v =>
        v.contrato === contrato &&
        (v.loja || '').trim().toLowerCase() === (loja || '').trim().toLowerCase()
    );
    if (contratoExistente) {
        const dataEx = contratoExistente.data ? new Date(contratoExistente.data).toLocaleDateString('pt-BR') : '';
        mostrarNotificacao(
            `⚠️ Atenção: já existe o contrato ${contrato} para "${loja}"${dataEx ? ' registrado em ' + dataEx : ''}. Verifique se não é duplicidade.`,
            'warning'
        );
    }

    // Criar registro de venda com múltiplos itens (novo)
    const novaVenda = {
        id: Date.now(),
        contrato: contrato,
        loja: loja,
        representante: representante,
        items: itens,
        quantidadeTotal: totalQtd,
        valorTotal: totalValor,
        observacoes: observacoes,
        data: (function(){ const di = document.getElementById('dataVenda') ? document.getElementById('dataVenda').value : ''; if (di && di !== '') { try { return new Date(di + 'T00:00:00Z').toISOString(); } catch (e) { _catchSilencioso(e, 'finalizarSalvamentoVendaDetalhada'); } } return new Date().toISOString(); })()
    };

    estoque.registroVendas.push(novaVenda);

    try {
        registrarAuditoriaVenda(
            'criacao',
            null,
            JSON.parse(JSON.stringify(novaVenda)),
            `Contrato ${contrato} criado (${totalQtd} itens / ${formatarMoedaValor(totalValor)})`
        );
    } catch (e) { _catchSilencioso(e, 'finalizarSalvamentoVendaDetalhada'); }

    try { reconstruirVendasAPartirDeRegistros(); } catch (e) { _catchSilencioso(e, 'finalizarSalvamentoVendaDetalhada'); }
    salvarDados();
    renderizarTabela();
    renderizarDashboard();
    renderizarRegistroVendas();
    fecharModal('modalVendaDetalhada');

    mostrarNotificacao(`Venda registrada: Contrato ${contrato} - ${totalQtd} itens - ${formatarMoedaValor(totalValor)}`, 'success');
}

function salvarVendaDetalhada(event) {
    if (!requireAdminOrNotify()) return;
    event.preventDefault();
    const contratoInput = (document.getElementById('contratoVenda')?.value || '').trim();
    const dataVendaVal = document.getElementById('dataVenda')?.value || '';
    const anoVenda = dataVendaVal ? new Date(dataVendaVal + 'T12:00:00').getFullYear() : new Date().getFullYear();
    const isEditing = vendaEditandoId !== null;
    let contratoFinal = contratoInput;
    if (!isEditing) {
        if (!contratoFinal) {
            contratoFinal = String(obterProximoNumeroContratoParaAno(anoVenda)).padStart(3, '0') + '/' + anoVenda;
        } else if (!contratoFinal.includes('/')) {
            contratoFinal = String(parseInt(contratoFinal, 10) || 0).padStart(3, '0') + '/' + anoVenda;
        } else {
            const parts = contratoFinal.split('/');
            const seq = String(parseInt(parts[0] || '0', 10) || 0).padStart(3, '0');
            contratoFinal = seq + '/' + anoVenda;
        }
    } else {
        // edição: manter ano se fornecido, caso contrário usar ano da data; garantir padding da sequência
        if (!contratoFinal.includes('/')) {
            contratoFinal = String(parseInt(contratoFinal || '0', 10) || 0).padStart(3, '0') + '/' + anoVenda;
        } else {
            const parts = contratoFinal.split('/');
            const seq = String(parseInt(parts[0] || '0', 10) || 0).padStart(3, '0');
            const yr = parts[1] || anoVenda;
            contratoFinal = seq + '/' + yr;
        }
    }
    const loja = document.getElementById('lojaVenda').value.trim().toUpperCase();
    const representante = document.getElementById('representanteVendaDet').value;
    const observacoes = document.getElementById('observacoesVenda').value.trim();

    // Coletar itens
    const container = document.getElementById('itensVendaContainer');
    if (!container) {
        mostrarNotificacao('Erro interno: container de itens não encontrado.', 'error');
        return;
    }

    const rows = Array.from(container.querySelectorAll('.item-venda-row'));
    if (rows.length === 0) {
        mostrarNotificacao('Adicione ao menos um item à venda.', 'error');
        return;
    }

    let itens = [];
    let erros = [];
    let totalQtd = 0;
    let totalValor = 0;

    rows.forEach((row, idx) => {
        const produtoId = parseInt(row.querySelector('.item-produto').value) || null;
        const quantidade = parseInt(row.querySelector('.item-quantidade').value) || 0;
        const valorInput = row.querySelector('.item-valor').value || '';

        if (!produtoId || quantidade <= 0) {
            erros.push(`Item ${idx + 1}: produto ou quantidade inválidos.`);
            return;
        }

        const produto = estoque.produtos.find(p => p.id === produtoId);
        if (!produto) {
            erros.push(`Item ${idx + 1}: produto não encontrado.`);
            return;
        }

        // Determinar preço unitário (obrigatório por item)
        let unit = 0;
        if (valorInput && valorInput.trim() !== '') {
            unit = converterMoedaParaNumero(valorInput);
        } else {
            erros.push(`Item ${idx + 1}: informe o valor unitário.`);
            return;
        }

        if (!unit || unit <= 0) {
            erros.push(`Item ${idx + 1}: valor unitário inválido.`);
            return;
        }

        const valorTotalItem = unit * quantidade;

        itens.push({ produtoId: produtoId, produtoNome: produto.nome, quantidade: quantidade, valorUnitario: unit, valorTotal: valorTotalItem });

        totalQtd += quantidade;
        totalValor += valorTotalItem;
    });

    if (erros.length > 0) {
        mostrarNotificacao(erros.join('\n'), 'error');
        return;
    }

    // Se estivermos editando, primeiro reverter os efeitos da venda anterior
    let vendaAnterior = null;
    let vendaAnteriorSnapshot = null;
    if (isEditing) {
        vendaAnterior = estoque.registroVendas.find(v => v.id === vendaEditandoId);
        if (!vendaAnterior) {
            mostrarNotificacao('Venda anterior não encontrada para edição.', 'error');
            vendaEditandoId = null;
            return;
        }
        try { vendaAnteriorSnapshot = JSON.parse(JSON.stringify(vendaAnterior)); } catch (e) { vendaAnteriorSnapshot = null; }
    }

    // Validar estoque antes de salvar (excluir a venda editada do cálculo para não contar duas vezes)
    const validacao = validarEstoqueParaVenda(representante, itens, isEditing ? vendaEditandoId : undefined);
    if (!validacao.valido) {
        let msg = '⚠️ Estoque insuficiente para ' + representante + ':\n\n';
        validacao.erros.forEach(e => { msg += `• ${e.produto}: solicitado ${e.solicitado}, disponível ${e.disponivel}\n`; });
        msg += '\nDeseja registrar mesmo assim?';

        const cancelarCallback = () => {
            if (isEditing) vendaEditandoId = vendaAnterior ? vendaAnterior.id : null;
        };

        mostrarConfirmacaoEstoque(msg, () => {
            finalizarSalvamentoVendaDetalhada({ contrato: contratoFinal, loja, representante, observacoes, itens, totalQtd, totalValor, isEditing, vendaAnterior, vendaAnteriorSnapshot, vendaEditandoIdLocal: vendaEditandoId });
        }, cancelarCallback);

        return;
    }

    // Alerta de estoque baixo (saldo após esta venda < estoqueMin do produto)
    const alertasBaixo = [];
    (itens || []).forEach(it => {
        const produto = (estoque.produtos || []).find(p => p.id === it.produtoId);
        if (!produto) return;
        const repUpper = (representante || '').toUpperCase();
        const distribuido = (estoque.registroDistribuicao || []).reduce((s, d) => {
            if ((d.representante || '').toUpperCase() !== repUpper) return s;
            if (Number(d.produtoId) !== Number(produto.id) && d.produtoNome !== produto.nome) return s;
            return s + (Number(d.quantidade) || 0);
        }, 0) - (estoque.registroDevolucoes || []).reduce((s, d) => {
            if ((d.origem || '').toUpperCase() !== repUpper) return s;
            if (Number(d.produtoId) !== Number(produto.id) && d.produtoNome !== produto.nome) return s;
            return s + (Number(d.quantidade) || 0);
        }, 0);
        const vendidoAtual = (estoque.registroVendas || []).reduce((s, v) => {
            if (v.cancelado) return s;
            if (isEditing && v.id === vendaEditandoId) return s;
            if ((v.representante || '').toUpperCase() !== repUpper) return s;
            return s + vendaItemQtdParaProduto(v, produto);
        }, 0);
        const saldoApos = distribuido - vendidoAtual - (it.quantidade || 0);
        const minAlerta = Number(produto.estoqueMin) || 0;
        if (saldoApos >= 0 && saldoApos <= minAlerta) {
            alertasBaixo.push(`⚠️ ${produto.nome}: restará ${saldoApos} unid. para ${representante} (mín: ${minAlerta})`);
        }
    });
    if (alertasBaixo.length > 0) {
        mostrarNotificacao(alertasBaixo.join('\n'), 'warning');
    }

    // Se válido, finalizar imediatamente
    finalizarSalvamentoVendaDetalhada({ contrato: contratoFinal, loja, representante, observacoes, itens, totalQtd, totalValor, isEditing, vendaAnterior, vendaAnteriorSnapshot, vendaEditandoIdLocal: vendaEditandoId });
}

// ──────────────────────────────────────────────
//  Menu flutuante "⋯" para agrupar ações raras/destrutivas em tabelas densas
//  (ex.: linha de contrato na tabela Vendas/Envio). Um único elemento
//  reaproveitado e reposicionado a cada abertura — mesmo espírito do popup
//  de troca de funil do CRM (crm-ui.js: abrirSeletorFunilNegocio), mas
//  ancorado no botão que o abriu em vez de centralizado na tela.
// ──────────────────────────────────────────────
let _menuAcoesBtnAtivo = null;

function _elMenuAcoesFlutuante() {
    let menu = document.getElementById('menuAcoesFlutuante');
    if (!menu) {
        menu = document.createElement('div');
        menu.id = 'menuAcoesFlutuante';
        menu.className = 'menu-acoes-flutuante';
        document.body.appendChild(menu);
        document.addEventListener('click', (e) => {
            if (_menuAcoesBtnAtivo && !menu.contains(e.target) && e.target !== _menuAcoesBtnAtivo) {
                fecharMenuAcoes();
            }
        }, true);
        window.addEventListener('scroll', () => { if (_menuAcoesBtnAtivo) fecharMenuAcoes(); }, true);
        window.addEventListener('resize', () => { if (_menuAcoesBtnAtivo) fecharMenuAcoes(); });
    }
    return menu;
}

function fecharMenuAcoes() {
    const menu = document.getElementById('menuAcoesFlutuante');
    if (menu) menu.style.display = 'none';
    _menuAcoesBtnAtivo = null;
}

function toggleMenuAcoes(btn, html) {
    const menu = _elMenuAcoesFlutuante();
    if (_menuAcoesBtnAtivo === btn && menu.style.display === 'flex') {
        fecharMenuAcoes();
        return;
    }
    menu.innerHTML = html;
    menu.style.display = 'flex';
    _menuAcoesBtnAtivo = btn;

    const r = btn.getBoundingClientRect();
    const alturaMenu = menu.offsetHeight;
    const espacoAbaixo = window.innerHeight - r.bottom;
    menu.style.top = (espacoAbaixo < alturaMenu + 8 && r.top > alturaMenu)
        ? (r.top - alturaMenu - 4) + 'px'
        : (r.bottom + 4) + 'px';
    const larguraMenu = menu.offsetWidth || 190;
    menu.style.left = Math.max(4, r.right - larguraMenu) + 'px';
}
window.toggleMenuAcoes = toggleMenuAcoes;
window.fecharMenuAcoes = fecharMenuAcoes;

/** Conteúdo do menu "⋯" da linha de contrato em Vendas/Envio — ações raras/destrutivas. */
function htmlMenuAcoesVenda(vendaId, contratoKey, contratoRefEnvio) {
    return `
        <button class="menu-acoes-item" onclick="fecharMenuAcoes(); abrirHistoricoContrato('${contratoKey}')">🕘 Histórico do Contrato</button>
        <button class="menu-acoes-item" onclick="fecharMenuAcoes(); limparControleEnvio('${contratoRefEnvio}')">📭 Limpar dados de envio</button>
        <button class="menu-acoes-item menu-acoes-item-destrutivo" onclick="fecharMenuAcoes(); cancelarContrato('${contratoKey}')">✖ Cancelar contrato</button>
        <button class="menu-acoes-item menu-acoes-item-destrutivo" onclick="fecharMenuAcoes(); excluirVenda(${vendaId})">🗑 Excluir venda</button>
    `;
}
window.htmlMenuAcoesVenda = htmlMenuAcoesVenda;

function renderizarRegistroVendas() {
    const tbody = document.getElementById('tabelaRegistroVendasBody');
    if (!tbody) return;

    const filtroRep = document.getElementById('filtroRepresentante')?.value || '';
    const filtroProduto = document.getElementById('filtroProduto')?.value || '';
    const filtroProdutoId = filtroProduto ? String(filtroProduto) : null;
    // Resolver o nome do produto pelo ID atual (para fallback por nome)
    const filtroProdutoNome = filtroProdutoId
        ? ((estoque.produtos || []).find(p => String(p.id) === filtroProdutoId) || {}).nome || null
        : null;
    const filtroDataInicio = document.getElementById('filtroVendasDataInicio')?.value || '';
    const filtroDataFim = document.getElementById('filtroVendasDataFim')?.value || '';
    const filtroBusca = (document.getElementById('filtroVendasBusca')?.value || '').trim().toLowerCase();
    // Filtros de envio (agora unificados nesta tabela)
    const filtroSistema   = document.getElementById('filtroVendasSistema')?.value   || '';
    const filtroAssinado  = document.getElementById('filtroVendasAssinado')?.value  || '';
    const filtroEnviado   = document.getElementById('filtroVendasEnviado')?.value   || '';
    const filtroProgresso = document.getElementById('filtroVendasProgresso')?.value || '';

    let vendasFiltradas = estoque.registroVendas || [];

    if (filtroRep) {
        vendasFiltradas = vendasFiltradas.filter(v => v.representante === filtroRep);
    }
    if (filtroBusca) {
        vendasFiltradas = vendasFiltradas.filter(v =>
            (v.loja || '').toLowerCase().includes(filtroBusca) ||
            String(v.contrato || '').toLowerCase().includes(filtroBusca)
        );
    }

    // Expandir vendas para linhas de item (cada produto vira uma linha)
    const linhas = [];
    vendasFiltradas.forEach(venda => {
        const dataNorm = parseDateToYYYYMMDD(venda.data) || '';
        if (filtroDataInicio && dataNorm && dataNorm < filtroDataInicio) return;
        if (filtroDataFim && dataNorm && dataNorm > filtroDataFim) return;
        if ((filtroDataInicio || filtroDataFim) && !dataNorm) return;

        const rawContrato = (venda.contrato ?? '').toString().normalize('NFKC');
        const contratoClean = rawContrato.replace(/[\u200B-\u200D\uFEFF\s]+/g, '');
        const somenteDigitos = contratoClean.replace(/\D+/g, '');
        const contratoKey = somenteDigitos ? String(parseInt(somenteDigitos, 10)) : contratoClean.toUpperCase();

        if (Array.isArray(venda.items) && venda.items.length > 0) {
            venda.items.forEach(it => {
                if (filtroProdutoId) {
                    const idOk = String(it.produtoId) === filtroProdutoId;
                    const nomeOk = filtroProdutoNome && (it.produtoNome || '').trim().toUpperCase() === filtroProdutoNome.trim().toUpperCase();
                    if (!idOk && !nomeOk) return;
                }
                const qtd = Number(it.quantidade || 0);
                const valorUnNum = Number(it.valorUnitario || 0);
                const valorTotNum = Number(it.valorTotal || (valorUnNum * qtd) || 0);
                linhas.push({
                    vendaId: venda.id,
                    contratoKey,
                    contratoRaw: venda.contrato,
                    loja: venda.loja || '-',
                    representante: venda.representante || '-',
                    dataNorm,
                    observacoes: venda.observacoes || '-',
                    produtoNome: it.produtoNome || '-',
                    quantidade: qtd,
                    valorUnitario: valorUnNum,
                    valorTotal: valorTotNum
                });
            });
        } else {
            if (filtroProdutoId) {
                const idOk = String(venda.produtoId) === filtroProdutoId;
                const nomeOk = filtroProdutoNome && (venda.produtoNome || '').trim().toUpperCase() === filtroProdutoNome.trim().toUpperCase();
                if (!idOk && !nomeOk) return;
            }
            const qtd = Number(venda.quantidade || 0);
            const valorUnNum = Number(venda.valorUnitario || 0);
            const valorTotNum = Number(venda.valorTotal || (valorUnNum * qtd) || 0);
            linhas.push({
                vendaId: venda.id,
                contratoKey,
                contratoRaw: venda.contrato,
                loja: venda.loja || '-',
                representante: venda.representante || '-',
                dataNorm,
                observacoes: venda.observacoes || '-',
                produtoNome: venda.produtoNome || '-',
                quantidade: qtd,
                valorUnitario: valorUnNum,
                valorTotal: valorTotNum
            });
        }
    });

    // Ordenar conforme seleção do usuário (estado genérico _sortState, fallback para _ordenVendas)
    const sortV = _sortState['vendas'] || { col: _ordenVendas.campo || 'contrato', dir: _ordenVendas.direcao || 'desc' };
    const getValVenda = (l, col) => {
        if (!l) return '';
        if (col === 'contrato') {
            const n = parseInt(l.contratoKey);
            return isNaN(n) ? String(l.contratoKey || '') : n;
        }
        if (col === 'valorTotal') return Number(l.valorTotal || 0);
        if (col === 'quantidade') return Number(l.quantidade || 0);
        if (col === 'data') return l.dataNorm || '';
        if (col === 'loja') return l.loja || '';
        if (col === 'representante') return l.representante || '';
        if (col === 'produtoNome') return l.produtoNome || '';
        return l[col] ?? '';
    };

    const linhasOrdenadas = getSortedArray(linhas, sortV.col, sortV.dir, getValVenda);

    tbody.innerHTML = '';

    if (linhasOrdenadas.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="12" class="empty-state">
                    <div class="empty-icon">📋</div>
                    <div class="empty-text">Nenhuma venda registrada</div>
                    <div class="empty-hint">Clique em "Nova Venda" para adicionar o primeiro registro</div>
                </td>
            </tr>
        `;
        atualizarTotaisVendas(0, 0);
        return;
    }

    let totalQtd = 0;
    let totalValor = 0;

    // Agrupar mantendo a ordem das linhas ordenadas
    const grupos = {};
    const orderedKeys = [];
    linhasOrdenadas.forEach(linha => {
        const k = linha.contratoKey;
        if (!grupos[k]) { grupos[k] = []; orderedKeys.push(k); }
        grupos[k].push(linha);
    });

    // Determinar chaves na ordem apropriada; se o usuário ordenou por 'contrato', ordenar numericamente
    let chavesOrdenadas = orderedKeys.slice();
    if (sortV.col === 'contrato') {
        chavesOrdenadas = Object.keys(grupos).sort((a, b) => {
            const na = parseInt(a);
            const nb = parseInt(b);
            if (!isNaN(na) && !isNaN(nb)) return na - nb;
            return a.localeCompare(b);
        });
        if (sortV.dir === 'desc') chavesOrdenadas.reverse();
    }

    // Remover overlay de debug temporário se existir
    const dbg = document.getElementById('debug-grupos-vendas');
    if (dbg) dbg.remove();

    // Fase 1 (sem DOM): resolve os dados de cada contrato e decide, com base
    // nos filtros de envio, quais grupos entram na tabela — sem ainda criar
    // nenhum elemento. Precisa terminar antes da Fase 2 (render) porque
    // atualizarTotaisVendas/atualizarKPIsVendas dependem do total agregado de
    // TODOS os grupos filtrados, não só do primeiro lote que o LazyLoader
    // desenharia de cara.
    const gruposParaRenderizar = [];
    chavesOrdenadas.forEach(contratoKey => {
        const grupo = grupos[contratoKey] || [];
        const linhasDoContrato = grupo.length;
        if (!linhasDoContrato) return;

        const totalContrato = grupo.reduce((sum, linha) => sum + (Number(linha.valorTotal) || 0), 0);
        const totalQtdContrato = grupo.reduce((sum, linha) => sum + (Number(linha.quantidade) || 0), 0);
        const primeira = grupo[0];
        const minData = grupo.map(g => g.dataNorm).filter(Boolean).sort()[0] || null;
        const maxData = grupo.map(g => g.dataNorm).filter(Boolean).sort().slice(-1)[0] || null;
        const dataDisplay = minData
            ? (maxData && maxData !== minData
                ? `${formatDateToDDMMYYYY(minData)} até ${formatDateToDDMMYYYY(maxData)}`
                : formatDateToDDMMYYYY(minData))
            : '-';
        // verificar se todas as vendas deste contrato estão canceladas
        const vendasDoContrato = (estoque.registroVendas || []).filter(v => normalizarContratoKey(v.contrato) === contratoKey);
        const contratoCancelado = vendasDoContrato.length > 0 && vendasDoContrato.every(v => !!v.cancelado);

        // Quando há filtro por produto ativo, expande automaticamente para mostrar os itens
        const expandido = filtroProdutoId ? true : !!_contratosExpandidos[contratoKey];

        // Dados de envio (chave bruta ou normalizada)
        const envioData = (estoque.controleEnvio || {})[primeira.contratoRaw]
                       || (estoque.controleEnvio || {})[contratoKey]
                       || {};

        // Limpar marcações se cancelado
        if (contratoCancelado && (envioData.sistema || envioData.assinado || envioData.enviado)) {
            envioData.sistema = false;
            envioData.assinado = false;
            envioData.enviado = false;
        }

        const sistemaMarcado  = contratoCancelado ? false : campoMarcado(envioData.sistema);
        const assinadoMarcado = contratoCancelado ? false : campoMarcado(envioData.assinado);
        const enviadoMarcado  = contratoCancelado ? false : campoMarcado(envioData.enviado);
        const qtdConcluidos   = Number(sistemaMarcado) + Number(assinadoMarcado) + Number(enviadoMarcado);

        // Aplicar filtros de envio
        if (filtroSistema   === 'sim' && !sistemaMarcado)  return;
        if (filtroSistema   === 'nao' && sistemaMarcado)   return;
        if (filtroAssinado  === 'sim' && !assinadoMarcado) return;
        if (filtroAssinado  === 'nao' && assinadoMarcado)  return;
        if (filtroEnviado   === 'sim' && !enviadoMarcado)  return;
        if (filtroEnviado   === 'nao' && enviadoMarcado)   return;
        if (filtroProgresso === 'completo' && qtdConcluidos !== 3) return;
        if (filtroProgresso === 'parcial'  && (qtdConcluidos === 0 || qtdConcluidos === 3)) return;
        if (filtroProgresso === 'pendente' && qtdConcluidos !== 0) return;

        totalQtd += totalQtdContrato;
        totalValor += totalContrato;

        gruposParaRenderizar.push({
            contratoKey, grupo, linhasDoContrato, totalContrato, totalQtdContrato,
            primeira, dataDisplay, contratoCancelado, expandido, envioData,
            sistemaMarcado, assinadoMarcado, enviadoMarcado, qtdConcluidos
        });
    });

    try { atualizarKPIsVendas(grupos); } catch (e) { _catchSilencioso(e, 'renderizarRegistroVendas'); }
    atualizarTotaisVendas(totalQtd, totalValor);

    const vendasContador = document.getElementById('vendasContador');
    if (vendasContador) {
        const nContratos = Object.keys(grupos).length;
        vendasContador.textContent = `${nContratos} contrato(s) · ${linhas.length} linha(s)`;
    }
    // Rodapé resumido para o período filtrado
    try {
        const totalFiltrado = linhas.reduce((s, l) => s + (Number(l.valorTotal) || 0), 0);
        const totalUnidades = linhas.reduce((s, l) => s + (Number(l.quantidade) || 0), 0);
        const qtdContratos = new Set(linhas.map(l => l.contratoKey)).size;

        const tfoot = document.querySelector('#tabelaRegistroVendas tfoot') || document.createElement('tfoot');
        const fmtVal = v => formatarMoedaValor(Number(v) || 0);
        tfoot.innerHTML = `
            <tr style="background:#1e3a5f;color:#fff;font-weight:700">
              <td colspan="3" style="padding:10px 14px;text-align:left">📊 ${qtdContratos} contrato(s) · ${linhas.length} linha(s)</td>
              <td style="padding:10px;text-align:center">${totalUnidades}</td>
              <td colspan="2"></td>
              <td style="padding:10px;text-align:right;color:#7ee787;font-size:1rem">${fmtVal(totalFiltrado)}</td>
              <td colspan="5"></td>
            </tr>`;

        const table = document.getElementById('tabelaRegistroVendas') || (tbody && tbody.closest && tbody.closest('table'));
        if (table) {
            const existing = table.querySelector('tfoot');
            if (existing) existing.remove();
            table.appendChild(tfoot);
        }
    } catch (e) { console.warn('Erro ao renderizar rodapé de totais vendas', e); }

    // Fase 2: desenha as linhas em si. Totais/KPIs/rodapé acima já usaram o
    // agregado completo de gruposParaRenderizar — só a criação de elementos
    // DOM é adiada em lotes, exatamente como em _renderUnidade (produtos) e
    // montarRegistrosLazy (Ponto/Registros).
    if (window.LazyLoader) {
        LazyLoader.render(tbody, gruposParaRenderizar, _renderGrupoVenda, {
            chunkSize: 50,
            criarSentinela: function (restantes) {
                const tr = document.createElement('tr');
                tr.className = 'lazy-sentinela';
                const td = document.createElement('td');
                td.colSpan = 12;
                td.style.cssText = 'text-align:center;padding:12px;color:#94a3b8;font-size:0.8rem';
                td.textContent = `Carregando mais contratos... (${restantes} restante${restantes !== 1 ? 's' : ''})`;
                tr.appendChild(td);
                return tr;
            }
        });
    } else {
        gruposParaRenderizar.forEach(_renderGrupoVenda);
    }
}

// Constrói a linha-resumo de um contrato (+ linhas de detalhe por produto,
// se expandido) a partir do objeto pré-computado pela Fase 1 de
// renderizarRegistroVendas — chamada em lotes pelo LazyLoader.render.
function _renderGrupoVenda(dados) {
    const tbody = document.getElementById('tabelaRegistroVendasBody');
    if (!tbody) return;
    const {
        contratoKey, grupo, linhasDoContrato, totalContrato, totalQtdContrato,
        primeira, dataDisplay, contratoCancelado, expandido, envioData,
        sistemaMarcado, assinadoMarcado, enviadoMarcado, qtdConcluidos
    } = dados;

    const repClass = (primeira.representante || '').toLowerCase();
    const cancelBadgeHtml = contratoCancelado ? '<span class="badge-cancelado">CANCELADO</span>' : '';
    const badgeNova = '';

    const progressCor = qtdConcluidos === 3 ? '#2da44e' : qtdConcluidos > 0 ? '#d97706' : '#94a3b8';
    const progressBadge = contratoCancelado ? '' :
        `<span class="ctr-progress" style="background:${progressCor}22;border-color:${progressCor};color:${progressCor}">${qtdConcluidos}/3</span>`;

    const statusBtn = (checked, campo) => {
        if (contratoCancelado) return `<button type="button" class="status-indicator" disabled title="Contrato cancelado" style="opacity:0.3;cursor:not-allowed"><svg viewBox="0 0 12 12" aria-hidden="true"><path fill="white" d="M4.7 9.2 1.9 6.4l1.1-1.1 1.7 1.7 4.2-4.2L10 4z"/></svg></button>`;
        let tooltipTitle = campo;
        if (campo === 'enviado' && checked) {
            const ts = estoque.controleEnvio?.[primeira.contratoRaw || contratoKey]?.emailEnviadoEm;
            if (ts) tooltipTitle = `Email enviado em ${ts}`;
        }
        return `<button type="button" class="status-indicator ${checked ? 'checked' : ''}" onclick="salvarControleEnvio('${primeira.contratoRaw || contratoKey}', '${campo}', ${!checked})" title="${tooltipTitle}"><svg viewBox="0 0 12 12" aria-hidden="true"><path fill="white" d="M4.7 9.2 1.9 6.4l1.1-1.1 1.7 1.7 4.2-4.2L10 4z"/></svg></button>`;
    };

    const resumo = document.createElement('tr');
    resumo.className = 'row-contrato-resumo' + (contratoCancelado ? ' contrato-cancelado' : '');
    if (!contratoCancelado) {
        if (qtdConcluidos === 3) resumo.classList.add('row-envio-completo');
        else if (qtdConcluidos === 0) resumo.classList.add('row-envio-pendente');
    }
    const fallbackYear = primeira.dataNorm ? (primeira.dataNorm.slice(0,4)) : new Date().getFullYear();
    const contratoDisplay = formatarContratoDisplay(primeira.contratoRaw || primeira.contratoKey, fallbackYear);
    let actionsHtml = '';
    if (contratoCancelado) {
        actionsHtml = '<span class="badge-cancelado">CANCELADO</span>';
    } else {
        const emailEnviadoEm = (estoque.controleEnvio?.[primeira.contratoRaw || contratoKey]?.emailEnviadoEm) || '';
        const emailBtnTitle = emailEnviadoEm ? `Email enviado em ${emailEnviadoEm}` : 'Preparar email de pedido';
        const emailBtnStyle = emailEnviadoEm ? 'color:#15803d;border-color:#bbf7d0;background:#f0fdf4' : '';
        // Ações frequentes ficam visíveis; as raras/destrutivas (histórico, cancelar,
        // limpar envio, excluir) vão para o menu "⋯" — eram 7 ícones lado a lado.
        const contratoRefEnvio = primeira.contratoRaw || contratoKey;
        actionsHtml = `<button class="btn-action btn-edit" onclick="abrirModalVendaDetalhada(${primeira.vendaId})" title="Editar venda">✎</button>` +
                      `<button class="btn-contrato-docx" onclick="gerarContratoVenda('${primeira.vendaId || primeira.contratoRaw}')" title="Gerar contrato .docx">📄</button>` +
                      `<button class="btn-action" onclick="prepararEmailPorContrato('${contratoRefEnvio}')" title="${emailBtnTitle}" style="${emailBtnStyle}">✉️</button>` +
                      `<button class="btn-action" onclick="toggleMenuAcoes(this, htmlMenuAcoesVenda(${primeira.vendaId}, '${contratoKey}', '${contratoRefEnvio}'))" title="Mais ações">⋯</button>`;
    }

    resumo.innerHTML = `
        <td class="col-contrato">
            <div class="ctr-cell">
                <span class="link-contrato" title="${contratoDisplay}">${contratoDisplay || '-'}</span>
                ${progressBadge}
            </div>
            ${cancelBadgeHtml}${badgeNova}
        </td>
        <td class="col-loja" title="${primeira.loja}">${primeira.loja}</td>
        <td class="col-representante"><span class="badge-rep ${repClass}">${primeira.representante}</span></td>
        <td class="col-produto-venda">${
            linhasDoContrato === 1
                ? `<span class="prod-nome-inline">${grupo[0].produtoNome}</span>`
                : `<button class="btn-expand-contrato expand-btn-prod" onclick="toggleContratoExpandido('${contratoKey}')">
                    <span class="expand-chevron ${expandido ? 'open' : ''}">▶</span>
                    <span class="expand-count">${linhasDoContrato} produtos</span>
                    <span class="expand-preview">${grupo.map(p => p.produtoNome.split(' ').slice(0,2).join(' ')).join(' · ')}</span>
                    ${!expandido ? `<span class="prod-mais-wrap"><span class="prod-mais-chip">+${linhasDoContrato - 1}</span><span class="prod-mais-tooltip">${grupo.slice(1).map(p => `<span class="prod-mais-row"><span class="prod-mais-nome">${p.produtoNome}</span><span class="prod-mais-qty">× ${p.quantidade}</span></span>`).join('')}</span></span>` : ''}
                   </button>`
        }</td>
        <td class="col-qtd">${totalQtdContrato}</td>
        <td class="col-valor-total">${formatarMoedaValor(totalContrato)}</td>
        <td class="col-data">${dataDisplay}</td>
        <td class="col-sistema">${statusBtn(sistemaMarcado, 'sistema')}</td>
        <td class="col-assinado">${statusBtn(assinadoMarcado, 'assinado')}</td>
        <td class="col-enviado">${statusBtn(enviadoMarcado, 'enviado')}</td>
        <td class="col-solicitacao">
            <input type="text" class="campo-editavel" value="${envioData.solicitacao || ''}" placeholder="Data ou obs." onchange="salvarControleEnvio('${primeira.contratoRaw || contratoKey}', 'solicitacao', this.value)" ${contratoCancelado ? 'disabled style="opacity:0.4;cursor:not-allowed"' : ''}>
        </td>
        <td class="col-acoes">${actionsHtml}</td>
    `;
    tbody.appendChild(resumo);

    grupo.forEach((linha) => {
        const tr = document.createElement('tr');
        tr.className = `row-contrato-detalhe sub-linha-produto ${expandido ? '' : 'hidden-row'}`;
        const valorUn = linha.valorUnitario ? formatarMoedaValor(linha.valorUnitario) : '-';

        // verificar se a venda específica está cancelada
        const vendaObj = estoque.registroVendas.find(v => v.id === linha.vendaId);
        const isLinhaCancelada = vendaObj && vendaObj.cancelado;
        const detalheAcoesHtml = isLinhaCancelada ? '<span class="badge-cancelado">CANCELADO</span>' : '';

        tr.innerHTML = `
            <td class="col-contrato detalhe-vazio"></td>
            <td class="col-loja detalhe-vazio" title="${linha.observacoes || ''}"><span style="color:#64748b;font-size:0.8rem">${linha.observacoes && linha.observacoes !== '-' ? linha.observacoes : ''}</span></td>
            <td class="col-representante detalhe-vazio"></td>
            <td class="col-produto-venda sub-td" title="${linha.produtoNome}"><div class="sub-prod-nome"><span class="sub-prod-hierarchy">└</span>${linha.produtoNome}</div></td>
            <td class="col-qtd sub-td sub-td-mono">${linha.quantidade}</td>
            <td class="col-valor-total sub-td"><div class="sub-prod-valor"><span class="sub-prod-valor-unit">${valorUn}</span><span class="sub-prod-valor-formula">unit. × ${linha.quantidade}</span></div></td>
            <td class="col-data" style="font-size:0.8rem">${linha.dataNorm ? formatDateToDDMMYYYY(linha.dataNorm) : '-'}</td>
            <td class="col-sistema detalhe-vazio"></td>
            <td class="col-assinado detalhe-vazio"></td>
            <td class="col-enviado detalhe-vazio"></td>
            <td class="col-solicitacao detalhe-vazio"></td>
            <td class="col-acoes">${detalheAcoesHtml}</td>
        `;

        tbody.appendChild(tr);
    });
}

function atualizarTotaisVendas(totalQtd, totalValor) {
    const spanQtd = document.getElementById('totalQtdVendas');
    const spanValor = document.getElementById('totalValorVendas');
    
    if (spanQtd) spanQtd.innerHTML = `<strong>${totalQtd.toLocaleString('pt-BR')}</strong>`;
    if (spanValor) spanValor.innerHTML = `<strong>${formatarMoedaValor(totalValor)}</strong>`;
}

function toggleContratoExpandido(contratoKey) {
    _contratosExpandidos[contratoKey] = !_contratosExpandidos[contratoKey];
    renderizarRegistroVendas();
}

function expandirTodosContratos() {
    (estoque.registroVendas || []).forEach(v => {
        const k = normalizarContratoKey(v.contrato);
        if (k) _contratosExpandidos[k] = true;
    });
    renderizarRegistroVendas();
}

function colapsarTodosContratos() {
    _contratosExpandidos = {};
    renderizarRegistroVendas();
}

function atualizarKPIsVendas(grupos) {
    const todasVendas = estoque.registroVendas || [];
    let ativos = 0, cancelados = 0, totalAtivo = 0;
    Object.keys(grupos).forEach(k => {
        const vendas = todasVendas.filter(v => normalizarContratoKey(v.contrato) === k);
        const todoCancelado = vendas.length > 0 && vendas.every(v => !!v.cancelado);
        if (todoCancelado) {
            cancelados++;
        } else {
            ativos++;
            totalAtivo += grupos[k].reduce((s, l) => s + (Number(l.valorTotal) || 0), 0);
        }
    });
    const ticket = ativos > 0 ? totalAtivo / ativos : 0;
    const el = id => document.getElementById(id);
    if (el('kpiVendasContratos')) el('kpiVendasContratos').textContent = ativos;
    if (el('kpiVendasTotal')) el('kpiVendasTotal').textContent = formatarMoedaValor(totalAtivo);
    if (el('kpiVendasTicket')) el('kpiVendasTicket').textContent = formatarMoedaValor(ticket);
    if (el('kpiVendasCancelados')) el('kpiVendasCancelados').textContent = cancelados;
}

function abrirHistoricoContrato(contratoInformado = '') {
    const contrato = (contratoInformado || prompt('Informe o contrato para visualizar o histórico:') || '').trim();
    if (!contrato) return;

    const contratoKey = normalizarContratoKey(contrato);

    // --- Dados da venda ---
    const vendasContrato = (estoque.registroVendas || []).filter(v => normalizarContratoKey(v.contrato) === contratoKey);
    const primeira = vendasContrato[0] || {};
    const contratoCancelado = vendasContrato.length > 0 && vendasContrato.every(v => !!v.cancelado);

    // --- Título ---
    const tituloEl = document.getElementById('modalHistoricoTitulo');
    if (tituloEl) {
        const contratoDisplay = primeira.contrato || contrato;
        tituloEl.innerHTML = `Contrato ${contratoDisplay}${contratoCancelado ? ' <span class="badge-cancelado">CANCELADO</span>' : ''}`;
    }

    // --- Resumo ---
    const resumoEl = document.getElementById('historicoResumo');
    if (resumoEl) {
        if (primeira.contrato) {
            const totalQtd = vendasContrato.reduce((s, v) => s + (Array.isArray(v.items) ? v.items.reduce((si, it) => si + (it.quantidade || 0), 0) : (v.quantidade || 0)), 0);
            const totalVal = vendasContrato.reduce((s, v) => s + (v.valorTotal || (Array.isArray(v.items) ? v.items.reduce((si, it) => si + (it.valorTotal || 0), 0) : 0)), 0);
            const dataStr = primeira.data ? new Date(primeira.data).toLocaleDateString('pt-BR') : '-';
            const repClass = (primeira.representante || '').toLowerCase();
            resumoEl.innerHTML = `
                <div><span style="color:var(--text-secondary);font-size:0.78rem">LOJA</span><br><strong>${primeira.loja || '-'}</strong></div>
                <div><span style="color:var(--text-secondary);font-size:0.78rem">REPRESENTANTE</span><br><span class="badge-rep ${repClass}">${primeira.representante || '-'}</span></div>
                <div><span style="color:var(--text-secondary);font-size:0.78rem">DATA</span><br><strong>${dataStr}</strong></div>
                <div><span style="color:var(--text-secondary);font-size:0.78rem">QTD TOTAL</span><br><strong>${totalQtd}</strong></div>
                <div><span style="color:var(--text-secondary);font-size:0.78rem">VALOR TOTAL</span><br><strong>${formatarMoedaValor(totalVal)}</strong></div>
                ${primeira.observacoes ? `<div><span style="color:var(--text-secondary);font-size:0.78rem">OBS</span><br>${primeira.observacoes}</div>` : ''}
            `;
        } else {
            resumoEl.innerHTML = `<span style="color:var(--text-secondary)">Nenhuma venda ativa encontrada para este contrato.</span>`;
        }
    }

    // --- Status de envio ---
    const envioEl = document.getElementById('historicoEnvio');
    if (envioEl) {
        const envioData = (estoque.controleEnvio || {})[primeira.contrato] || (estoque.controleEnvio || {})[contratoKey] || {};
        const checks = [
            { label: 'Sistema', campo: 'sistema' },
            { label: 'Assinado', campo: 'assinado' },
            { label: 'Enviado', campo: 'enviado' }
        ];
        const statusHtml = checks.map(c => {
            const ok = campoMarcado(envioData[c.campo]);
            return `<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:20px;font-size:0.8rem;font-weight:600;background:${ok ? '#f0fdf4' : '#f8fafc'};border:1px solid ${ok ? '#86efac' : '#e2e8f0'};color:${ok ? '#16a34a' : '#94a3b8'}">
                ${ok ? '✓' : '○'} ${c.label}
            </span>`;
        }).join('');
        const solicitacao = envioData.solicitacao ? `<span style="font-size:0.8rem;color:var(--text-secondary);margin-left:8px">📅 ${envioData.solicitacao}</span>` : '';
        envioEl.innerHTML = `<span style="font-size:0.78rem;color:var(--text-secondary);margin-right:4px">ENVIO:</span>${statusHtml}${solicitacao}`;
    }

    // --- Itens da venda ---
    const itensEl = document.getElementById('historicoItens');
    if (itensEl) {
        const todosItens = [];
        vendasContrato.forEach(v => {
            if (Array.isArray(v.items) && v.items.length) {
                v.items.forEach(it => todosItens.push({ nome: it.produtoNome || it.produto || '-', qtd: it.quantidade || 0, valor: it.valorTotal || ((it.valorUnitario || 0) * (it.quantidade || 0)) }));
            } else if (v.produtoNome) {
                todosItens.push({ nome: v.produtoNome, qtd: v.quantidade || 0, valor: v.valorTotal || 0 });
            }
        });
        if (todosItens.length) {
            itensEl.innerHTML = `<p style="font-size:0.78rem;color:var(--text-secondary);margin:0 0 6px">ITENS</p>` +
                todosItens.map(it => `<div style="display:flex;justify-content:space-between;font-size:0.83rem;padding:3px 0;border-bottom:1px solid var(--border-color)">
                    <span>${it.nome}</span>
                    <span style="color:var(--text-secondary)">${it.qtd} × ${formatarMoedaValor(it.valor / (it.qtd || 1))} = <strong>${formatarMoedaValor(it.valor)}</strong></span>
                </div>`).join('');
        } else {
            itensEl.innerHTML = '';
        }
    }

    // --- Auditoria ---
    const auditoriaEl = document.getElementById('historicoConteudo');
    if (auditoriaEl) {
        const lista = obterAuditoriaPorContrato(contratoKey);
        if (lista.length === 0) {
            auditoriaEl.innerHTML = `<p style="text-align:center;color:var(--text-secondary);padding:12px;font-size:0.82rem">Nenhum histórico de auditoria para este contrato.</p>`;
        } else {
            auditoriaEl.innerHTML = `<p style="font-size:0.78rem;color:var(--text-secondary);margin:0 0 6px">HISTÓRICO DE ALTERAÇÕES</p>` +
                lista.map(h => {
                    const dt = h.quando ? new Date(h.quando).toLocaleString('pt-BR') : '-';
                    const acao = (h.acao || '-').toUpperCase();
                    const desc = h.detalhes || '-';
                    return `<div class="historico-item">
                        <span class="hist-data">${dt}<br><small>${h.quem || 'Usuário'}</small></span>
                        <span class="hist-tipo venda">${acao}</span>
                        <span class="hist-descricao">${desc}</span>
                    </div>`;
                }).join('');
        }
    }

    document.getElementById('modalHistorico').style.display = 'flex';
}

