function limparTodosDados() {
    if (!confirm('⚠️ ATENÇÃO!\n\nEsta ação irá APAGAR TODOS os dados do sistema:\n- Produtos\n- Distribuições\n- Vendas\n- Registro de vendas\n- Registro de distribuição\n\nOs dados serão resetados para os valores iniciais.\n\nDeseja continuar?')) {
        return;
    }
    
    if (!confirm('ÚLTIMA CONFIRMAÇÃO:\n\nVocê tem certeza absoluta? Esta ação não pode ser desfeita!')) {
        return;
    }
    
    // Remover do localStorage
    localStorage.removeItem('estoqueArmasV2');
    
    // Recarregar dados iniciais
    estoque.produtos = dadosIniciais.map((item, index) => ({
        id: index + 1,
        nome: item.nome,
        preco: item.preco,
        distribuicao: { KOLTE: 0, ISA: 0, LC: 0, ADES: 0, FL: 0, IMBEL: 0 },
        vendas: { KOLTE: 0, ISA: 0, LC: 0, ADES: 0, FL: 0, IMBEL: 0 }
    }));
    estoque.registroVendas = [];
    estoque.registroDistribuicao = [];
    estoque.controleEnvio = {};
    estoque.clientes = [];
    clientes = estoque.clientes;
    estoque.propostas = [];
    propostas = estoque.propostas;
    estoque.precificacao = {};
    precificacoesCliente = [];
    estoque.precificacoesCliente = [];
    estoque.precificacaoConfig = null;
    precificacao = estoque.precificacao;
    tabelaAliquotas = {};
    tabelaICMS = [];
    categoriaPorProduto = {};
    // Limpar tabelas de impostos editáveis
    impostosEditaveis = {};
    icmsEditavelPJ = {};
    icmsEditavelPF = {};
    
    salvarDados();
    renderizarTabela();
    renderizarDashboard();
    renderizarRegistroVendas();
    renderizarRegistroDistribuicao();
    renderizarControleEnvio();
    renderizarClientes();
    atualizarKPIsClientes();
    atualizarDatalistClientes();
    renderizarPropostas();
    atualizarKPIsPropostas();
    renderizarPrecificacao();
    atualizarSelectsProdutos();
    try { atualizarEstatisticas(); } catch (e) { _catchSilencioso(e, 'limparTodosDados'); }

    mostrarNotificacao('Todos os dados foram apagados!', 'success');
}

// ========================================
// CONTROLE DE ENVIO DE CONTRATOS
// ========================================

function campoMarcado(valor) {
    return valor === true || valor === 'Sim' || valor === 'SAP' || valor === 'Outro' || valor === 'true' || (typeof valor === 'string' && valor.length > 0);
}

function renderizarControleEnvio() {
    const tbody = document.getElementById('tabelaControleEnvioBody');
    if (!tbody) return;

    const filtroRep = document.getElementById('filtroControleEnvioRep')?.value || '';
    const filtroSistema = document.getElementById('filtroControleEnvioSistema')?.value || '';
    const filtroAssinado = document.getElementById('filtroControleEnvioAssinado')?.value || '';
    const filtroEnviado = document.getElementById('filtroControleEnvioEnviado')?.value || '';
    const filtroProgresso = document.getElementById('filtroControleEnvioProgresso')?.value || '';
    const filtroBusca = (document.getElementById('filtroControleEnvioBusca')?.value || '').trim().toLowerCase();

    // Agrupa vendas por contrato (pega a primeira ocorrência de cada contrato)
    const contratoMap = {};
    estoque.registroVendas.forEach(venda => {
        if (!contratoMap[venda.contrato]) {
            contratoMap[venda.contrato] = {
                contrato: venda.contrato,
                loja: venda.loja,
                representante: venda.representante,
                id: venda.id,
                cancelado: false
            };
        }
        // marca cancelado se TODAS as vendas do contrato estiverem canceladas
        if (!venda.cancelado) contratoMap[venda.contrato].cancelado = false;
    });
    // segunda passagem: confirma cancelado só se todas as vendas estiverem canceladas
    Object.keys(contratoMap).forEach(k => {
        const vendasDoContrato = estoque.registroVendas.filter(v => v.contrato === k);
        contratoMap[k].cancelado = vendasDoContrato.length > 0 && vendasDoContrato.every(v => !!v.cancelado);
    });

    let contratos = Object.values(contratoMap);

    if (filtroRep) {
        contratos = contratos.filter(c => c.representante === filtroRep);
    }
    if (filtroBusca) {
        contratos = contratos.filter(c =>
            String(c.contrato || '').toLowerCase().includes(filtroBusca) ||
            (c.loja || '').toLowerCase().includes(filtroBusca)
        );
    }

    contratos = contratos.filter(c => {
        const envio = estoque.controleEnvio[c.contrato] || {};
        const sistemaMarcado = campoMarcado(envio.sistema);
        const assinadoMarcado = campoMarcado(envio.assinado);
        const enviadoMarcado = campoMarcado(envio.enviado);
        const concluidos = Number(sistemaMarcado) + Number(assinadoMarcado) + Number(enviadoMarcado);

        if (filtroSistema === 'sim' && !sistemaMarcado) return false;
        if (filtroSistema === 'nao' && sistemaMarcado) return false;
        if (filtroAssinado === 'sim' && !assinadoMarcado) return false;
        if (filtroAssinado === 'nao' && assinadoMarcado) return false;
        if (filtroEnviado === 'sim' && !enviadoMarcado) return false;
        if (filtroEnviado === 'nao' && enviadoMarcado) return false;
        if (filtroProgresso === 'completo' && concluidos !== 3) return false;
        if (filtroProgresso === 'parcial' && (concluidos === 0 || concluidos === 3)) return false;
        if (filtroProgresso === 'pendente' && concluidos !== 0) return false;

        return true;
    });

    contratos = contratos.sort((a, b) => {
        const contratoA = parseInt(a.contrato) || 0;
        const contratoB = parseInt(b.contrato) || 0;
        return contratoB - contratoA;
    });

    tbody.innerHTML = '';

    // KPIs
    const totalContratos = contratos.length;
    let concluidos = 0, enviados = 0, pendentes = 0;
    contratos.forEach(c => {
        const envio = estoque.controleEnvio[c.contrato] || {};
        const s = campoMarcado(envio.sistema);
        const a = campoMarcado(envio.assinado);
        const e = campoMarcado(envio.enviado);
        const cnt = Number(s) + Number(a) + Number(e);
        if (cnt === 3) concluidos++;
        if (e) enviados++;
        if (cnt === 0) pendentes++;
    });
    const el = id => document.getElementById(id);
    if (el('kpiEnvioTotal')) el('kpiEnvioTotal').textContent = totalContratos;
    if (el('kpiEnvioConcluidos')) el('kpiEnvioConcluidos').textContent = concluidos;
    if (el('kpiEnvioEnviados')) el('kpiEnvioEnviados').textContent = enviados;
    if (el('kpiEnvioPendentes')) el('kpiEnvioPendentes').textContent = pendentes;
    const pctConcluidos = totalContratos > 0 ? Math.round((concluidos / totalContratos) * 100) : 0;
    if (el('kpiEnvioProgressBar')) el('kpiEnvioProgressBar').style.width = pctConcluidos + '%';
    if (el('kpiEnvioProgressLabel')) el('kpiEnvioProgressLabel').textContent = `${concluidos} de ${totalContratos} concluídos (${pctConcluidos}%)`;
    if (el('envioContador')) el('envioContador').textContent = `${totalContratos} contrato(s)`;

    if (contratos.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="8" class="empty-state">
                    <div class="empty-icon">📮</div>
                    <div class="empty-text">Nenhum contrato encontrado</div>
                    <div class="empty-hint">Ajuste os filtros ou registre vendas na aba "Registro de Vendas"</div>
                </td>
            </tr>
        `;
        return;
    }

    let houveLimpeza = false;
    contratos.forEach(contrato => {
        const contratoCancelado = !!contrato.cancelado;
        const envio = estoque.controleEnvio[contrato.contrato] || {};

        // Se cancelado e tiver marcações, limpa silenciosamente
        if (contratoCancelado && estoque.controleEnvio[contrato.contrato] &&
            (envio.sistema || envio.assinado || envio.enviado)) {
            estoque.controleEnvio[contrato.contrato].sistema = false;
            estoque.controleEnvio[contrato.contrato].assinado = false;
            estoque.controleEnvio[contrato.contrato].enviado = false;
            houveLimpeza = true;
        }

        const sistemaMarcado = contratoCancelado ? false : campoMarcado(envio.sistema);
        const assinadoMarcado = contratoCancelado ? false : campoMarcado(envio.assinado);
        const enviadoMarcado = contratoCancelado ? false : campoMarcado(envio.enviado);
        const repClass = (contrato.representante || '').toLowerCase();
        const qtdConcluidos = Number(sistemaMarcado) + Number(assinadoMarcado) + Number(enviadoMarcado);

        const progressCor = qtdConcluidos === 3 ? '#2da44e' : qtdConcluidos > 0 ? '#d97706' : '#94a3b8';

        const statusBtn = (checked, campo) => contratoCancelado
            ? `<button type="button" class="status-indicator" disabled title="Contrato cancelado" style="opacity:0.3;cursor:not-allowed">
                <svg viewBox="0 0 12 12" aria-hidden="true"><path fill="white" d="M4.7 9.2 1.9 6.4l1.1-1.1 1.7 1.7 4.2-4.2L10 4z"/></svg>
               </button>`
            : `<button type="button" class="status-indicator ${checked ? 'checked' : ''}" onclick="salvarControleEnvio('${contrato.contrato}', '${campo}', ${!checked})" title="${campo}">
                <svg viewBox="0 0 12 12" aria-hidden="true"><path fill="white" d="M4.7 9.2 1.9 6.4l1.1-1.1 1.7 1.7 4.2-4.2L10 4z"/></svg>
               </button>`;
        const tr = document.createElement('tr');
        if (contratoCancelado) tr.classList.add('contrato-cancelado');
        else if (qtdConcluidos === 3) tr.classList.add('row-envio-completo');
        else if (qtdConcluidos === 0) tr.classList.add('row-envio-pendente');
        const canceladoBadge = contratoCancelado ? ' <span class="badge-cancelado">CANCELADO</span>' : '';
        tr.innerHTML = `
            <td class="col-contrato">
                <div class="ctr-cell">
                    <span class="link-contrato" onclick="irParaRegistroVendas('${contrato.contrato}')" title="Ver no Registro de Vendas" style="font-weight:700">${contrato.contrato}</span>${canceladoBadge}
                    ${contratoCancelado ? '' : `<span class="ctr-progress" style="background:${progressCor}22;border-color:${progressCor};color:${progressCor}">${qtdConcluidos}/3</span>`}
                </div>
            </td>
            <td class="col-loja" title="${contrato.loja}">${contrato.loja}</td>
            <td class="col-representante"><span class="badge-rep ${repClass}">${contrato.representante}</span></td>
            <td class="col-sistema">${statusBtn(sistemaMarcado, 'sistema')}</td>
            <td class="col-assinado">${statusBtn(assinadoMarcado, 'assinado')}</td>
            <td class="col-enviado">${statusBtn(enviadoMarcado, 'enviado')}</td>
            <td class="col-solicitacao">
                <input type="text" class="campo-editavel" value="${envio.solicitacao || ''}" placeholder="Data ou observação" onchange="salvarControleEnvio('${contrato.contrato}', 'solicitacao', this.value)" ${contratoCancelado ? 'disabled style="opacity:0.4;cursor:not-allowed"' : ''}>
            </td>
            <td class="col-acoes">
                <button class="btn-action btn-delete" onclick="limparControleEnvio('${contrato.contrato}')" title="Limpar dados" ${contratoCancelado ? 'disabled style="opacity:0.3;cursor:not-allowed"' : ''}>🗑</button>
            </td>
        `;
        tbody.appendChild(tr);
    });

    if (houveLimpeza) salvarDados();
}

function irParaControleEnvio(contrato) {
    // Controle de Envio unificado — navegar para a linha na tabela de Vendas/Envio
    trocarAba('vendas');
    setTimeout(() => {
        const rows = document.querySelectorAll('#tabelaRegistroVendasBody tr.row-contrato-resumo');
        for (const row of rows) {
            const cell = row.querySelector('.col-contrato');
            if (cell && cell.textContent.includes(contrato)) {
                row.scrollIntoView({ behavior: 'smooth', block: 'center' });
                row.classList.add('highlight-row');
                setTimeout(() => row.classList.remove('highlight-row'), 1200);
                break;
            }
        }
    }, 150);
}

function irParaRegistroVendas(contrato) {
    trocarAba('vendas');
    setTimeout(() => {
        const rows = document.querySelectorAll('#tabelaRegistroVendasBody tr.row-contrato-resumo');
        for (const row of rows) {
            const cell = row.querySelector('.col-contrato');
            if (cell && cell.textContent.includes(contrato)) {
                row.scrollIntoView({ behavior: 'smooth', block: 'center' });
                row.classList.add('highlight-row');
                setTimeout(() => row.classList.remove('highlight-row'), 1200);
                break;
            }
        }
    }, 150);
}

function salvarControleEnvio(contrato, campo, valor) {
    if (!estoque.controleEnvio[contrato]) {
        estoque.controleEnvio[contrato] = {};
    }

    if (campo === 'sistema' || campo === 'assinado' || campo === 'enviado') {
        valor = Boolean(valor);
    }
    
    estoque.controleEnvio[contrato][campo] = valor;
    salvarDados();
    // Re-renderizar a tabela unificada
    try { renderizarRegistroVendas(); } catch (e) { _catchSilencioso(e, 'salvarControleEnvio'); }
}

function limparFiltrosControleEnvio() {
    ['filtroControleEnvioRep','filtroControleEnvioSistema','filtroControleEnvioAssinado',
     'filtroControleEnvioEnviado','filtroControleEnvioProgresso','filtroControleEnvioBusca']
        .forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
    renderizarControleEnvio();
}

function limparControleEnvio(contrato) {
    if (confirm(`Deseja limpar os dados de envio do contrato ${contrato}?`)) {
        delete estoque.controleEnvio[contrato];
        salvarDados();
        try { renderizarRegistroVendas(); } catch (e) { _catchSilencioso(e, 'limparControleEnvio'); }
        mostrarNotificacao(`Dados de envio do contrato ${contrato} removidos`, 'success');
    }
}

function exportarControleEnvio() {
    const contratoMap = {};
    
    estoque.registroVendas.forEach(venda => {
        if (!contratoMap[venda.contrato]) {
            contratoMap[venda.contrato] = {
                contrato: venda.contrato,
                loja: venda.loja,
                representante: venda.representante
            };
        }
    });

    const contratos = Object.values(contratoMap).sort((a, b) => {
        const contratoA = parseInt(a.contrato) || 0;
        const contratoB = parseInt(b.contrato) || 0;
        return contratoA - contratoB;
    });

    const dados = contratos.map(c => {
        const envio = estoque.controleEnvio[c.contrato] || {};
        const sistemaMarcado = campoMarcado(envio.sistema);
        return {
            'CTR': c.contrato,
            'NOME': c.loja,
            'REPRESENTANTE': c.representante,
            'SISTEMA': sistemaMarcado ? 'Sim' : 'Não',
            'ASSINADO': envio.assinado ? 'Sim' : 'Não',
            'ENVIADO': envio.enviado ? 'Sim' : 'Não',
            'SOLICITAÇÃO': envio.solicitacao || ''
        };
    });

    const csv = gerarCSV(dados);
    const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `Controle_Envio_${new Date().toLocaleDateString('pt-BR').replace(/\//g, '-')}.csv`;
    link.click();
}

function importarControleEnvioArquivo(event) {
    const file = event.target.files[0];
    event.target.value = '';
    if (!file) return;

    const ext = file.name.split('.').pop().toLowerCase();
    const isXlsx = ext === 'xlsx' || ext === 'xls';

    const processarLinhas = (linhas) => {
        if (linhas.length < 2) {
            alert('Arquivo sem dados.');
            return;
        }

        // detectar separador (ponto-e-vírgula ou vírgula)
        const sep = linhas[0].includes(';') ? ';' : ',';
        const parseRow = (linha) => {
            const cols = [];
            let cur = '', inQ = false;
            for (let i = 0; i < linha.length; i++) {
                const ch = linha[i];
                if (ch === '"') { inQ = !inQ; }
                else if (ch === sep && !inQ) { cols.push(cur.trim()); cur = ''; }
                else { cur += ch; }
            }
            cols.push(cur.trim());
            return cols;
        };

        const headers = parseRow(linhas[0]).map(h => h.replace(/^"|"$/g, '').toLowerCase().trim());
        const idx = (nome) => headers.findIndex(h => h === nome || h === nome.replace('ã','a').replace('ç','c'));

        const iCtr       = idx('ctr');
        const iSistema   = idx('sistema');
        const iAssinado  = idx('assinado');
        const iEnviado   = idx('enviado');
        const iSolic     = idx('solicitação') !== -1 ? idx('solicitação') : idx('solicitacao');

        if (iCtr === -1) {
            alert('Coluna "CTR" não encontrada. Use o arquivo exportado pelo sistema.');
            return;
        }

        let importados = 0, ignorados = 0;

        const ehSim = (v) => {
            const s = (v || '').toLowerCase().trim();
            return s === 'sim' || s === '1' || s === 'true' || s === 'x';
        };
        // Se já há data gravada e o excel confirma "Sim", preserva a data original.
        // Se excel diz "Sim" e não há data, registra agora. Se diz "Não", limpa.
        const resolverCampo = (valorExcel, valorAtual) => {
            if (ehSim(valorExcel)) return valorAtual !== undefined && valorAtual !== '' ? valorAtual : true;
            return '';
        };

        linhas.slice(1).forEach(linha => {
            if (!linha.trim()) return;
            const cols = parseRow(linha).map(c => c.replace(/^"|"$/g, '').trim());
            const contrato = cols[iCtr] || '';
            if (!contrato) { ignorados++; return; }

            if (!estoque.controleEnvio) estoque.controleEnvio = {};
            const atual = estoque.controleEnvio[contrato] || {};

            estoque.controleEnvio[contrato] = {
                sistema:     iSistema  !== -1 ? resolverCampo(cols[iSistema],  atual.sistema)  : (atual.sistema  || ''),
                assinado:    iAssinado !== -1 ? resolverCampo(cols[iAssinado], atual.assinado) : (atual.assinado || ''),
                enviado:     iEnviado  !== -1 ? resolverCampo(cols[iEnviado],  atual.enviado)  : (atual.enviado  || ''),
                solicitacao: iSolic    !== -1 ? (cols[iSolic] || atual.solicitacao || '')       : (atual.solicitacao || '')
            };

            importados++;
        });

        salvarDados();
        renderizarControleEnvio();
        alert(`Importação concluída: ${importados} contrato(s) atualizados${ignorados ? ', ' + ignorados + ' ignorados' : ''}.`);
    };

    if (isXlsx) {
        if (typeof XLSX === 'undefined') {
            alert('Biblioteca XLSX não carregada. Use o formato CSV.');
            return;
        }
        const reader = new FileReader();
        reader.onload = (e) => {
            const wb = XLSX.read(e.target.result, { type: 'array' });
            const ws = wb.Sheets[wb.SheetNames[0]];
            const csv = XLSX.utils.sheet_to_csv(ws, { FS: ';' });
            processarLinhas(csv.split('\n'));
        };
        reader.readAsArrayBuffer(file);
    } else {
        const reader = new FileReader();
        reader.onload = (e) => {
            const text = e.target.result;
            processarLinhas(text.split('\n'));
        };
        reader.readAsText(file, 'UTF-8');
    }
}

function gerarCSV(dados) {
    if (!dados || dados.length === 0) return '';
    
    const headers = Object.keys(dados[0]);
    const csv = [
        headers.join(';'),
        ...dados.map(row => headers.map(header => `"${(row[header] || '').toString().replace(/"/g, '""')}"`).join(';'))
    ].join('\n');
    
    return csv;
}

